fn diagnose_proposal_review_queue(
    review_queue: WorkspacePatchReviewQueueSummary,
) -> WorkspacePatchReviewQueueDiagnosticsSummary {
    let mut checks = Vec::new();

    let actual_complete = review_queue
        .items
        .iter()
        .filter(|item| item.report_status == "Complete")
        .count();
    let actual_blocked = review_queue
        .items
        .iter()
        .filter(|item| item.report_status == "Blocked")
        .count();
    let actual_needs_action = review_queue
        .items
        .len()
        .saturating_sub(actual_complete)
        .saturating_sub(actual_blocked);

    push_queue_diagnostics_check(
        &mut checks,
        "queue_counts_match_item_statuses",
        review_queue.proposal_count == review_queue.items.len()
            && review_queue.complete_count == actual_complete
            && review_queue.needs_action_count == actual_needs_action
            && review_queue.blocked_count == actual_blocked,
        "queue counts match item statuses",
        format!(
            "queue counts do not match items: proposals={} items={} complete={}/{} needs_action={}/{} blocked={}/{}",
            review_queue.proposal_count,
            review_queue.items.len(),
            review_queue.complete_count,
            actual_complete,
            review_queue.needs_action_count,
            actual_needs_action,
            review_queue.blocked_count,
            actual_blocked
        ),
    );

    let expected_queue_status = if review_queue.blocked_count > 0 {
        "Blocked"
    } else if review_queue.needs_action_count > 0 {
        "NeedsAction"
    } else {
        "Complete"
    };
    push_queue_diagnostics_check(
        &mut checks,
        "queue_status_matches_item_reports",
        review_queue.queue_status == expected_queue_status,
        "queue status matches item report statuses",
        format!(
            "queue status {} does not match expected {}",
            review_queue.queue_status, expected_queue_status
        ),
    );

    push_queue_diagnostics_check(
        &mut checks,
        "items_never_authorize_apply",
        review_queue.items.iter().all(|item| !item.apply_authorized),
        "all queue items keep apply_authorized=false",
        "one or more queue items indicated apply authorization".to_string(),
    );

    push_queue_diagnostics_check(
        &mut checks,
        "items_have_compact_review_evidence",
        review_queue.items.iter().all(|item| {
            !item.proposal_id.trim().is_empty()
                && !item.path.trim().is_empty()
                && !item.report_reason.trim().is_empty()
                && !item.generated_at.trim().is_empty()
        }),
        "each queue item has compact review evidence fields",
        "one or more queue items are missing compact review evidence fields".to_string(),
    );

    let deduped_required_next_actions =
        dedupe_required_next_actions(&review_queue.required_next_actions);
    push_queue_diagnostics_check(
        &mut checks,
        "required_next_actions_are_deduplicated",
        deduped_required_next_actions.len() == review_queue.required_next_actions.len(),
        "required next actions are deduplicated summary strings",
        "required next actions contain duplicate summary strings".to_string(),
    );

    checks.push(WorkspacePatchReviewQueueDiagnosticsCheckSummary {
        name: "queue_blocked_items".to_string(),
        status: if review_queue.blocked_count > 0 {
            "Blocked"
        } else {
            "Pass"
        }
        .to_string(),
        reason: Some(if review_queue.blocked_count > 0 {
            format!(
                "{} proposal review item(s) are blocked",
                review_queue.blocked_count
            )
        } else {
            "no proposal review items are blocked".to_string()
        }),
    });

    let mut failed_checks: Vec<String> = checks
        .iter()
        .filter(|check| check.status == "Fail")
        .map(|check| check.name.clone())
        .collect();
    let mut blocked_checks: Vec<String> = checks
        .iter()
        .filter(|check| check.status == "Blocked")
        .map(|check| check.name.clone())
        .collect();

    failed_checks.sort();
    blocked_checks.sort();

    let (diagnostics_status, diagnostics_reason) = if !failed_checks.is_empty()
        || !blocked_checks.is_empty()
    {
        (
            "Blocked".to_string(),
            "Review queue diagnostics found blocked or inconsistent queue evidence.".to_string(),
        )
    } else if review_queue.needs_action_count > 0 {
        (
            "NeedsAction".to_string(),
            "Review queue diagnostics are consistent; additional proposal review signals are required."
                .to_string(),
        )
    } else {
        (
            "Complete".to_string(),
            "Review queue diagnostics are consistent and complete; patch apply remains unauthorized."
                .to_string(),
        )
    };

    WorkspacePatchReviewQueueDiagnosticsSummary {
        run_id: review_queue.run_id,
        diagnostics_status,
        diagnostics_reason,
        queue_status: review_queue.queue_status,
        proposal_count: review_queue.proposal_count,
        complete_count: review_queue.complete_count,
        needs_action_count: review_queue.needs_action_count,
        blocked_count: review_queue.blocked_count,
        check_count: checks.len(),
        failed_checks,
        blocked_checks,
        checks,
        required_next_actions: deduped_required_next_actions,
        apply_authorized: false,
        generated_at: now_rfc3339(),
    }
}

fn push_queue_diagnostics_check(
    checks: &mut Vec<WorkspacePatchReviewQueueDiagnosticsCheckSummary>,
    name: &str,
    passed: bool,
    pass_reason: &str,
    fail_reason: String,
) {
    checks.push(WorkspacePatchReviewQueueDiagnosticsCheckSummary {
        name: name.to_string(),
        status: if passed { "Pass" } else { "Fail" }.to_string(),
        reason: Some(if passed {
            pass_reason.to_string()
        } else {
            fail_reason
        }),
    });
}

fn dedupe_required_next_actions(actions: &[String]) -> Vec<String> {
    let mut deduped = Vec::new();
    for action in actions {
        if !deduped.contains(action) {
            deduped.push(action.clone());
        }
    }
    deduped
}

#[derive(Debug, Clone, Copy)]
struct ApplyDryRunSafety {
    no_patch_applied: bool,
    apply_executed: bool,
    workspace_files_changed: bool,
}

fn latest_apply_dry_run_safety(
    events: &[LedgerEvent],
    proposal_id: &str,
    dry_run_id: Option<&str>,
) -> Option<ApplyDryRunSafety> {
    events.iter().rev().find_map(|event| {
        if event.kind != LedgerEventKind::WorkspacePatchApplyDryRunChecked {
            return None;
        }
        let payload = sanitize_ledger_payload(event.payload.clone())?;
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            return None;
        }
        if let Some(dry_run_id) = dry_run_id {
            if payload.get("dry_run_id").and_then(Value::as_str) != Some(dry_run_id) {
                return None;
            }
        }
        Some(ApplyDryRunSafety {
            no_patch_applied: payload.get("no_patch_applied")?.as_bool()?,
            apply_executed: payload.get("apply_executed")?.as_bool()?,
            workspace_files_changed: payload.get("workspace_files_changed")?.as_bool()?,
        })
    })
}

fn reason_suffix(reason: Option<&str>) -> String {
    reason
        .filter(|reason| !reason.trim().is_empty())
        .map(|reason| format!(": {reason}."))
        .unwrap_or_else(|| ".".to_string())
}

fn latest_review_signal(
    events: &[LedgerEvent],
    proposal_id: &str,
    kind: LedgerEventKind,
    status_key: &str,
    reason_key: &str,
    generated_at_key: &str,
    source_id_key: &str,
) -> Option<WorkspacePatchReviewSignalSummary> {
    events.iter().rev().find_map(|event| {
        if event.kind != kind {
            return None;
        }
        let payload = sanitize_ledger_payload(event.payload.clone())?;
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            return None;
        }
        Some(WorkspacePatchReviewSignalSummary {
            status: review_signal_status(&payload, status_key)?,
            reason: payload
                .get(reason_key)
                .and_then(Value::as_str)
                .map(ToString::to_string),
            generated_at: payload
                .get(generated_at_key)
                .and_then(Value::as_str)
                .map(ToString::to_string),
            source_id: payload
                .get(source_id_key)
                .and_then(Value::as_str)
                .map(ToString::to_string),
        })
    })
}

fn review_signal_status(payload: &Value, key: &str) -> Option<String> {
    payload.get(key).and_then(|value| {
        value
            .as_str()
            .map(ToString::to_string)
            .or_else(|| value.as_bool().map(|value| value.to_string()))
    })
}

fn proposal_audit_entry(
    event: &LedgerEvent,
    proposal_id: &str,
) -> Option<WorkspacePatchAuditTrailEntry> {
    let payload = sanitize_ledger_payload(event.payload.clone())?;
    if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
        return None;
    }
    let (audit_event, metadata, summary) = match event.kind {
        LedgerEventKind::WorkspacePatchProposed => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "operation",
                    "path",
                    "content_chars",
                    "validation_status",
                    "validation_reason",
                    "diff_truncated",
                    "diff_redacted",
                ],
            );
            (
                "proposal_created",
                metadata,
                format!(
                    "Proposal created with validation status {}.",
                    payload
                        .get("validation_status")
                        .and_then(Value::as_str)
                        .unwrap_or("Unknown")
                ),
            )
        }
        LedgerEventKind::WorkspacePatchApproved => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "approval_status",
                    "approval_reason",
                    "approval_reason_redacted",
                    "approved_at",
                ],
            );
            (
                "proposal_approved",
                metadata,
                "Proposal approved.".to_string(),
            )
        }
        LedgerEventKind::WorkspacePatchRejected => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "approval_status",
                    "approval_reason",
                    "approval_reason_redacted",
                    "rejected_at",
                ],
            );
            (
                "proposal_rejected",
                metadata,
                "Proposal rejected.".to_string(),
            )
        }
        LedgerEventKind::WorkspacePatchPreflightSnapshotCreated => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "snapshot_id",
                    "path",
                    "canonical_path_hash",
                    "file_exists",
                    "file_kind",
                    "file_size_bytes",
                    "file_modified_unix_ms",
                    "file_sha256",
                    "captured_at",
                    "stale",
                    "stale_reason",
                ],
            );
            (
                "preflight_snapshot_created",
                metadata,
                format!(
                    "Preflight snapshot captured with stale={}.",
                    payload
                        .get("stale")
                        .and_then(Value::as_bool)
                        .map(|stale| stale.to_string())
                        .unwrap_or_else(|| "unknown".to_string())
                ),
            )
        }
        LedgerEventKind::WorkspacePatchApplyPlanCreated => {
            let metadata = select_audit_metadata(
                &payload,
                &["plan_id", "status", "check_count", "failed_checks"],
            );
            (
                "apply_plan_created",
                metadata,
                format!(
                    "Apply plan recorded with status {}.",
                    payload
                        .get("status")
                        .and_then(Value::as_str)
                        .unwrap_or("Unknown")
                ),
            )
        }
        LedgerEventKind::WorkspacePatchReadinessReportCreated => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "report_id",
                    "readiness_status",
                    "readiness_reason",
                    "readiness_fingerprint",
                    "fingerprint_input_count",
                    "generated_at",
                    "check_count",
                    "failed_checks",
                    "blocked_checks",
                ],
            );
            (
                "readiness_checked",
                metadata,
                format!(
                    "Readiness check recorded with status {}.",
                    payload
                        .get("readiness_status")
                        .and_then(Value::as_str)
                        .unwrap_or("Unknown")
                ),
            )
        }
        LedgerEventKind::WorkspacePatchApplyCapabilityChecked => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "capability_id",
                    "apply_supported",
                    "apply_enabled",
                    "mode",
                    "reason",
                    "required_gates",
                    "can_apply_now",
                    "checked_at",
                    "check_count",
                    "failed_checks",
                    "blocked_checks",
                ],
            );
            (
                "apply_capability_checked",
                metadata,
                "Apply capability check recorded without enabling apply.".to_string(),
            )
        }
        LedgerEventKind::WorkspacePatchApplyDryRunChecked => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "dry_run_id",
                    "dry_run_status",
                    "dry_run_reason",
                    "checked_at",
                    "required_gates",
                    "check_count",
                    "failed_checks",
                    "blocked_checks",
                    "no_patch_applied",
                    "apply_executed",
                    "workspace_files_changed",
                ],
            );
            (
                "apply_dry_run_checked",
                metadata,
                "Apply dry-run check recorded without applying a patch.".to_string(),
            )
        }
        LedgerEventKind::WorkspacePatchApplyResultRecorded => {
            let metadata = select_audit_metadata(
                &payload,
                &[
                    "apply_id",
                    "apply_status",
                    "apply_reason",
                    "authorization_id",
                    "authorization_consumed",
                    "applied",
                    "atomic_replacement_completed",
                    "path",
                    "expected_target_sha256",
                    "pre_write_target_sha256",
                    "post_write_sha256",
                    "content_chars",
                    "content_bytes",
                    "checked_at",
                    "applied_at",
                    "temp_file_cleaned",
                    "transaction_id",
                    "transaction_status",
                    "transaction_item_count",
                    "transaction_items",
                    "check_count",
                    "failed_checks",
                    "blocked_checks",
                ],
            );
            (
                "apply_result_recorded",
                metadata,
                format!(
                    "Apply result recorded with status {}.",
                    payload
                        .get("apply_status")
                        .and_then(Value::as_str)
                        .unwrap_or("Unknown")
                ),
            )
        }
        _ => return None,
    };
    Some(WorkspacePatchAuditTrailEntry {
        event_id: event.event_id.clone(),
        audit_event: audit_event.to_string(),
        event_kind: format!("{:?}", event.kind),
        timestamp: event.timestamp.clone(),
        proposal_id: proposal_id.to_string(),
        summary,
        metadata,
    })
}

fn select_audit_metadata(payload: &Value, keys: &[&str]) -> Value {
    let mut map = serde_json::Map::new();
    for key in keys {
        if let Some(value) = payload.get(*key) {
            map.insert((*key).to_string(), value.clone());
        }
    }
    Value::Object(map)
}

fn dry_run_history_entry_from_payload(
    payload: &Value,
) -> Option<WorkspacePatchApplyDryRunHistoryEntry> {
    let no_patch_applied = payload.get("no_patch_applied")?.as_bool()?;
    let apply_executed = payload.get("apply_executed")?.as_bool()?;
    let workspace_files_changed = payload.get("workspace_files_changed")?.as_bool()?;
    if !no_patch_applied || apply_executed || workspace_files_changed {
        return None;
    }
    Some(WorkspacePatchApplyDryRunHistoryEntry {
        proposal_id: payload.get("proposal_id")?.as_str()?.to_string(),
        dry_run_id: payload.get("dry_run_id")?.as_str()?.to_string(),
        dry_run_status: payload.get("dry_run_status")?.as_str()?.to_string(),
        dry_run_reason: payload.get("dry_run_reason")?.as_str()?.to_string(),
        checked_at: payload.get("checked_at")?.as_str()?.to_string(),
        required_gates: string_array_field(payload, "required_gates")?,
        check_count: usize::try_from(payload.get("check_count")?.as_u64()?).ok()?,
        failed_checks: string_array_field(payload, "failed_checks")?,
        blocked_checks: string_array_field(payload, "blocked_checks")?,
        no_patch_applied,
        apply_executed,
        workspace_files_changed,
    })
}

fn string_array_field(payload: &Value, key: &str) -> Option<Vec<String>> {
    payload
        .get(key)?
        .as_array()?
        .iter()
        .map(|value| value.as_str().map(ToString::to_string))
        .collect()
}

fn build_readiness_checklist(
    proposal: &WorkspacePatchProposalSummary,
) -> Vec<WorkspacePatchReadinessCheckSummary> {
    let snapshot = proposal.latest_snapshot.as_ref();
    let mut checklist = vec![readiness_check("proposal_exists", "Pass", None)];

    if proposal.validation_status == "Blocked" {
        checklist.push(readiness_check(
            "proposal_is_valid",
            "Blocked",
            proposal.validation_reason.as_deref(),
        ));
    } else if proposal.validation_status == "Valid" {
        checklist.push(readiness_check("proposal_is_valid", "Pass", None));
    } else {
        checklist.push(readiness_check(
            "proposal_is_valid",
            "Fail",
            proposal
                .validation_reason
                .as_deref()
                .or(Some("Proposal validation status is not Valid.")),
        ));
    }

    checklist.push(if proposal.approval_status == "Approved" {
        readiness_check("proposal_is_approved", "Pass", None)
    } else {
        readiness_check(
            "proposal_is_approved",
            "Fail",
            Some("Proposal is not approved."),
        )
    });
    checklist.push(if snapshot.is_some() {
        readiness_check("proposal_has_preflight_snapshot", "Pass", None)
    } else {
        readiness_check(
            "proposal_has_preflight_snapshot",
            "Fail",
            Some("Run proposal.preflight before final review."),
        )
    });
    checklist.push(match snapshot {
        Some(snapshot) if !snapshot.stale => readiness_check("proposal_not_stale", "Pass", None),
        Some(snapshot) => readiness_check(
            "proposal_not_stale",
            "Fail",
            snapshot
                .stale_reason
                .as_deref()
                .or(Some("Latest preflight snapshot is stale.")),
        ),
        None => readiness_check(
            "proposal_not_stale",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(match snapshot {
        Some(snapshot) if snapshot.file_exists => {
            readiness_check("target_file_exists", "Pass", None)
        }
        Some(_) => readiness_check(
            "target_file_exists",
            "Fail",
            Some("Target file was missing at preflight."),
        ),
        None => readiness_check(
            "target_file_exists",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(match snapshot {
        Some(snapshot) if snapshot.file_kind == "File" => {
            readiness_check("target_file_regular", "Pass", None)
        }
        Some(snapshot) if snapshot.file_kind == "Unreadable" => readiness_check(
            "target_file_regular",
            "Blocked",
            Some("Target file was unreadable at preflight."),
        ),
        Some(_) => readiness_check(
            "target_file_regular",
            "Fail",
            Some("Target path is not a regular file."),
        ),
        None => readiness_check(
            "target_file_regular",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(match snapshot {
        Some(snapshot) if snapshot.file_sha256.is_some() => {
            readiness_check("target_file_hash_available", "Pass", None)
        }
        Some(_) => readiness_check(
            "target_file_hash_available",
            "Fail",
            Some("Target file hash is unavailable."),
        ),
        None => readiness_check(
            "target_file_hash_available",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(if proposal.diff_preview.is_some() {
        readiness_check("diff_preview_available", "Pass", None)
    } else {
        readiness_check(
            "diff_preview_available",
            "Fail",
            Some("Sanitized diff preview is unavailable."),
        )
    });
    checklist.push(if proposal.diff_redacted {
        readiness_check(
            "diff_not_redacted",
            "Blocked",
            Some("Diff preview was redacted."),
        )
    } else {
        readiness_check("diff_not_redacted", "Pass", None)
    });
    let sensitive = proposal.validation_status == "Blocked"
        || proposal.diff_redacted
        || proposal.content_preview == "[redacted]";
    checklist.push(if sensitive {
        readiness_check(
            "no_sensitive_content_detected",
            "Blocked",
            Some("Sensitive-like content was detected or redacted."),
        )
    } else {
        readiness_check("no_sensitive_content_detected", "Pass", None)
    });
    checklist.push(readiness_check("no_raw_content_exposed", "Pass", None));
    checklist.push(readiness_check(
        "apply_execution_supported",
        "Pass",
        Some("Patch apply is available through proposal.apply after explicit authorization."),
    ));
    checklist
}

fn readiness_fingerprint(
    proposal: &WorkspacePatchProposalSummary,
    checklist: &[WorkspacePatchReadinessCheckSummary],
) -> (String, usize) {
    let mut inputs = vec![
        format!("proposal_id={}", proposal.proposal_id),
        format!("path={}", proposal.path),
        format!("operation={}", proposal.operation),
        format!("content_chars={}", proposal.content_chars),
        format!("truncated={}", proposal.truncated),
        format!("validation_status={}", proposal.validation_status),
        format!(
            "validation_reason={}",
            proposal.validation_reason.as_deref().unwrap_or("")
        ),
        format!("diff_preview_available={}", proposal.diff_preview.is_some()),
        format!("diff_truncated={}", proposal.diff_truncated),
        format!("diff_redacted={}", proposal.diff_redacted),
        format!("approval_status={}", proposal.approval_status),
        format!(
            "approved_at={}",
            proposal.approved_at.as_deref().unwrap_or("")
        ),
        format!(
            "rejected_at={}",
            proposal.rejected_at.as_deref().unwrap_or("")
        ),
    ];
    if let Some(snapshot) = proposal.latest_snapshot.as_ref() {
        inputs.extend([
            format!("snapshot_id={}", snapshot.snapshot_id),
            format!("snapshot_path={}", snapshot.path),
            format!("canonical_path_hash={}", snapshot.canonical_path_hash),
            format!("file_exists={}", snapshot.file_exists),
            format!("file_kind={}", snapshot.file_kind),
            format!(
                "file_size_bytes={}",
                snapshot
                    .file_size_bytes
                    .map(|value| value.to_string())
                    .unwrap_or_default()
            ),
            format!(
                "file_modified_unix_ms={}",
                snapshot
                    .file_modified_unix_ms
                    .map(|value| value.to_string())
                    .unwrap_or_default()
            ),
            format!(
                "file_sha256={}",
                snapshot.file_sha256.as_deref().unwrap_or("")
            ),
            format!("stale={}", snapshot.stale),
            format!(
                "stale_reason={}",
                snapshot.stale_reason.as_deref().unwrap_or("")
            ),
        ]);
    } else {
        inputs.push("snapshot_id=".to_string());
    }
    for (index, check) in checklist.iter().enumerate() {
        inputs.push(format!(
            "check[{index}]={}|{}|{}",
            check.name,
            check.status,
            check.reason.as_deref().unwrap_or("")
        ));
    }
    let input_count = inputs.len();
    (
        format!("sha256:{}", hex_sha256(inputs.join("\n").as_bytes())),
        input_count,
    )
}

fn readiness_proposal(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchReadinessReportSummary,
    ),
    String,
> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let checklist = build_readiness_checklist(&proposal);

    let blocked_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Blocked")
        .map(|c| c.name.clone())
        .collect();
    let failed_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Fail")
        .map(|c| c.name.clone())
        .collect();
    let (readiness_status, readiness_reason, summary) = if !blocked_checks.is_empty() {
        ("Blocked", Some("Proposal or target file contains sensitive-like content; sanitized preview is unavailable."), "Blocked. Proposal or target file contains sensitive-like content; sanitized preview is unavailable.")
    } else if !failed_checks.is_empty() {
        let stale = failed_checks
            .iter()
            .any(|name| name == "proposal_not_stale");
        let reason = if stale {
            "Latest preflight snapshot is stale; rerun proposal.preflight before review."
        } else {
            "Proposal is missing required approval, validation, preflight, target hash, or sanitized diff preview."
        };
        (
            "NotReady",
            Some(reason),
            if stale {
                "Not ready for final human review. Latest preflight snapshot is stale; rerun proposal.preflight before review."
            } else {
                "Not ready for final human review. Proposal is missing required approval, validation, preflight, target hash, or sanitized diff preview."
            },
        )
    } else {
        ("Ready", None, "Ready for final human review. Proposal is approved, latest preflight is fresh, target file hash is captured, a sanitized diff preview is available, and controlled apply execution is available through proposal.apply.")
    };
    let generated_at = now_rfc3339();
    let report_id = format!("report_{}", uuid::Uuid::new_v4().simple());
    let (readiness_fingerprint, fingerprint_input_count) =
        readiness_fingerprint(&proposal, &checklist);
    let report = WorkspacePatchReadinessReportSummary {
        proposal_id: proposal_id.to_string(),
        report_id: report_id.clone(),
        readiness_status: readiness_status.to_string(),
        readiness_reason: readiness_reason.map(ToString::to_string),
        readiness_fingerprint: readiness_fingerprint.clone(),
        fingerprint_input_count,
        generated_at: generated_at.clone(),
        checklist,
        summary: summary.to_string(),
    };
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchReadinessReportCreated,
            Some(json!({
                "proposal_id": proposal_id,
                "report_id": report_id,
                "readiness_status": readiness_status,
                "readiness_reason": report.readiness_reason,
                "readiness_fingerprint": readiness_fingerprint,
                "fingerprint_input_count": fingerprint_input_count,
                "generated_at": generated_at,
                "check_count": report.checklist.len(),
                "failed_checks": failed_checks,
                "blocked_checks": blocked_checks,
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    Ok((inspect_proposal(store, run_id, proposal_id)?, report))
}

fn preflight_proposal(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchPreflightSnapshotSummary,
        WorkspacePatchApplyPlanSummary,
    ),
    String,
> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    if proposal.approval_status != "Approved" {
        return Err("invalid params: proposal must be approved".to_string());
    }
    if proposal.validation_status != "Valid" {
        return Err("invalid params: proposal must be valid".to_string());
    }
    let events = read_existing_run_events(store, run_id)?;
    let previous = latest_snapshot(&events, proposal_id);
    let snapshot = capture_preflight_snapshot(store, &proposal, previous.as_ref())?;
    let plan_id = format!("plan_{}", uuid::Uuid::new_v4().simple());
    let apply_plan = build_apply_plan_summary(proposal_id, &plan_id, "Ready", &proposal.operation);
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchPreflightSnapshotCreated,
            Some(json!(snapshot)),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchApplyPlanCreated,
            Some(json!({
                "proposal_id": proposal_id,
                "plan_id": plan_id,
                "operation": &proposal.operation,
                "status": "Ready",
                "check_count": apply_plan.checklist.len(),
                "failed_checks": [],
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    Ok((
        inspect_proposal(store, run_id, proposal_id)?,
        snapshot,
        apply_plan,
    ))
}

fn capture_preflight_snapshot(
    store: &BrownieStore,
    proposal: &WorkspacePatchProposalSummary,
    previous: Option<&WorkspacePatchPreflightSnapshotSummary>,
) -> Result<WorkspacePatchPreflightSnapshotSummary, String> {
    brownie_tools::preflight_workspace_write_path(&proposal.path)
        .map_err(|_| "invalid params: target path is not safe".to_string())?;
    let root = store
        .workspace_root()
        .canonicalize()
        .map_err(|_| "invalid params: workspace root is not accessible".to_string())?;
    if std::path::Path::new(&proposal.path)
        .components()
        .any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        return Err("invalid params: target path is not safe".to_string());
    }
    let target = root.join(&proposal.path);
    if proposal.operation == WorkspacePatchOperation::CreateFile.as_str() {
        let relative_path = Path::new(&proposal.path);
        let parent_relative = relative_path.parent().unwrap_or_else(|| Path::new(""));
        let parent = root.join(parent_relative);
        let parent_metadata = std::fs::symlink_metadata(&parent)
            .map_err(|_| "invalid params: target parent directory does not exist".to_string())?;
        if parent_metadata.file_type().is_symlink() {
            return Err("invalid params: target parent directory is a symlink".to_string());
        }
        if !parent_metadata.is_dir() {
            return Err("invalid params: target parent path is not a directory".to_string());
        }
        let canonical_parent = parent
            .canonicalize()
            .map_err(|_| "invalid params: target parent directory is not accessible".to_string())?;
        if !canonical_parent.starts_with(&root) {
            return Err("invalid params: target parent escapes workspace root".to_string());
        }
    }
    let canonical_for_hash = target.canonicalize().unwrap_or(target.clone());
    if canonical_for_hash.exists() && !canonical_for_hash.starts_with(&root) {
        return Err("invalid params: target path escapes workspace root".to_string());
    }
    let canonical_path_hash = format!(
        "sha256:{}",
        hex_sha256(canonical_for_hash.to_string_lossy().as_bytes())
    );
    let captured_at = now_rfc3339();
    let snapshot_id = format!("snapshot_{}", uuid::Uuid::new_v4().simple());
    let metadata = if proposal.operation == WorkspacePatchOperation::CreateFile.as_str()
        || proposal.operation == WorkspacePatchOperation::DeleteFile.as_str()
        || proposal.operation == WorkspacePatchOperation::PatchFile.as_str()
    {
        std::fs::symlink_metadata(&target)
    } else {
        std::fs::metadata(&target)
    };
    let (file_exists, mut file_kind, file_size_bytes, file_modified_unix_ms, mut file_sha256) =
        match metadata {
            Ok(metadata) => {
                let kind = if metadata.file_type().is_symlink() {
                    "Symlink"
                } else if metadata.is_file() {
                    "File"
                } else if metadata.is_dir() {
                    "Directory"
                } else {
                    "Other"
                };
                let modified = metadata.modified().ok().and_then(system_time_unix_ms);
                let hash = if metadata.is_file() {
                    std::fs::read(&target)
                        .ok()
                        .map(|bytes| format!("sha256:{}", hex_sha256(&bytes)))
                } else {
                    None
                };
                (true, kind.to_string(), Some(metadata.len()), modified, hash)
            }
            Err(_) => (false, "Missing".to_string(), None, None, None),
        };
    if file_exists && file_kind == "File" && file_sha256.is_none() {
        file_kind = "Unreadable".to_string();
    }
    if file_sha256
        .as_deref()
        .is_some_and(|hash| scan_text_for_sensitive_content(hash))
    {
        file_sha256 = None;
    }
    let stale = previous.is_some_and(|prev| {
        prev.file_exists != file_exists
            || prev.file_kind != file_kind
            || prev.file_sha256 != file_sha256
            || prev.file_size_bytes != file_size_bytes
            || prev.file_modified_unix_ms != file_modified_unix_ms
    });
    Ok(WorkspacePatchPreflightSnapshotSummary {
        proposal_id: proposal.proposal_id.clone(),
        snapshot_id,
        path: proposal.path.clone(),
        canonical_path_hash,
        file_exists,
        file_kind,
        file_size_bytes,
        file_modified_unix_ms,
        file_sha256,
        captured_at,
        stale,
        stale_reason: stale
            .then(|| "target file metadata changed since previous preflight".to_string()),
    })
}

fn hex_sha256(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn completion_result_fingerprint(
    final_state: AgentLoopState,
    completion_summary: &str,
    final_response_content: &str,
) -> String {
    let canonical = json!({
        "version": "completion_result_fingerprint_v1",
        "final_state": agent_loop_state_name(final_state),
        "completion_summary_chars": completion_summary.chars().count(),
        "completion_summary_sha256": format!("sha256:{}", hex_sha256(completion_summary.as_bytes())),
        "final_response_chars": final_response_content.chars().count(),
        "final_response_sha256": format!("sha256:{}", hex_sha256(final_response_content.as_bytes())),
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn task_run_completion_evidence(
    final_state: AgentLoopState,
    task_status: TaskStatus,
    completion_result_fingerprint: String,
    completion_summary: &str,
    final_response_content: &str,
    replayed: bool,
) -> TaskRunCompletionEvidence {
    let completion_summary_preview = preview_with_limit(
        completion_summary,
        TASK_RUN_COMPLETION_SUMMARY_PREVIEW_CHARS,
    );
    let completion_summary_chars = completion_summary.chars().count();
    TaskRunCompletionEvidence {
        final_state: agent_loop_state_name(final_state).to_string(),
        task_status,
        completion_result_fingerprint,
        completion_summary_preview,
        completion_summary_chars,
        completion_summary_truncated: completion_summary_chars
            > TASK_RUN_COMPLETION_SUMMARY_PREVIEW_CHARS,
        final_response_present: !final_response_content.is_empty(),
        final_response_chars: final_response_content.chars().count(),
        replayed,
    }
}

fn system_time_unix_ms(time: std::time::SystemTime) -> Option<i64> {
    time.duration_since(std::time::UNIX_EPOCH)
        .ok()
        .and_then(|duration| i64::try_from(duration.as_millis()).ok())
}

fn inspect_proposal(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<WorkspacePatchProposalSummary, String> {
    list_proposals(store, run_id)?
        .into_iter()
        .find(|proposal| proposal.proposal_id == proposal_id)
        .ok_or_else(|| "invalid params: proposal not found".to_string())
}

fn inspect_run(store: &BrownieStore, run_id: &str) -> Result<RunInspectSummary, String> {
    let events = read_existing_run_events(store, run_id)?;
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|error| format!("invalid params: {error}"))?;
    let child_tasks = store
        .tasks()
        .list_tasks()
        .map_err(|error| format!("invalid params: {error}"))?
        .into_iter()
        .filter(|task| task.parent_run_id.as_deref() == Some(run_id))
        .collect::<Vec<_>>();
    let child_task_ids = child_tasks
        .iter()
        .map(|task| task.task_id.clone())
        .collect::<Vec<_>>();
    let child_task_summaries = child_tasks
        .iter()
        .map(|task| child_task_inspect_summary(store, task))
        .collect::<Result<Vec<_>, _>>()?;
    let has_tool_execution_completed = events
        .iter()
        .any(|event| event.kind == LedgerEventKind::ToolExecutionCompleted);
    let subtask_queue_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskOrchestrationQueued)
        .count();
    let subtask_handoff_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskHandoffPrepared)
        .count();
    let subtask_scheduler_readiness_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskSchedulerReadinessRecorded)
        .count();
    let subtask_dispatch_plan_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchPlanPrepared)
        .count();
    let subtask_dispatch_contract_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchContractPrepared)
        .count();
    let subtask_dispatch_admission_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchAdmissionEvaluated)
        .count();
    let subtask_dispatch_readiness_snapshot_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchReadinessSnapshotRecorded)
        .count();
    let subtask_dispatcher_guard_verdict_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatcherGuardVerdictRecorded)
        .count();
    let subtask_dispatch_decision_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchDecisionRecorded)
        .count();
    let subtask_dispatch_candidate_manifest_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchCandidateManifestRecorded)
        .count();
    let subtask_dispatch_handoff_envelope_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
        .count();
    let has_second_pass = events
        .iter()
        .any(|event| event.kind == LedgerEventKind::SecondPassLlmResponseReceived);
    let final_response_preview =
        latest_content_preview(&events, LedgerEventKind::SecondPassLlmResponseReceived)
            .or_else(|| latest_content_preview(&events, LedgerEventKind::LlmResponseReceived));
    let parent_join_readiness_summary = task
        .as_ref()
        .map(|record| parent_join_readiness_summary_for_parent_inspection(store, record))
        .transpose()?
        .flatten();
    let consumed_parent_join_recovery_summary = task
        .as_ref()
        .map(|record| consumed_parent_join_recovery_summary_for_parent_inspection(store, record))
        .transpose()?
        .flatten();
    let progress_snapshot = progress_snapshot_for_run(
        task.as_ref(),
        &events,
        &child_tasks,
        parent_join_readiness_summary.as_ref(),
    );
    Ok(RunInspectSummary {
        run_id: run_id.to_string(),
        task_id: task.as_ref().map(|task| task.task_id.clone()),
        status: task.as_ref().map(|task| task.status.clone()),
        progress_snapshot,
        recovery_cycle_budget_outcome: recovery_cycle_budget_outcome_from_events(&events),
        parent_join_readiness_summary,
        consumed_parent_join_recovery_summary,
        child_task_count: child_task_ids.len(),
        child_task_ids,
        child_tasks: child_task_summaries,
        event_count: events.len(),
        has_tool_execution_completed,
        has_subtask_orchestration_queued: subtask_queue_count > 0,
        subtask_queue_count,
        has_subtask_handoff_prepared: subtask_handoff_count > 0,
        subtask_handoff_count,
        has_subtask_scheduler_readiness: subtask_scheduler_readiness_count > 0,
        subtask_scheduler_readiness_count,
        has_subtask_dispatch_plan_prepared: subtask_dispatch_plan_count > 0,
        subtask_dispatch_plan_count,
        has_subtask_dispatch_contract_prepared: subtask_dispatch_contract_count > 0,
        subtask_dispatch_contract_count,
        has_subtask_dispatch_admission_evaluated: subtask_dispatch_admission_count > 0,
        subtask_dispatch_admission_count,
        has_subtask_dispatch_readiness_snapshot: subtask_dispatch_readiness_snapshot_count > 0,
        subtask_dispatch_readiness_snapshot_count,
        has_subtask_dispatcher_guard_verdict: subtask_dispatcher_guard_verdict_count > 0,
        subtask_dispatcher_guard_verdict_count,
        has_subtask_dispatch_decision: subtask_dispatch_decision_count > 0,
        subtask_dispatch_decision_count,
        has_subtask_dispatch_candidate_manifest: subtask_dispatch_candidate_manifest_count > 0,
        subtask_dispatch_candidate_manifest_count,
        has_subtask_dispatch_handoff_envelope: subtask_dispatch_handoff_envelope_count > 0,
        subtask_dispatch_handoff_envelope_count,
        has_second_pass,
        final_response_preview,
        timeline: events.iter().map(timeline_entry).collect(),
    })
}

fn progress_snapshot_for_run(
    task: Option<&TaskRecord>,
    events: &[LedgerEvent],
    child_tasks: &[TaskRecord],
    parent_join_readiness_summary: Option<&RunInspectParentJoinReadinessSummary>,
) -> ProgressSnapshot {
    let created_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Created)
        .count();
    let queued_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Queued)
        .count();
    let running_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Running)
        .count();
    let completed_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Completed)
        .count();
    let failed_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Failed)
        .count();
    let cancelled_controlled_child_count = child_tasks
        .iter()
        .filter(|child| child.status == TaskStatus::Cancelled)
        .count();
    let pending_controlled_child_count = child_tasks
        .iter()
        .filter(|child| is_parent_join_runnable_pending_child_status(&child.status))
        .count();
    let terminal_controlled_child_count = child_tasks
        .iter()
        .filter(|child| is_parent_join_terminal_child_status(&child.status))
        .count();
    let non_runnable_controlled_child_count = child_tasks
        .iter()
        .filter(|child| is_parent_join_non_runnable_child_status(&child.status))
        .count();
    let agent_loop_terminal_evidence_present = events
        .iter()
        .any(|event| event.kind == LedgerEventKind::AgentLoopCompleted);
    let task_terminal_event_present = events.iter().any(|event| {
        matches!(
            event.kind,
            LedgerEventKind::TaskCompleted
                | LedgerEventKind::TaskFailed
                | LedgerEventKind::TaskCancelled
        )
    });
    let latest_task_terminal_event_kind = latest_task_terminal_event_kind(events);
    let verification_state = progress_verification_state(events);
    let verifier_required = progress_verifier_required(events)
        || matches!(
            verification_state,
            ProgressVerificationState::Pending
                | ProgressVerificationState::Passed
                | ProgressVerificationState::Failed
                | ProgressVerificationState::Unknown
        );
    let verifier_failed = verification_state == ProgressVerificationState::Failed;
    let verifier_passed = verification_state == ProgressVerificationState::Passed;
    let recovery_signal_present = task.is_some_and(|task| {
        task.recovery_cycle_provenance.is_some()
            || task.verification_recovery_provenance.is_some()
            || task.verification_recovery_retry_provenance.is_some()
            || task.llm_provider_failure_retry_provenance.is_some()
    }) || events.iter().any(|event| {
        event.payload.as_ref().is_some_and(|payload| {
            payload.get("verification_recovery").is_some()
                || payload.get("verification_recovery_retry").is_some()
                || payload.get("verification_recovery_repair").is_some()
                || payload.get("recovery_cycle_budget_outcome").is_some()
        })
    });
    let apply_signal_present = events
        .iter()
        .any(|event| event.kind == LedgerEventKind::WorkspacePatchApplyResultRecorded);
    let selected_index_context_count = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::CodebaseIndexPromptContextMaterialized)
        .count();
    let selected_index_context_present = selected_index_context_count > 0;
    let parent_join_ready = parent_join_readiness_summary.is_some_and(|summary| {
        summary.parent_join_ready && summary.next_action == "run_parent_task_explicitly"
    });
    let has_running_evidence = events.iter().any(|event| {
        matches!(
            event.kind,
            LedgerEventKind::TaskRunning | LedgerEventKind::AgentLoopStarted
        )
    });

    let task_status = task.map(|task| &task.status);
    let (lifecycle_phase, current_stage, next_action) = match task_status {
        Some(TaskStatus::Failed) => {
            let action = if verification_state == ProgressVerificationState::Failed {
                ProgressNextAction::StartVerificationRecoveryExplicitly
            } else {
                ProgressNextAction::InspectTerminalResult
            };
            (
                ProgressLifecyclePhase::Terminal,
                ProgressCurrentStage::Failed,
                action,
            )
        }
        Some(TaskStatus::Cancelled) => (
            ProgressLifecyclePhase::Terminal,
            ProgressCurrentStage::Cancelled,
            ProgressNextAction::InspectTerminalResult,
        ),
        Some(TaskStatus::Completed) if non_runnable_controlled_child_count > 0 => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::InspectNonRunnableChildTasks,
            ProgressNextAction::InspectNonRunnableChildTasks,
        ),
        Some(TaskStatus::Completed) if pending_controlled_child_count > 0 => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::CompletedWithPendingChildren,
            ProgressNextAction::RunRemainingChildTasksExplicitly,
        ),
        Some(TaskStatus::Completed) if parent_join_ready => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::ParentJoinReady,
            ProgressNextAction::RunParentTaskExplicitly,
        ),
        Some(TaskStatus::Completed) => (
            ProgressLifecyclePhase::Terminal,
            ProgressCurrentStage::Completed,
            ProgressNextAction::InspectTerminalResult,
        ),
        Some(TaskStatus::Running) => (
            ProgressLifecyclePhase::Running,
            ProgressCurrentStage::RunningAgentLoop,
            ProgressNextAction::InspectTask,
        ),
        Some(TaskStatus::Queued) => (
            ProgressLifecyclePhase::Queued,
            ProgressCurrentStage::Queued,
            ProgressNextAction::RunTaskExplicitly,
        ),
        Some(TaskStatus::Created) => (
            ProgressLifecyclePhase::Created,
            ProgressCurrentStage::Created,
            ProgressNextAction::RunTaskExplicitly,
        ),
        None if has_running_evidence => (
            ProgressLifecyclePhase::Running,
            ProgressCurrentStage::RunningAgentLoop,
            ProgressNextAction::InspectTask,
        ),
        _ if non_runnable_controlled_child_count > 0 => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::InspectNonRunnableChildTasks,
            ProgressNextAction::InspectNonRunnableChildTasks,
        ),
        _ if pending_controlled_child_count > 0 => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::CompletedWithPendingChildren,
            ProgressNextAction::RunRemainingChildTasksExplicitly,
        ),
        _ if verification_state == ProgressVerificationState::Failed => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::Failed,
            ProgressNextAction::StartVerificationRecoveryExplicitly,
        ),
        _ if recovery_signal_present => (
            ProgressLifecyclePhase::BlockedForExplicitAction,
            ProgressCurrentStage::Unknown,
            ProgressNextAction::RunTaskExplicitly,
        ),
        None if selected_index_context_present => (
            ProgressLifecyclePhase::Unknown,
            ProgressCurrentStage::Unknown,
            ProgressNextAction::InspectTask,
        ),
        None => (
            ProgressLifecyclePhase::Unknown,
            ProgressCurrentStage::Unknown,
            ProgressNextAction::InspectTask,
        ),
    };
    let source_fingerprint = progress_snapshot_source_fingerprint(&[
        ("version", "progress_snapshot_v3".to_string()),
        (
            "task_status",
            task_status
                .map(|status| format!("{status:?}"))
                .unwrap_or_else(|| "None".to_string()),
        ),
        ("lifecycle_phase", format!("{lifecycle_phase:?}")),
        ("current_stage", format!("{current_stage:?}")),
        ("next_action", format!("{next_action:?}")),
        ("event_count", events.len().to_string()),
        (
            "agent_loop_terminal_evidence_present",
            agent_loop_terminal_evidence_present.to_string(),
        ),
        (
            "task_terminal_event_present",
            task_terminal_event_present.to_string(),
        ),
        (
            "latest_task_terminal_event_kind",
            latest_task_terminal_event_kind
                .as_deref()
                .unwrap_or("none")
                .to_string(),
        ),
        ("controlled_child_count", child_tasks.len().to_string()),
        (
            "created_controlled_child_count",
            created_controlled_child_count.to_string(),
        ),
        (
            "queued_controlled_child_count",
            queued_controlled_child_count.to_string(),
        ),
        (
            "running_controlled_child_count",
            running_controlled_child_count.to_string(),
        ),
        (
            "completed_controlled_child_count",
            completed_controlled_child_count.to_string(),
        ),
        (
            "failed_controlled_child_count",
            failed_controlled_child_count.to_string(),
        ),
        (
            "cancelled_controlled_child_count",
            cancelled_controlled_child_count.to_string(),
        ),
        (
            "pending_controlled_child_count",
            pending_controlled_child_count.to_string(),
        ),
        (
            "terminal_controlled_child_count",
            terminal_controlled_child_count.to_string(),
        ),
        (
            "non_runnable_controlled_child_count",
            non_runnable_controlled_child_count.to_string(),
        ),
        ("verification_state", format!("{verification_state:?}")),
        ("verifier_required", verifier_required.to_string()),
        ("verifier_failed", verifier_failed.to_string()),
        ("verifier_passed", verifier_passed.to_string()),
        ("parent_join_ready", parent_join_ready.to_string()),
        (
            "recovery_signal_present",
            recovery_signal_present.to_string(),
        ),
        ("apply_signal_present", apply_signal_present.to_string()),
        (
            "selected_index_context_present",
            selected_index_context_present.to_string(),
        ),
        (
            "selected_index_context_count",
            selected_index_context_count.to_string(),
        ),
    ]);

    ProgressSnapshot {
        lifecycle_phase,
        current_stage,
        next_action,
        source_fingerprint,
        event_count: events.len(),
        agent_loop_terminal_evidence_present,
        task_terminal_event_present,
        controlled_child_count: child_tasks.len(),
        pending_controlled_child_count,
        terminal_controlled_child_count,
        non_runnable_controlled_child_count,
        verification_state,
        verifier_required,
        verifier_failed,
        verifier_passed,
        recovery_signal_present,
        apply_signal_present,
        selected_index_context_present,
        selected_index_context_count,
    }
}

fn progress_snapshot_source_fingerprint(entries: &[(&str, String)]) -> String {
    let mut canonical = String::new();
    for (key, value) in entries {
        canonical.push_str(key);
        canonical.push('\0');
        canonical.push_str(&value.len().to_string());
        canonical.push('\0');
        canonical.push_str(value);
        canonical.push('\n');
    }
    format!("sha256:{}", hex_sha256(canonical.as_bytes()))
}

fn latest_task_terminal_event_kind(events: &[LedgerEvent]) -> Option<String> {
    events
        .iter()
        .rev()
        .find(|event| {
            matches!(
                event.kind,
                LedgerEventKind::TaskCompleted
                    | LedgerEventKind::TaskFailed
                    | LedgerEventKind::TaskCancelled
            )
        })
        .map(|event| format!("{:?}", event.kind))
}

enum ProgressVerificationGateStatus<'a> {
    Known(&'a str),
    Malformed,
}

fn latest_progress_verification_gate_status(
    events: &[LedgerEvent],
) -> Option<ProgressVerificationGateStatus<'_>> {
    events.iter().rev().find_map(|event| {
        if !is_progress_verification_gate_event_kind(&event.kind) {
            return None;
        }
        let payload = event.payload.as_ref()?;
        if payload.get("verification_completion_gate_status").is_some() {
            return Some(
                payload
                    .get("verification_completion_gate_status")
                    .and_then(Value::as_str)
                    .map(ProgressVerificationGateStatus::Known)
                    .unwrap_or(ProgressVerificationGateStatus::Malformed),
            );
        }
        if let Some(gate) = payload.get("verification_completion_gate") {
            return Some(
                gate.get("status")
                    .and_then(Value::as_str)
                    .map(ProgressVerificationGateStatus::Known)
                    .unwrap_or(ProgressVerificationGateStatus::Malformed),
            );
        }
        None
    })
}

fn is_progress_verification_gate_event_kind(kind: &LedgerEventKind) -> bool {
    matches!(
        kind,
        LedgerEventKind::TaskCompleted
            | LedgerEventKind::TaskFailed
            | LedgerEventKind::TaskCancelled
    )
}

fn progress_verifier_required(events: &[LedgerEvent]) -> bool {
    !required_verification_intents(events).is_empty()
        || events.iter().any(|event| {
            if !is_progress_verification_gate_event_kind(&event.kind) {
                return false;
            }
            event.payload.as_ref().is_some_and(|payload| {
                payload.get("verification_completion_gate_status").is_some()
                    || payload.get("verification_completion_gate").is_some()
                    || payload
                        .get("required_verifier_count")
                        .and_then(Value::as_u64)
                        .is_some_and(|count| count > 0)
            })
        })
}

fn progress_verification_state(events: &[LedgerEvent]) -> ProgressVerificationState {
    match latest_progress_verification_gate_status(events) {
        Some(ProgressVerificationGateStatus::Known(VERIFICATION_COMPLETION_GATE_STATUS_PASSED)) => {
            ProgressVerificationState::Passed
        }
        Some(ProgressVerificationGateStatus::Known(VERIFICATION_COMPLETION_GATE_STATUS_FAILED)) => {
            ProgressVerificationState::Failed
        }
        Some(_) => ProgressVerificationState::Unknown,
        None if progress_verifier_required(events) => ProgressVerificationState::Pending,
        None => ProgressVerificationState::NotRequired,
    }
}

fn recovery_cycle_budget_outcome_for_run(
    store: &BrownieStore,
    run_id: &str,
) -> Result<Option<RecoveryCycleBudgetOutcome>, String> {
    let events = store
        .tasks()
        .read_ledger_events(run_id)
        .map_err(|error| format!("invalid params: {error}"))?;
    Ok(recovery_cycle_budget_outcome_from_events(&events))
}

fn recovery_cycle_budget_outcome_for_replay(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<(TaskRunAgentLoopSummary, RecoveryCycleBudgetOutcome)>, String> {
    if !matches!(
        record.status,
        TaskStatus::Completed | TaskStatus::Failed | TaskStatus::Cancelled
    ) {
        return Ok(None);
    }

    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| format!("invalid params: {error}"))?;
    let Some(recovery_cycle_budget_outcome) = recovery_cycle_budget_outcome_from_events(&events)
    else {
        return Ok(None);
    };
    let Some(agent_loop) = task_run_agent_loop_summary_from_events(&events) else {
        return Ok(None);
    };

    Ok(Some((agent_loop, recovery_cycle_budget_outcome)))
}

fn child_orchestration_outcome_for_replay(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<(TaskRunAgentLoopSummary, TaskRunChildOrchestrationOutcome)>, String> {
    if record.status != TaskStatus::Completed || record.parent_run_id.is_some() {
        return Ok(None);
    }

    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| format!("invalid params: {error}"))?;
    let Some(agent_loop) = task_run_agent_loop_summary_from_events(&events) else {
        return Ok(None);
    };
    let child_orchestration_outcome = if events
        .iter()
        .any(|event| event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed)
    {
        child_orchestration_outcome_for_latest_parent_join_queued_children(
            store,
            &record.task_id,
            &record.run_id,
            &events,
        )?
    } else {
        if controlled_child_set_has_terminal_and_pending(
            store,
            Some(&record.task_id),
            &record.run_id,
            None,
        )? {
            return Ok(None);
        }
        child_orchestration_outcome_for_existing_queued_children(store, &record.run_id)?
    };
    let Some(child_orchestration_outcome) = child_orchestration_outcome else {
        return Ok(None);
    };

    Ok(Some((agent_loop, child_orchestration_outcome)))
}

fn parent_join_readiness_outcome_for_replay(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<(TaskRunAgentLoopSummary, TaskRunParentJoinReadinessOutcome)>, String> {
    let Some(parent_join_readiness_outcome) =
        parent_join_readiness_outcome_for_terminal_child(store, record)?
    else {
        return Ok(None);
    };
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| format!("invalid params: {error}"))?;
    let Some(agent_loop) = task_run_terminal_child_agent_loop_summary_from_events(record, &events)
    else {
        return Ok(None);
    };

    Ok(Some((agent_loop, parent_join_readiness_outcome)))
}

fn task_run_agent_loop_summary_from_events(
    events: &[LedgerEvent],
) -> Option<TaskRunAgentLoopSummary> {
    let payload = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::AgentLoopCompleted)?
        .payload
        .as_ref()?;
    Some(TaskRunAgentLoopSummary {
        final_state: non_empty_payload_string(payload, "final_state")?,
        completion_summary: payload
            .get("completion_summary")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
    })
}

fn task_run_completion_evidence_from_events(
    events: &[LedgerEvent],
    record: &TaskRecord,
    replayed: bool,
) -> Option<TaskRunCompletionEvidence> {
    for event in events.iter().rev() {
        if !matches!(
            event.kind,
            LedgerEventKind::TaskCompleted
                | LedgerEventKind::TaskFailed
                | LedgerEventKind::TaskCancelled
        ) {
            continue;
        }
        let payload = event.payload.as_ref()?;
        if let Some(evidence) = payload.get("completion_evidence").and_then(|value| {
            serde_json::from_value::<TaskRunCompletionEvidence>(value.clone()).ok()
        }) {
            return Some(TaskRunCompletionEvidence {
                replayed,
                ..evidence
            });
        }
    }

    let payload = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::AgentLoopCompleted)?
        .payload
        .as_ref()?;
    let final_state = non_empty_payload_string(payload, "final_state")?;
    let completion_summary = payload
        .get("completion_summary")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let completion_result_fingerprint = payload
        .get("completion_result_fingerprint")
        .and_then(Value::as_str)?
        .to_string();
    let completion_summary_preview = preview_with_limit(
        completion_summary,
        TASK_RUN_COMPLETION_SUMMARY_PREVIEW_CHARS,
    );
    let completion_summary_chars = completion_summary.chars().count();
    Some(TaskRunCompletionEvidence {
        final_state,
        task_status: record.status.clone(),
        completion_result_fingerprint,
        completion_summary_preview,
        completion_summary_chars,
        completion_summary_truncated: completion_summary_chars
            > TASK_RUN_COMPLETION_SUMMARY_PREVIEW_CHARS,
        final_response_present: payload
            .get("final_response_present")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        final_response_chars: payload_usize(payload, "final_response_chars").unwrap_or(0),
        replayed,
    })
}

fn task_run_completion_evidence_for_record(
    store: &BrownieStore,
    record: &TaskRecord,
    replayed: bool,
) -> Result<Option<TaskRunCompletionEvidence>, String> {
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| error.to_string())?;
    Ok(task_run_completion_evidence_from_events(
        &events, record, replayed,
    ))
}

fn llm_provider_failure_outcome_for_replay(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<(TaskRunAgentLoopSummary, LlmProviderFailureOutcome)>, String> {
    if record.status != TaskStatus::Failed {
        return Ok(None);
    }
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| error.to_string())?;
    let Some(outcome) = llm_provider_failure_outcome_from_events(&events) else {
        return Ok(None);
    };
    let agent_loop = task_run_agent_loop_summary_from_events(&events)
        .unwrap_or_else(llm_provider_failed_agent_loop_summary);
    Ok(Some((agent_loop, outcome)))
}

fn llm_provider_failure_outcome_from_events(
    events: &[LedgerEvent],
) -> Option<LlmProviderFailureOutcome> {
    events
        .iter()
        .rev()
        .find(|event| {
            matches!(
                event.kind,
                LedgerEventKind::LlmRequestFailed | LedgerEventKind::SecondPassLlmRequestFailed
            )
        })
        .and_then(|event| event.payload.as_ref())
        .and_then(llm_provider_failure_outcome_from_payload)
}

fn llm_provider_failure_outcome_from_payload(payload: &Value) -> Option<LlmProviderFailureOutcome> {
    let failure = payload.get("llm_provider_failure")?;
    let reason = failure.get("reason").and_then(Value::as_str)?.to_string();
    let reason_chars = payload_usize(failure, "reason_chars")?;
    Some(LlmProviderFailureOutcome {
        provider: failure.get("provider").and_then(Value::as_str)?.to_string(),
        model: failure.get("model").and_then(Value::as_str)?.to_string(),
        request_phase: failure
            .get("request_phase")
            .and_then(Value::as_str)?
            .to_string(),
        failure_class: failure
            .get("failure_class")
            .and_then(Value::as_str)?
            .to_string(),
        retryable: failure.get("retryable").and_then(Value::as_bool)?,
        next_action: failure
            .get("next_action")
            .and_then(Value::as_str)?
            .to_string(),
        failure_fingerprint: failure
            .get("failure_fingerprint")
            .and_then(Value::as_str)?
            .to_string(),
        reason,
        reason_chars,
        reason_truncated: failure
            .get("reason_truncated")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        http_status: failure
            .get("http_status")
            .and_then(Value::as_u64)
            .and_then(|value| u16::try_from(value).ok()),
    })
}

fn task_run_terminal_child_agent_loop_summary_from_events(
    record: &TaskRecord,
    events: &[LedgerEvent],
) -> Option<TaskRunAgentLoopSummary> {
    if let Some(agent_loop) = task_run_agent_loop_summary_from_events(events) {
        return Some(agent_loop);
    }
    if record.status != TaskStatus::Failed {
        return None;
    }
    if events.iter().any(|event| {
        matches!(
            event.kind,
            LedgerEventKind::LlmRequestFailed | LedgerEventKind::SecondPassLlmRequestFailed
        )
    }) {
        return Some(controlled_child_failed_agent_loop_summary());
    }
    None
}

fn parent_join_readiness_outcome_for_terminal_child(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<TaskRunParentJoinReadinessOutcome>, String> {
    if !matches!(record.status, TaskStatus::Completed | TaskStatus::Failed) {
        return Ok(None);
    }
    let Some(parent_task_id) = non_empty_record_string(record.parent_task_id.as_deref()) else {
        return Ok(None);
    };
    let Some(parent_run_id) = non_empty_record_string(record.parent_run_id.as_deref()) else {
        return Ok(None);
    };
    if !task_has_complete_controlled_child_provenance(record) {
        return Ok(None);
    }

    let mut controlled_children = controlled_child_records_for_parent_run(
        store,
        Some(&parent_task_id),
        &parent_run_id,
        None,
    )?;
    if !controlled_children
        .iter()
        .any(|child| child.task_id == record.task_id)
    {
        controlled_children.push(record.clone());
        sort_controlled_child_records(&mut controlled_children);
    }
    let terminal_controlled_child_count = controlled_children
        .iter()
        .filter(|child| is_parent_join_terminal_child_status(&child.status))
        .count();
    let pending_controlled_child_task_ids = controlled_children
        .iter()
        .filter(|child| is_parent_join_runnable_pending_child_status(&child.status))
        .map(|child| child.task_id.clone())
        .collect::<Vec<_>>();
    let pending_controlled_child_count = pending_controlled_child_task_ids.len();
    let non_runnable_controlled_child_task_ids = controlled_children
        .iter()
        .filter(|child| is_parent_join_non_runnable_child_status(&child.status))
        .map(|child| child.task_id.clone())
        .collect::<Vec<_>>();
    let non_runnable_controlled_child_count = non_runnable_controlled_child_task_ids.len();
    let parent_join_ready = pending_controlled_child_count == 0
        && non_runnable_controlled_child_count == 0
        && terminal_controlled_child_count > 0;
    let next_action = if non_runnable_controlled_child_count > 0 {
        "inspect_non_runnable_child_tasks"
    } else if parent_join_ready {
        "run_parent_task_explicitly"
    } else {
        "run_remaining_child_tasks_explicitly"
    };

    Ok(Some(TaskRunParentJoinReadinessOutcome {
        parent_task_id,
        parent_run_id,
        child_task_id: record.task_id.clone(),
        child_run_id: record.run_id.clone(),
        child_terminal_status: record.status.clone(),
        terminal_controlled_child_count,
        pending_controlled_child_count,
        pending_controlled_child_task_ids,
        non_runnable_controlled_child_count,
        non_runnable_controlled_child_task_ids,
        parent_join_ready,
        parent_running_enabled: false,
        next_action: next_action.to_string(),
    }))
}

fn parent_join_readiness_summary_for_parent_inspection(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<RunInspectParentJoinReadinessSummary>, String> {
    if record.parent_run_id.is_some() || record.status != TaskStatus::Completed {
        return Ok(None);
    }
    let Some(parent_task_id) = non_empty_record_string(Some(record.task_id.as_str())) else {
        return Ok(None);
    };
    let Some(parent_run_id) = non_empty_record_string(Some(record.run_id.as_str())) else {
        return Ok(None);
    };

    let controlled_children = controlled_child_records_for_parent_run(
        store,
        Some(&parent_task_id),
        &parent_run_id,
        None,
    )?;
    if controlled_children.is_empty() {
        return Ok(None);
    }

    let terminal_controlled_child_count = controlled_children
        .iter()
        .filter(|child| is_parent_join_terminal_child_status(&child.status))
        .count();
    let pending_controlled_child_task_ids = controlled_children
        .iter()
        .filter(|child| is_parent_join_runnable_pending_child_status(&child.status))
        .map(|child| child.task_id.clone())
        .collect::<Vec<_>>();
    let pending_controlled_child_count = pending_controlled_child_task_ids.len();
    let non_runnable_controlled_child_task_ids = controlled_children
        .iter()
        .filter(|child| is_parent_join_non_runnable_child_status(&child.status))
        .map(|child| child.task_id.clone())
        .collect::<Vec<_>>();
    let non_runnable_controlled_child_count = non_runnable_controlled_child_task_ids.len();
    let parent_join_ready =
        if pending_controlled_child_count == 0 && non_runnable_controlled_child_count == 0 {
            if terminal_controlled_child_count == 0 {
                return Ok(None);
            }
            for child in &controlled_children {
                if !child_has_terminal_parent_join_outcome(store, child)
                    .map_err(task_run_admission_rejection_message)?
                {
                    return Ok(None);
                }
            }
            let child_evidence = controlled_children
                .iter()
                .map(|child| {
                    parent_join_child_completion_evidence(store, child)
                        .map_err(task_run_admission_rejection_message)
                })
                .collect::<Result<Vec<_>, _>>()?;
            let (child_completion_fingerprint, _) =
                parent_join_child_completion_fingerprint(&child_evidence);
            !parent_join_child_completion_fingerprint_consumed(
                store,
                record,
                &child_completion_fingerprint,
            )
            .map_err(task_run_admission_rejection_message)?
        } else {
            false
        };
    if pending_controlled_child_count == 0
        && non_runnable_controlled_child_count == 0
        && !parent_join_ready
    {
        return Ok(None);
    }
    let next_action = if non_runnable_controlled_child_count > 0 {
        "inspect_non_runnable_child_tasks"
    } else if parent_join_ready {
        "run_parent_task_explicitly"
    } else {
        "run_remaining_child_tasks_explicitly"
    };

    Ok(Some(RunInspectParentJoinReadinessSummary {
        parent_task_id,
        parent_run_id,
        terminal_controlled_child_count,
        pending_controlled_child_count,
        pending_controlled_child_task_ids,
        non_runnable_controlled_child_count,
        non_runnable_controlled_child_task_ids,
        parent_join_ready,
        parent_running_enabled: false,
        next_action: next_action.to_string(),
    }))
}

fn consumed_parent_join_recovery_summary_for_parent_inspection(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<RunInspectConsumedParentJoinRecoverySummary>, String> {
    if record.parent_run_id.is_some() || record.status != TaskStatus::Completed {
        return Ok(None);
    }
    let Some(parent_task_id) = non_empty_record_string(Some(record.task_id.as_str())) else {
        return Ok(None);
    };
    let Some(parent_run_id) = non_empty_record_string(Some(record.run_id.as_str())) else {
        return Ok(None);
    };

    let parent_events = store
        .tasks()
        .read_ledger_events(&parent_run_id)
        .map_err(|error| error.to_string())?;
    let controlled_children = controlled_child_records_for_parent_run(
        store,
        Some(&parent_task_id),
        &parent_run_id,
        None,
    )?;
    if controlled_children.is_empty() {
        return Ok(None);
    }

    for event in parent_events.iter().rev() {
        let Some(consumption) = consumed_parent_join_fingerprint_from_event(event) else {
            continue;
        };
        if !parent_join_consumption_has_terminal_result(&parent_events, &consumption) {
            continue;
        }
        if consumed_terminal_controlled_child_set_for_consumed_parent_join(
            store,
            &parent_events,
            &controlled_children,
            &consumption,
        )?
        .is_none()
        {
            continue;
        }

        let continuation_children = continuation_controlled_children_for_consumed_parent_join(
            &parent_events,
            &controlled_children,
            &consumption,
        );
        let continuation_runnable_child_task_ids = continuation_children
            .iter()
            .filter(|child| is_parent_join_runnable_pending_child_status(&child.status))
            .map(|child| child.task_id.clone())
            .collect::<Vec<_>>();
        let continuation_runnable_child_count = continuation_runnable_child_task_ids.len();
        let continuation_non_runnable_child_task_ids = continuation_children
            .iter()
            .filter(|child| is_parent_join_non_runnable_child_status(&child.status))
            .map(|child| child.task_id.clone())
            .collect::<Vec<_>>();
        let continuation_non_runnable_child_count = continuation_non_runnable_child_task_ids.len();
        let continuation_terminal_child_count = continuation_children
            .iter()
            .filter(|child| is_parent_join_terminal_child_status(&child.status))
            .count();
        let next_action = if continuation_non_runnable_child_count > 0 {
            "inspect_non_runnable_continuation_child_tasks"
        } else if continuation_runnable_child_count > 0 {
            "run_continuation_child_tasks_explicitly"
        } else {
            "inspect_parent_task"
        };

        return Ok(Some(RunInspectConsumedParentJoinRecoverySummary {
            parent_task_id,
            parent_run_id,
            parent_join_consumed: true,
            consumed_terminal_controlled_child_count: consumption.child_completion_child_count,
            continuation_controlled_child_count: continuation_children.len(),
            continuation_runnable_child_count,
            continuation_runnable_child_task_ids,
            continuation_non_runnable_child_count,
            continuation_non_runnable_child_task_ids,
            continuation_terminal_child_count,
            parent_running_enabled: false,
            next_action: next_action.to_string(),
        }));
    }

    Ok(None)
}

