fn resolve_task_start_policy(
    mode_id: Option<&str>,
    store: &BrownieStore,
) -> Result<CompiledModePolicy, String> {
    match mode_id {
        Some(mode_id) if !mode_id.trim().is_empty() => {
            resolve_workspace_mode_policy(store, mode_id)?
                .ok_or_else(|| "invalid params: unknown mode_id".to_string())
        }
        _ => Ok(BuiltinModeRegistry::default_policy()),
    }
}

fn workspace_mode_policies(store: &BrownieStore) -> Result<Vec<CompiledModePolicy>, String> {
    let mut policies = BuiltinModeRegistry::list();
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        for policy in snapshot.policies {
            let compiled = compiled_mode_policy_from_active_snapshot(&policy)?;
            if policies
                .iter()
                .any(|existing| existing.mode_id == compiled.mode_id)
            {
                return Err(format!(
                    "active modepack mode duplicates existing mode_id: {}",
                    compiled.mode_id
                ));
            }
            policies.push(compiled);
        }
        return Ok(policies);
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(policies);
    };
    for policy in snapshot.modes {
        if policies
            .iter()
            .any(|existing| existing.mode_id == policy.mode_id)
        {
            return Err(format!(
                "modepack mode duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
        policies.push(policy);
    }
    Ok(policies)
}

fn compiled_mode_policy_from_active_snapshot(
    policy: &ActiveModePackPolicySnapshot,
) -> Result<CompiledModePolicy, String> {
    compiled_mode_policy_from_payload(&json!({
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "permissions": policy.permissions,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "completion_rules": policy.completion_rules,
    }))
    .ok_or_else(|| {
        format!(
            "active modepack policy snapshot is invalid: {}",
            policy.mode_id
        )
    })
}

fn resolve_workspace_mode_policy(
    store: &BrownieStore,
    mode_id: &str,
) -> Result<Option<CompiledModePolicy>, String> {
    Ok(workspace_mode_policies(store)?
        .into_iter()
        .find(|policy| policy.mode_id == mode_id))
}

fn agent_loop_state_name(state: AgentLoopState) -> &'static str {
    match state {
        AgentLoopState::Created => "Created",
        AgentLoopState::LoadingMode => "LoadingMode",
        AgentLoopState::BuildingContext => "BuildingContext",
        AgentLoopState::CallingLlm => "CallingLlm",
        AgentLoopState::ParsingResponse => "ParsingResponse",
        AgentLoopState::ExecutingTool => "ExecutingTool",
        AgentLoopState::ApplyingPatch => "ApplyingPatch",
        AgentLoopState::SpawningSubtask => "SpawningSubtask",
        AgentLoopState::Waiting => "Waiting",
        AgentLoopState::Verifying => "Verifying",
        AgentLoopState::Completed => "Completed",
        AgentLoopState::Failed => "Failed",
        AgentLoopState::Cancelled => "Cancelled",
    }
}

fn mode_summary(policy: CompiledModePolicy) -> ModeSummary {
    ModeSummary {
        mode_id: policy.mode_id,
        display_name: policy.display_name,
        role_definition: policy.role_definition,
        permissions: ModePermissionsSummary {
            read_only: policy.permissions.read_only,
            workspace_write: policy.permissions.workspace_write,
            process_exec: policy.permissions.process_exec,
            network_access: policy.permissions.network_access,
            service_control: policy.permissions.service_control,
            destructive: policy.permissions.destructive,
            can_spawn_subtasks: policy.permissions.can_spawn_subtasks,
            codebase_index: policy.permissions.codebase_index,
        },
    }
}

fn mode_resolved_payload(policy: &CompiledModePolicy) -> Value {
    json!({
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "completion_rules": policy.completion_rules,
        "permissions": {
            "read_only": policy.permissions.read_only,
            "workspace_write": policy.permissions.workspace_write,
            "process_exec": policy.permissions.process_exec,
            "network_access": policy.permissions.network_access,
            "service_control": policy.permissions.service_control,
            "destructive": policy.permissions.destructive,
            "can_spawn_subtasks": policy.permissions.can_spawn_subtasks,
            "codebase_index": policy.permissions.codebase_index,
        }
    })
}

fn append_mode_resolved_event(
    store: &BrownieStore,
    record: &TaskRecord,
    policy: &CompiledModePolicy,
) -> anyhow::Result<()> {
    let mut payload = mode_resolved_payload(policy);
    if let Some(provenance) = external_modepack_task_provenance_payload(store, &policy.mode_id)
        .map_err(anyhow::Error::msg)?
    {
        payload["external_modepack_task_provenance"] = provenance;
    }
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::ModeResolved,
        Some(payload),
    )
}

fn resolve_policy_for_task_run(
    record: &brownie_protocol::TaskRecord,
    store: &BrownieStore,
) -> Result<CompiledModePolicy, String> {
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| error.to_string())?;
    if let Some(policy) = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::ModeResolved)
        .and_then(|event| event.payload.as_ref())
        .and_then(compiled_mode_policy_from_payload)
    {
        return Ok(policy);
    }

    if let Some(mode_id) = record.mode_id.as_deref() {
        return resolve_workspace_mode_policy(store, mode_id)?
            .ok_or_else(|| format!("stored task has unknown mode_id: {mode_id}"));
    }

    let mode_id = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::ModeResolved)
        .and_then(|event| event.payload.as_ref())
        .and_then(|payload| payload.get("mode_id"))
        .and_then(|value| value.as_str())
        .unwrap_or(DEFAULT_MODE_ID_FOR_RUN);
    resolve_workspace_mode_policy(store, mode_id)?
        .ok_or_else(|| format!("ledger has unknown mode_id: {mode_id}"))
}

fn compiled_mode_policy_from_payload(payload: &Value) -> Option<CompiledModePolicy> {
    let permissions = payload.get("permissions")?;
    let completion_rules = payload
        .get("completion_rules")
        .and_then(Value::as_array)
        .map(|rules| {
            rules
                .iter()
                .filter_map(|rule| rule.as_str().map(ToString::to_string))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    Some(CompiledModePolicy {
        mode_id: payload.get("mode_id")?.as_str()?.to_string(),
        display_name: payload.get("display_name")?.as_str()?.to_string(),
        role_definition: payload.get("role_definition")?.as_str()?.to_string(),
        permissions: brownie_agentmodes::ModePermissions {
            read_only: permissions.get("read_only")?.as_bool()?,
            workspace_write: permissions.get("workspace_write")?.as_bool()?,
            process_exec: permissions.get("process_exec")?.as_bool()?,
            network_access: permissions.get("network_access")?.as_bool()?,
            service_control: permissions.get("service_control")?.as_bool()?,
            destructive: permissions.get("destructive")?.as_bool()?,
            can_spawn_subtasks: permissions.get("can_spawn_subtasks")?.as_bool()?,
            codebase_index: permissions
                .get("codebase_index")
                .and_then(Value::as_bool)
                .unwrap_or(false),
        },
        allowed_handoff_targets: payload
            .get("allowed_handoff_targets")
            .and_then(Value::as_array)
            .map(|targets| {
                targets
                    .iter()
                    .filter_map(|target| target.as_str().map(ToString::to_string))
                    .collect::<Vec<_>>()
            })
            .filter(|targets| !targets.is_empty()),
        completion_rules,
    })
}

fn external_modepack_policy_fingerprint(
    modepack_name: &str,
    schema_version: u64,
    policy: &CompiledModePolicy,
) -> String {
    let canonical = json!({
        "version": EXTERNAL_MODEPACK_POLICY_FINGERPRINT_VERSION,
        "modepack_name": modepack_name,
        "schema_version": schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "completion_rules": policy.completion_rules,
        "permissions": {
            "read_only": policy.permissions.read_only,
            "workspace_write": policy.permissions.workspace_write,
            "process_exec": policy.permissions.process_exec,
            "network_access": policy.permissions.network_access,
            "service_control": policy.permissions.service_control,
            "destructive": policy.permissions.destructive,
            "can_spawn_subtasks": policy.permissions.can_spawn_subtasks,
            "codebase_index": policy.permissions.codebase_index,
        }
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn external_modepack_task_provenance_payload(
    store: &BrownieStore,
    mode_id: &str,
) -> Result<Option<Value>, String> {
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        let Some(policy) = snapshot
            .policies
            .iter()
            .find(|policy| policy.mode_id == mode_id)
        else {
            return Ok(None);
        };
        return Ok(Some(json!({
            "version": EXTERNAL_MODEPACK_TASK_PROVENANCE_VERSION,
            "source_kind": snapshot.summary.source_kind,
            "modepack_name": snapshot.summary.modepack_name,
            "schema_version": snapshot.summary.schema_version,
            "source_path": snapshot.summary.source_path,
            "mode_id": policy.mode_id,
            "policy_fingerprint": policy.policy_fingerprint,
            "activation_fingerprint": snapshot.summary.activation_fingerprint,
        })));
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(None);
    };
    let Some(policy) = snapshot
        .modes
        .iter()
        .find(|policy| policy.mode_id == mode_id)
    else {
        return Ok(None);
    };
    let policy_fingerprint =
        external_modepack_policy_fingerprint(&snapshot.name, snapshot.schema_version, policy);
    Ok(Some(json!({
        "version": EXTERNAL_MODEPACK_TASK_PROVENANCE_VERSION,
        "source_kind": "workspace_modepack",
        "modepack_name": snapshot.name,
        "schema_version": snapshot.schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "mode_id": policy.mode_id,
        "policy_fingerprint": policy_fingerprint,
    })))
}

#[derive(Debug, Clone)]
struct RemoteModePackFetchResponse {
    status: u16,
    content_type: Option<String>,
    body: Vec<u8>,
}

fn fetch_remote_modepack_candidate(
    store: &BrownieStore,
    params: &ModePackFetchCandidateParams,
) -> Result<ModePackFetchCandidateResult, String> {
    validate_modepack_fetch_url(&params.url, true)?;
    fetch_remote_modepack_candidate_with(store, params, |url| fetch_modepack_url(url))
}

fn fetch_remote_modepack_candidate_with<F>(
    store: &BrownieStore,
    params: &ModePackFetchCandidateParams,
    fetcher: F,
) -> Result<ModePackFetchCandidateResult, String>
where
    F: FnOnce(&str) -> Result<RemoteModePackFetchResponse, String>,
{
    let parsed = validate_modepack_fetch_url(&params.url, false)?;
    let response = fetcher(parsed.as_str())?;
    if response.status != 200 {
        return Err(format!(
            "modepack candidate fetch failed: unsupported HTTP status {}",
            response.status
        ));
    }
    if !modepack_candidate_content_type_allowed(response.content_type.as_deref()) {
        return Err("modepack candidate fetch failed: unsupported content type".to_string());
    }
    if response.body.len() > MODEPACK_REMOTE_FETCH_MAX_BYTES {
        return Err("modepack candidate fetch failed: response exceeds byte limit".to_string());
    }
    let content_sha256 = format!("sha256:{}", hex_sha256(&response.body));
    if let Some(expected) = params.expected_content_sha256.as_deref() {
        if expected != content_sha256 {
            return Err(format!(
                "modepack candidate fetch failed: content fingerprint mismatch: expected {expected} but found {content_sha256}"
            ));
        }
    }
    let body = String::from_utf8(response.body)
        .map_err(|_| "modepack candidate fetch failed: response is not UTF-8".to_string())?;
    if scan_text_for_sensitive_content(&body) {
        return Err(
            "modepack candidate fetch failed: response contains sensitive-like content".to_string(),
        );
    }
    let snapshot = load_modepack_from_str(&body, MODEPACK_CANDIDATE_CACHE_SOURCE_PATH)
        .map_err(|error| format!("modepack candidate compile failed: {error}"))?;
    for policy in &snapshot.modes {
        if BuiltinModeRegistry::get(&policy.mode_id).is_some() {
            return Err(format!(
                "modepack candidate duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
    }
    let policies = snapshot
        .modes
        .iter()
        .map(|policy| ActiveModePackPolicySnapshot {
            mode_id: policy.mode_id.clone(),
            display_name: policy.display_name.clone(),
            role_definition: policy.role_definition.clone(),
            permissions: mode_permissions_payload(policy),
            allowed_handoff_targets: policy.allowed_handoff_targets.clone(),
            completion_rules: policy.completion_rules.clone(),
            policy_fingerprint: external_modepack_policy_fingerprint(
                &snapshot.name,
                snapshot.schema_version,
                policy,
            ),
        })
        .collect::<Vec<_>>();
    let mode_ids = policies
        .iter()
        .map(|policy| policy.mode_id.clone())
        .collect::<Vec<_>>();
    let compiled_policy_fingerprint = active_modepack_compiled_policy_fingerprint(
        &snapshot.name,
        snapshot.schema_version,
        &policies,
    );
    let summary = ModePackCandidateSummary {
        candidate_id: format!("modepack_candidate_{}", &content_sha256[7..23]),
        source_kind: "remote_https".to_string(),
        source_url_host: parsed.host_str().unwrap_or_default().to_string(),
        source_url_fingerprint: format!("sha256:{}", hex_sha256(parsed.as_str().as_bytes())),
        content_sha256,
        byte_count: body.len(),
        modepack_name: snapshot.name,
        schema_version: snapshot.schema_version,
        mode_count: mode_ids.len(),
        mode_ids,
        compiled_policy_fingerprint,
        cached_at: codebase_index_timestamp().map_err(|error| error.to_string())?,
        cache_event_id: String::new(),
    };
    let candidate_snapshot = ModePackCandidateSnapshot {
        summary,
        modepack_json: body,
    };
    let committed = store
        .commit_modepack_candidate_snapshot(&candidate_snapshot)
        .map_err(|error| format!("modepack candidate cache failed: {error}"))?;
    Ok(ModePackFetchCandidateResult {
        fetched: !committed.replayed,
        replayed: committed.replayed,
        candidate: committed.snapshot.summary,
        next_action: "review_candidate_then_replace_active_modepack".to_string(),
    })
}

fn approve_remote_modepack_candidate(
    store: &BrownieStore,
    params: &ModePackApproveCandidateParams,
) -> Result<ModePackApproveCandidateResult, String> {
    let cached = store
        .read_modepack_candidate_snapshot(&params.expected_content_sha256)
        .map_err(|error| format!("modepack candidate approval failed: {error}"))?
        .ok_or_else(|| {
            "modepack candidate approval failed: cached candidate not found".to_string()
        })?;
    let actual_content_sha256 = format!("sha256:{}", hex_sha256(cached.modepack_json.as_bytes()));
    if actual_content_sha256 != params.expected_content_sha256 {
        return Err(format!(
            "modepack candidate approval failed: cached content fingerprint mismatch: expected {} but found {}",
            params.expected_content_sha256, actual_content_sha256
        ));
    }
    if cached.summary.content_sha256 != params.expected_content_sha256 {
        return Err(format!(
            "modepack candidate approval failed: cached summary fingerprint mismatch: expected {} but found {}",
            params.expected_content_sha256, cached.summary.content_sha256
        ));
    }
    let recompiled =
        load_modepack_from_str(&cached.modepack_json, MODEPACK_CANDIDATE_CACHE_SOURCE_PATH)
            .map_err(|error| format!("modepack candidate approval compile failed: {error}"))?;
    for policy in &recompiled.modes {
        if BuiltinModeRegistry::get(&policy.mode_id).is_some() {
            return Err(format!(
                "modepack candidate approval failed: candidate duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
    }
    let policy_snapshots = recompiled
        .modes
        .iter()
        .map(|policy| ActiveModePackPolicySnapshot {
            mode_id: policy.mode_id.clone(),
            display_name: policy.display_name.clone(),
            role_definition: policy.role_definition.clone(),
            permissions: mode_permissions_payload(policy),
            allowed_handoff_targets: policy.allowed_handoff_targets.clone(),
            completion_rules: policy.completion_rules.clone(),
            policy_fingerprint: external_modepack_policy_fingerprint(
                &recompiled.name,
                recompiled.schema_version,
                policy,
            ),
        })
        .collect::<Vec<_>>();
    let mode_ids = policy_snapshots
        .iter()
        .map(|policy| policy.mode_id.clone())
        .collect::<Vec<_>>();
    let compiled_policy_fingerprint = active_modepack_compiled_policy_fingerprint(
        &recompiled.name,
        recompiled.schema_version,
        &policy_snapshots,
    );
    if compiled_policy_fingerprint != params.expected_compiled_policy_fingerprint {
        return Err(format!(
            "modepack candidate approval failed: compiled policy fingerprint mismatch: expected {} but found {}",
            params.expected_compiled_policy_fingerprint, compiled_policy_fingerprint
        ));
    }
    if cached.summary.compiled_policy_fingerprint != params.expected_compiled_policy_fingerprint {
        return Err(format!(
            "modepack candidate approval failed: cached summary policy fingerprint mismatch: expected {} but found {}",
            params.expected_compiled_policy_fingerprint, cached.summary.compiled_policy_fingerprint
        ));
    }
    if cached.summary.mode_ids != mode_ids {
        return Err("modepack candidate approval failed: cached mode ids are stale".to_string());
    }

    let approved_at = codebase_index_timestamp().map_err(|error| error.to_string())?;
    let approval_summary = ModePackApprovedCandidateSummary {
        approval_id: format!(
            "modepack_candidate_approval_{}",
            &actual_content_sha256[7..23]
        ),
        candidate_id: cached.summary.candidate_id,
        source_kind: cached.summary.source_kind,
        source_url_host: cached.summary.source_url_host,
        source_url_fingerprint: cached.summary.source_url_fingerprint,
        content_sha256: params.expected_content_sha256.clone(),
        modepack_name: recompiled.name,
        schema_version: recompiled.schema_version,
        mode_count: mode_ids.len(),
        mode_ids,
        compiled_policy_fingerprint,
        approved_at,
        approval_event_id: String::new(),
        consumed: false,
    };
    let committed = store
        .approve_modepack_candidate_snapshot(&ModePackApprovedCandidateSnapshot {
            summary: approval_summary,
        })
        .map_err(|error| format!("modepack candidate approval failed: {error}"))?;
    Ok(ModePackApproveCandidateResult {
        approved: !committed.replayed,
        replayed: committed.replayed,
        approval: committed.approval.summary,
        next_action: "replace_active_with_approved_modepack_candidate".to_string(),
    })
}

fn verify_modepack_candidate_provenance(
    store: &BrownieStore,
    params: &ModePackVerifyCandidateProvenanceParams,
) -> Result<ModePackVerifyCandidateProvenanceResult, String> {
    if params.provenance_statement_json.as_bytes().len() > MODEPACK_PROVENANCE_STATEMENT_MAX_BYTES {
        return Err(
            "modepack candidate provenance verification failed: statement exceeds byte limit"
                .to_string(),
        );
    }
    if scan_text_for_sensitive_content(&params.provenance_statement_json) {
        return Err(
            "modepack candidate provenance verification failed: statement contains sensitive-like content"
                .to_string(),
        );
    }
    let public_key_bytes = general_purpose::STANDARD
        .decode(&params.provenance_public_key_base64)
        .map_err(|_| {
            "modepack candidate provenance verification failed: public key is not base64"
                .to_string()
        })?;
    if public_key_bytes.len() != 32 {
        return Err(
            "modepack candidate provenance verification failed: public key must be 32 bytes"
                .to_string(),
        );
    }
    let signature_bytes = general_purpose::STANDARD
        .decode(&params.provenance_signature_base64)
        .map_err(|_| {
            "modepack candidate provenance verification failed: signature is not base64".to_string()
        })?;
    if signature_bytes.len() != 64 {
        return Err(
            "modepack candidate provenance verification failed: signature must be 64 bytes"
                .to_string(),
        );
    }
    let signer_fingerprint = format!("sha256:{}", hex_sha256(&public_key_bytes));
    if signer_fingerprint != params.expected_signer_fingerprint {
        return Err(format!(
            "modepack candidate provenance verification failed: signer fingerprint mismatch: expected {} but found {}",
            params.expected_signer_fingerprint, signer_fingerprint
        ));
    }
    let verifying_key =
        VerifyingKey::from_bytes(public_key_bytes.as_slice().try_into().map_err(|_| {
            "modepack candidate provenance verification failed: public key length invalid"
                .to_string()
        })?)
        .map_err(|_| {
            "modepack candidate provenance verification failed: public key invalid".to_string()
        })?;
    let signature = Signature::from_slice(&signature_bytes).map_err(|_| {
        "modepack candidate provenance verification failed: signature invalid".to_string()
    })?;
    verifying_key
        .verify(params.provenance_statement_json.as_bytes(), &signature)
        .map_err(|_| {
            "modepack candidate provenance verification failed: bad signature".to_string()
        })?;
    let statement: Value =
        serde_json::from_str(&params.provenance_statement_json).map_err(|_| {
            "modepack candidate provenance verification failed: statement is not JSON".to_string()
        })?;
    let cached = store
        .read_modepack_candidate_snapshot(&params.expected_content_sha256)
        .map_err(|error| format!("modepack candidate provenance verification failed: {error}"))?
        .ok_or_else(|| {
            "modepack candidate provenance verification failed: cached candidate not found"
                .to_string()
        })?;
    let actual_content_sha256 = format!("sha256:{}", hex_sha256(cached.modepack_json.as_bytes()));
    if actual_content_sha256 != params.expected_content_sha256 {
        return Err(format!(
            "modepack candidate provenance verification failed: cached content fingerprint mismatch: expected {} but found {}",
            params.expected_content_sha256, actual_content_sha256
        ));
    }
    if cached.summary.content_sha256 != params.expected_content_sha256 {
        return Err(format!(
            "modepack candidate provenance verification failed: cached summary fingerprint mismatch: expected {} but found {}",
            params.expected_content_sha256, cached.summary.content_sha256
        ));
    }
    let recompiled =
        load_modepack_from_str(&cached.modepack_json, MODEPACK_CANDIDATE_CACHE_SOURCE_PATH)
            .map_err(|error| {
                format!("modepack candidate provenance verification compile failed: {error}")
            })?;
    for policy in &recompiled.modes {
        if BuiltinModeRegistry::get(&policy.mode_id).is_some() {
            return Err(format!(
                "modepack candidate provenance verification failed: candidate duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
    }
    let policy_snapshots = recompiled
        .modes
        .iter()
        .map(|policy| ActiveModePackPolicySnapshot {
            mode_id: policy.mode_id.clone(),
            display_name: policy.display_name.clone(),
            role_definition: policy.role_definition.clone(),
            permissions: mode_permissions_payload(policy),
            allowed_handoff_targets: policy.allowed_handoff_targets.clone(),
            completion_rules: policy.completion_rules.clone(),
            policy_fingerprint: external_modepack_policy_fingerprint(
                &recompiled.name,
                recompiled.schema_version,
                policy,
            ),
        })
        .collect::<Vec<_>>();
    let mode_ids = policy_snapshots
        .iter()
        .map(|policy| policy.mode_id.clone())
        .collect::<Vec<_>>();
    let compiled_policy_fingerprint = active_modepack_compiled_policy_fingerprint(
        &recompiled.name,
        recompiled.schema_version,
        &policy_snapshots,
    );
    if compiled_policy_fingerprint != params.expected_compiled_policy_fingerprint {
        return Err(format!(
            "modepack candidate provenance verification failed: compiled policy fingerprint mismatch: expected {} but found {}",
            params.expected_compiled_policy_fingerprint, compiled_policy_fingerprint
        ));
    }
    if cached.summary.compiled_policy_fingerprint != params.expected_compiled_policy_fingerprint {
        return Err(format!(
            "modepack candidate provenance verification failed: cached summary policy fingerprint mismatch: expected {} but found {}",
            params.expected_compiled_policy_fingerprint, cached.summary.compiled_policy_fingerprint
        ));
    }
    if cached.summary.mode_ids != mode_ids {
        return Err(
            "modepack candidate provenance verification failed: cached mode ids are stale"
                .to_string(),
        );
    }
    validate_modepack_provenance_statement(
        &statement,
        &cached.summary,
        &mode_ids,
        recompiled.schema_version,
        &params.expected_content_sha256,
        &params.expected_compiled_policy_fingerprint,
        &signer_fingerprint,
    )?;

    let provenance_summary = ModePackCandidateProvenanceSummary {
        provenance_id: format!(
            "modepack_candidate_provenance_{}",
            &actual_content_sha256[7..23]
        ),
        candidate_id: cached.summary.candidate_id,
        source_kind: cached.summary.source_kind,
        source_url_host: cached.summary.source_url_host,
        source_url_fingerprint: cached.summary.source_url_fingerprint,
        content_sha256: params.expected_content_sha256.clone(),
        modepack_name: recompiled.name,
        schema_version: recompiled.schema_version,
        mode_count: mode_ids.len(),
        mode_ids,
        compiled_policy_fingerprint,
        signer_fingerprint,
        statement_sha256: format!(
            "sha256:{}",
            hex_sha256(params.provenance_statement_json.as_bytes())
        ),
        signature_sha256: format!("sha256:{}", hex_sha256(&signature_bytes)),
        verified_at: codebase_index_timestamp().map_err(|error| error.to_string())?,
        provenance_event_id: String::new(),
    };
    let committed = store
        .verify_modepack_candidate_provenance_snapshot(&ModePackCandidateProvenanceSnapshot {
            summary: provenance_summary,
        })
        .map_err(|error| format!("modepack candidate provenance verification failed: {error}"))?;
    Ok(ModePackVerifyCandidateProvenanceResult {
        verified: !committed.replayed,
        replayed: committed.replayed,
        provenance: committed.provenance.summary,
        next_action: "approve_verified_modepack_candidate".to_string(),
    })
}

fn validate_modepack_provenance_statement(
    statement: &Value,
    cached_summary: &ModePackCandidateSummary,
    mode_ids: &[String],
    schema_version: u64,
    expected_content_sha256: &str,
    expected_compiled_policy_fingerprint: &str,
    signer_fingerprint: &str,
) -> Result<(), String> {
    if statement.get("content_sha256").and_then(Value::as_str) != Some(expected_content_sha256) {
        return Err(
            "modepack candidate provenance verification failed: statement content fingerprint mismatch"
                .to_string(),
        );
    }
    if statement
        .get("compiled_policy_fingerprint")
        .and_then(Value::as_str)
        != Some(expected_compiled_policy_fingerprint)
    {
        return Err(
            "modepack candidate provenance verification failed: statement policy fingerprint mismatch"
                .to_string(),
        );
    }
    if statement
        .get("source_url_fingerprint")
        .and_then(Value::as_str)
        != Some(cached_summary.source_url_fingerprint.as_str())
    {
        return Err(
            "modepack candidate provenance verification failed: statement source fingerprint mismatch"
                .to_string(),
        );
    }
    if statement.get("schema_version").and_then(Value::as_u64) != Some(schema_version) {
        return Err(
            "modepack candidate provenance verification failed: statement schema version mismatch"
                .to_string(),
        );
    }
    if statement.get("signer_fingerprint").and_then(Value::as_str) != Some(signer_fingerprint) {
        return Err(
            "modepack candidate provenance verification failed: statement signer fingerprint mismatch"
                .to_string(),
        );
    }
    if !statement
        .get("signer_identity")
        .and_then(Value::as_str)
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
    {
        return Err(
            "modepack candidate provenance verification failed: statement signer identity missing"
                .to_string(),
        );
    }
    let statement_mode_ids = statement
        .get("mode_ids")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            "modepack candidate provenance verification failed: statement mode_ids missing"
                .to_string()
        })?
        .iter()
        .map(|value| {
            value.as_str().map(ToString::to_string).ok_or_else(|| {
                "modepack candidate provenance verification failed: statement mode_ids invalid"
                    .to_string()
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    if statement_mode_ids != mode_ids {
        return Err(
            "modepack candidate provenance verification failed: statement mode ids mismatch"
                .to_string(),
        );
    }
    Ok(())
}

fn validate_modepack_fetch_url(value: &str, resolve_addresses: bool) -> Result<url::Url, String> {
    let parsed =
        url::Url::parse(value).map_err(|_| "modepack candidate URL is invalid".to_string())?;
    if parsed.scheme() != "https" {
        return Err("modepack candidate URL must use https".to_string());
    }
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("modepack candidate URL must not contain credentials".to_string());
    }
    if parsed.fragment().is_some() {
        return Err("modepack candidate URL must not contain a fragment".to_string());
    }
    if !matches!(parsed.port_or_known_default(), Some(443)) {
        return Err("modepack candidate URL uses an unsupported port".to_string());
    }
    let host = parsed
        .host_str()
        .ok_or_else(|| "modepack candidate URL host is required".to_string())?;
    if host.eq_ignore_ascii_case("localhost") {
        return Err("modepack candidate URL host is not allowed".to_string());
    }
    if let Ok(ip) = host.parse::<IpAddr>() {
        if private_or_special_ip(ip) {
            return Err("modepack candidate URL resolves to a disallowed address".to_string());
        }
    }
    if resolve_addresses {
        let addrs = (host, 443)
            .to_socket_addrs()
            .map_err(|error| format!("modepack candidate URL resolution failed: {error}"))?;
        for addr in addrs {
            if private_or_special_ip(addr.ip()) {
                return Err("modepack candidate URL resolves to a disallowed address".to_string());
            }
        }
    }
    Ok(parsed)
}

fn private_or_special_ip(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(ip) => {
            ip.is_private()
                || ip.is_loopback()
                || ip.is_link_local()
                || ip.is_broadcast()
                || ip.octets()[0] == 0
                || matches!(
                    ip.octets(),
                    [192, 0, 2, _] | [198, 51, 100, _] | [203, 0, 113, _]
                )
        }
        IpAddr::V6(ip) => {
            ip.is_loopback()
                || ip.is_unspecified()
                || ip.is_unique_local()
                || ip.is_unicast_link_local()
                || ip.segments()[0] == 0x2001 && ip.segments()[1] == 0x0db8
        }
    }
}

fn modepack_candidate_content_type_allowed(content_type: Option<&str>) -> bool {
    let Some(content_type) = content_type else {
        return true;
    };
    let media_type = content_type
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    matches!(
        media_type.as_str(),
        "application/json" | "text/json" | "text/plain" | "application/octet-stream"
    )
}

fn fetch_modepack_url(url: &str) -> Result<RemoteModePackFetchResponse, String> {
    let client = reqwest::blocking::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(MODEPACK_REMOTE_FETCH_TIMEOUT)
        .build()
        .map_err(|error| format!("modepack candidate fetch client failed: {error}"))?;
    let mut response = client
        .get(url)
        .send()
        .map_err(|error| format!("modepack candidate fetch failed: {error}"))?;
    if response.status().is_redirection() {
        return Err("modepack candidate fetch failed: redirects are not allowed".to_string());
    }
    let status = response.status().as_u16();
    let content_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(ToString::to_string);
    let mut body = Vec::new();
    response
        .copy_to(&mut body)
        .map_err(|error| format!("modepack candidate response read failed: {error}"))?;
    Ok(RemoteModePackFetchResponse {
        status,
        content_type,
        body,
    })
}

fn activate_workspace_modepack(store: &BrownieStore) -> Result<ModePackActivateResult, String> {
    let snapshot = build_active_modepack_snapshot(store)?;
    let committed = store
        .commit_active_modepack_snapshot(&snapshot)
        .map_err(|error| format!("modepack activation failed: {error}"))?;
    Ok(ModePackActivateResult {
        activated: !committed.replayed,
        replayed: committed.replayed,
        snapshot: committed.snapshot.summary,
    })
}

fn replace_active_workspace_modepack(
    store: &BrownieStore,
    params: &ModePackReplaceActiveParams,
) -> Result<ModePackReplaceActiveResult, String> {
    let approved_candidate = match (
        params.approved_candidate_approval_id.as_deref(),
        params.expected_approved_candidate_content_sha256.as_deref(),
        params
            .expected_approved_candidate_compiled_policy_fingerprint
            .as_deref(),
    ) {
        (None, None, None) => None,
        (Some(approval_id), Some(content_sha256), Some(policy_fingerprint)) => Some((
            approval_id,
            content_sha256,
            policy_fingerprint,
            build_active_modepack_snapshot_from_approved_candidate(
                store,
                approval_id,
                content_sha256,
                policy_fingerprint,
            )?,
        )),
        _ => {
            return Err(
                "modepack replacement failed: approved candidate activation requires approval id, content sha256, and compiled policy fingerprint".to_string(),
            )
        }
    };
    let snapshot = match approved_candidate.as_ref() {
        Some((_, _, _, (snapshot, approved))) => {
            if approved.consumed {
                let active = store
                    .read_active_modepack_snapshot()
                    .map_err(|error| format!("modepack replacement failed: {error}"))?
                    .ok_or_else(|| {
                        "modepack replacement failed: missing active modepack snapshot".to_string()
                    })?;
                if active.summary.activation_fingerprint
                    != params.expected_candidate_activation_fingerprint
                {
                    return Err(
                        "modepack replacement failed: approved candidate is already consumed"
                            .to_string(),
                    );
                }
            }
            snapshot.clone()
        }
        None => build_active_modepack_snapshot(store)?,
    };
    if snapshot.summary.activation_fingerprint != params.expected_candidate_activation_fingerprint {
        return Err(format!(
            "modepack replacement failed: candidate activation fingerprint mismatch: expected {} but found {}",
            params.expected_candidate_activation_fingerprint,
            snapshot.summary.activation_fingerprint
        ));
    }
    let committed = store
        .replace_active_modepack_snapshot(
            &params.expected_current_activation_fingerprint,
            &snapshot,
        )
        .map_err(|error| format!("modepack replacement failed: {error}"))?;
    let mut result = ModePackReplaceActiveResult {
        replaced: !committed.replayed,
        replayed: committed.replayed,
        previous_snapshot: committed.previous_snapshot.summary,
        replacement_snapshot: committed.replacement_snapshot.summary,
        replacement_event_id: committed.event_id,
        approved_candidate: None,
        candidate_consumed_event_id: None,
    };
    if let Some((approval_id, content_sha256, _, _)) = approved_candidate {
        let consumed = store
            .consume_approved_modepack_candidate(
                content_sha256,
                approval_id,
                &result.replacement_event_id,
                &result.replacement_snapshot.activation_fingerprint,
            )
            .map_err(|error| format!("modepack replacement failed: {error}"))?;
        result.approved_candidate = Some(consumed.approval.summary);
        result.candidate_consumed_event_id = Some(consumed.event_id);
    }
    Ok(result)
}

fn build_active_modepack_snapshot_from_approved_candidate(
    store: &BrownieStore,
    approval_id: &str,
    content_sha256: &str,
    compiled_policy_fingerprint: &str,
) -> Result<(ActiveModePackSnapshot, ModePackApprovedCandidateSummary), String> {
    let approved = store
        .read_approved_modepack_candidate_snapshot(content_sha256)
        .map_err(|error| format!("approved modepack candidate load failed: {error}"))?
        .ok_or_else(|| "approved modepack candidate load failed: approval not found".to_string())?;
    if approved.summary.approval_id != approval_id {
        return Err(format!(
            "approved modepack candidate load failed: approval id mismatch: expected {} but found {}",
            approval_id, approved.summary.approval_id
        ));
    }
    if approved.summary.compiled_policy_fingerprint != compiled_policy_fingerprint {
        return Err(format!(
            "approved modepack candidate load failed: compiled policy fingerprint mismatch: expected {} but found {}",
            compiled_policy_fingerprint, approved.summary.compiled_policy_fingerprint
        ));
    }
    let cached = store
        .read_modepack_candidate_snapshot(content_sha256)
        .map_err(|error| format!("approved modepack candidate cache load failed: {error}"))?
        .ok_or_else(|| {
            "approved modepack candidate cache load failed: cached candidate not found".to_string()
        })?;
    let actual_content_sha256 = format!("sha256:{}", hex_sha256(cached.modepack_json.as_bytes()));
    if actual_content_sha256 != content_sha256 {
        return Err(format!(
            "approved modepack candidate cache load failed: cached content fingerprint mismatch: expected {} but found {}",
            content_sha256, actual_content_sha256
        ));
    }
    let snapshot =
        load_modepack_from_str(&cached.modepack_json, MODEPACK_CANDIDATE_CACHE_SOURCE_PATH)
            .map_err(|error| format!("approved modepack candidate compile failed: {error}"))?;
    for policy in &snapshot.modes {
        if BuiltinModeRegistry::get(&policy.mode_id).is_some() {
            return Err(format!(
                "approved modepack candidate compile failed: candidate duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
    }
    let policies = snapshot
        .modes
        .iter()
        .map(|policy| {
            let policy_fingerprint = external_modepack_policy_fingerprint(
                &snapshot.name,
                snapshot.schema_version,
                policy,
            );
            ActiveModePackPolicySnapshot {
                mode_id: policy.mode_id.clone(),
                display_name: policy.display_name.clone(),
                role_definition: policy.role_definition.clone(),
                permissions: mode_permissions_payload(policy),
                allowed_handoff_targets: policy.allowed_handoff_targets.clone(),
                completion_rules: policy.completion_rules.clone(),
                policy_fingerprint,
            }
        })
        .collect::<Vec<_>>();
    let mode_ids = policies
        .iter()
        .map(|policy| policy.mode_id.clone())
        .collect::<Vec<_>>();
    let actual_compiled_policy_fingerprint = active_modepack_compiled_policy_fingerprint(
        &snapshot.name,
        snapshot.schema_version,
        &policies,
    );
    if actual_compiled_policy_fingerprint != compiled_policy_fingerprint {
        return Err(format!(
            "approved modepack candidate compile failed: compiled policy fingerprint mismatch: expected {} but found {}",
            compiled_policy_fingerprint, actual_compiled_policy_fingerprint
        ));
    }
    if cached.summary.compiled_policy_fingerprint != compiled_policy_fingerprint
        || cached.summary.content_sha256 != content_sha256
        || cached.summary.mode_ids != mode_ids
        || approved.summary.candidate_id != cached.summary.candidate_id
    {
        return Err(
            "approved modepack candidate load failed: cached candidate summary is stale"
                .to_string(),
        );
    }
    let activated_at = codebase_index_timestamp().map_err(|error| error.to_string())?;
    let activation_fingerprint = active_modepack_activation_fingerprint(
        &snapshot.name,
        snapshot.schema_version,
        &actual_compiled_policy_fingerprint,
        &mode_ids,
    );
    let summary = ModePackActiveSnapshotSummary {
        activation_id: format!("modepack_activation_{}", &activation_fingerprint[7..23]),
        activation_fingerprint,
        modepack_name: snapshot.name,
        schema_version: snapshot.schema_version,
        source_kind: "remote_https_candidate".to_string(),
        source_path: cached.summary.candidate_id,
        mode_count: mode_ids.len(),
        mode_ids,
        compiled_policy_fingerprint: actual_compiled_policy_fingerprint,
        activated_at,
        activation_event_id: String::new(),
    };
    Ok((
        ActiveModePackSnapshot { summary, policies },
        approved.summary,
    ))
}

fn rollback_active_workspace_modepack(
    store: &BrownieStore,
    params: &ModePackRollbackActiveParams,
) -> Result<ModePackRollbackActiveResult, String> {
    let committed = store
        .rollback_active_modepack_snapshot(
            &params.expected_current_activation_fingerprint,
            &params.expected_rollback_activation_fingerprint,
        )
        .map_err(|error| format!("modepack rollback failed: {error}"))?;
    Ok(ModePackRollbackActiveResult {
        rolled_back: !committed.replayed,
        replayed: committed.replayed,
        current_snapshot: committed.current_snapshot.summary,
        restored_snapshot: committed.restored_snapshot.summary,
        rollback_event_id: committed.event_id,
    })
}

fn build_active_modepack_snapshot(store: &BrownieStore) -> Result<ActiveModePackSnapshot, String> {
    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Err("modepack activation failed: missing .brownie/modepack.json".to_string());
    };
    for policy in &snapshot.modes {
        if BuiltinModeRegistry::get(&policy.mode_id).is_some() {
            return Err(format!(
                "modepack mode duplicates existing mode_id: {}",
                policy.mode_id
            ));
        }
    }
    let activated_at = codebase_index_timestamp().map_err(|error| error.to_string())?;
    let policy_snapshots = snapshot
        .modes
        .iter()
        .map(|policy| {
            let policy_fingerprint = external_modepack_policy_fingerprint(
                &snapshot.name,
                snapshot.schema_version,
                policy,
            );
            ActiveModePackPolicySnapshot {
                mode_id: policy.mode_id.clone(),
                display_name: policy.display_name.clone(),
                role_definition: policy.role_definition.clone(),
                permissions: mode_permissions_payload(policy),
                allowed_handoff_targets: policy.allowed_handoff_targets.clone(),
                completion_rules: policy.completion_rules.clone(),
                policy_fingerprint,
            }
        })
        .collect::<Vec<_>>();
    let mode_ids = policy_snapshots
        .iter()
        .map(|policy| policy.mode_id.clone())
        .collect::<Vec<_>>();
    let compiled_policy_fingerprint = active_modepack_compiled_policy_fingerprint(
        &snapshot.name,
        snapshot.schema_version,
        &policy_snapshots,
    );
    let activation_fingerprint = active_modepack_activation_fingerprint(
        &snapshot.name,
        snapshot.schema_version,
        &compiled_policy_fingerprint,
        &mode_ids,
    );
    let summary = ModePackActiveSnapshotSummary {
        activation_id: format!("modepack_activation_{}", &activation_fingerprint[7..23]),
        activation_fingerprint,
        modepack_name: snapshot.name,
        schema_version: snapshot.schema_version,
        source_kind: "workspace_modepack".to_string(),
        source_path: WORKSPACE_MODEPACK_PATH.to_string(),
        mode_count: mode_ids.len(),
        mode_ids,
        compiled_policy_fingerprint,
        activated_at,
        activation_event_id: String::new(),
    };
    Ok(ActiveModePackSnapshot {
        summary,
        policies: policy_snapshots,
    })
}

fn mode_permissions_payload(policy: &CompiledModePolicy) -> Value {
    json!({
        "read_only": policy.permissions.read_only,
        "workspace_write": policy.permissions.workspace_write,
        "process_exec": policy.permissions.process_exec,
        "network_access": policy.permissions.network_access,
        "service_control": policy.permissions.service_control,
        "destructive": policy.permissions.destructive,
        "can_spawn_subtasks": policy.permissions.can_spawn_subtasks,
        "codebase_index": policy.permissions.codebase_index,
    })
}

fn active_modepack_compiled_policy_fingerprint(
    modepack_name: &str,
    schema_version: u64,
    policies: &[ActiveModePackPolicySnapshot],
) -> String {
    let canonical = json!({
        "version": "active_modepack_compiled_policy_fingerprint_v1",
        "modepack_name": modepack_name,
        "schema_version": schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "policies": policies,
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn active_modepack_activation_fingerprint(
    modepack_name: &str,
    schema_version: u64,
    compiled_policy_fingerprint: &str,
    mode_ids: &[String],
) -> String {
    let canonical = json!({
        "version": "active_modepack_activation_fingerprint_v1",
        "modepack_name": modepack_name,
        "schema_version": schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "mode_ids": mode_ids,
        "compiled_policy_fingerprint": compiled_policy_fingerprint,
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn external_modepack_task_provenance_from_mode_resolved(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<Option<Value>, TaskRunAdmissionRejection> {
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| TaskRunAdmissionRejection::Internal(error.to_string()))?;
    Ok(events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::ModeResolved)
        .and_then(|event| event.payload.as_ref())
        .and_then(|payload| payload.get("external_modepack_task_provenance"))
        .cloned())
}

fn direct_external_modepack_task_requires_provenance(record: &TaskRecord) -> bool {
    record.parent_run_id.is_none()
        && record.parent_task_id.is_none()
        && record
            .mode_id
            .as_deref()
            .is_some_and(|mode_id| BuiltinModeRegistry::get(mode_id).is_none())
}

fn revalidate_external_modepack_task_provenance_for_run(
    store: &BrownieStore,
    record: &TaskRecord,
) -> Result<(), TaskRunAdmissionRejection> {
    if record.parent_run_id.is_some() || record.parent_task_id.is_some() {
        return Ok(());
    }

    let provenance = external_modepack_task_provenance_from_mode_resolved(store, record)?;
    let Some(provenance) = provenance else {
        if direct_external_modepack_task_requires_provenance(record) {
            return external_modepack_task_provenance_denied(
                record,
                store,
                "missing_external_modepack_task_provenance",
                "invalid params: external Mode Pack task provenance is missing",
            );
        }
        return Ok(());
    };

    let Some(mode_id) = record.mode_id.as_deref() else {
        return external_modepack_task_provenance_denied(
            record,
            store,
            "missing_task_mode_id",
            "invalid params: external Mode Pack task provenance is invalid",
        );
    };
    if provenance.get("version").and_then(Value::as_str)
        != Some(EXTERNAL_MODEPACK_TASK_PROVENANCE_VERSION)
        || provenance.get("source_kind").and_then(Value::as_str) != Some("workspace_modepack")
        || provenance.get("source_path").and_then(Value::as_str) != Some(WORKSPACE_MODEPACK_PATH)
        || provenance.get("mode_id").and_then(Value::as_str) != Some(mode_id)
    {
        return external_modepack_task_provenance_denied(
            record,
            store,
            "malformed_external_modepack_task_provenance",
            "invalid params: external Mode Pack task provenance is invalid",
        );
    }
    let Some(captured_fingerprint) = provenance
        .get("policy_fingerprint")
        .and_then(Value::as_str)
        .filter(|value| value.starts_with("sha256:") && value.len() == "sha256:".len() + 64)
    else {
        return external_modepack_task_provenance_denied(
            record,
            store,
            "malformed_external_modepack_policy_fingerprint",
            "invalid params: external Mode Pack task provenance is invalid",
        );
    };
    let current = match external_modepack_task_provenance_payload(store, mode_id) {
        Ok(current) => current,
        Err(_) => {
            return external_modepack_task_provenance_denied(
                record,
                store,
                "malformed_external_modepack_task_policy",
                "invalid params: external Mode Pack task provenance is stale",
            );
        }
    };
    let Some(current) = current else {
        return external_modepack_task_provenance_denied(
            record,
            store,
            "stale_external_modepack_task_policy_missing",
            "invalid params: external Mode Pack task provenance is stale",
        );
    };
    for key in [
        "modepack_name",
        "schema_version",
        "source_path",
        "mode_id",
        "policy_fingerprint",
    ] {
        if provenance.get(key) != current.get(key) {
            return external_modepack_task_provenance_denied(
                record,
                store,
                "stale_external_modepack_task_policy_mismatch",
                "invalid params: external Mode Pack task provenance is stale",
            );
        }
    }
    if current.get("policy_fingerprint").and_then(Value::as_str) != Some(captured_fingerprint) {
        return external_modepack_task_provenance_denied(
            record,
            store,
            "stale_external_modepack_task_policy_mismatch",
            "invalid params: external Mode Pack task provenance is stale",
        );
    }
    Ok(())
}

fn external_modepack_task_provenance_denied(
    record: &TaskRecord,
    store: &BrownieStore,
    reason: &'static str,
    message: &'static str,
) -> Result<(), TaskRunAdmissionRejection> {
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| TaskRunAdmissionRejection::Internal(error.to_string()))?;
    if !events.iter().any(|event| {
        event.kind == LedgerEventKind::ExternalModePackTaskProvenanceDenied
            && event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("reason"))
                .and_then(Value::as_str)
                == Some(reason)
    }) {
        store
            .tasks()
            .append_task_event_with_payload(
                record,
                LedgerEventKind::ExternalModePackTaskProvenanceDenied,
                Some(json!({
                    "status": "Denied",
                    "reason": reason,
                    "task_id": record.task_id,
                    "run_id": record.run_id,
                    "mode_id": record.mode_id,
                    "source_kind": "workspace_modepack",
                    "source_path": WORKSPACE_MODEPACK_PATH,
                })),
            )
            .map_err(|error| TaskRunAdmissionRejection::Internal(error.to_string()))?;
    }
    Err(TaskRunAdmissionRejection::InvalidParams(message))
}

fn external_modepack_child_provenance_payload(
    store: &BrownieStore,
    child_mode_id: &str,
    parent_run_id: &str,
    source_handoff_envelope_id: &str,
    source_handoff_envelope_fingerprint: &str,
) -> Result<Option<Value>, String> {
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        let Some(policy) = snapshot
            .policies
            .iter()
            .find(|policy| policy.mode_id == child_mode_id)
        else {
            return Ok(None);
        };
        return Ok(Some(json!({
            "version": EXTERNAL_MODEPACK_CHILD_PROVENANCE_VERSION,
            "source_kind": snapshot.summary.source_kind,
            "modepack_name": snapshot.summary.modepack_name,
            "schema_version": snapshot.summary.schema_version,
            "source_path": snapshot.summary.source_path,
            "mode_id": policy.mode_id,
            "policy_fingerprint": policy.policy_fingerprint,
            "activation_fingerprint": snapshot.summary.activation_fingerprint,
            "captured_parent_run_id": parent_run_id,
            "captured_handoff_envelope_id": source_handoff_envelope_id,
            "captured_handoff_envelope_fingerprint": source_handoff_envelope_fingerprint,
        })));
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(None);
    };
    let Some(policy) = snapshot
        .modes
        .iter()
        .find(|policy| policy.mode_id == child_mode_id)
    else {
        return Ok(None);
    };
    let policy_fingerprint =
        external_modepack_policy_fingerprint(&snapshot.name, snapshot.schema_version, policy);
    Ok(Some(json!({
        "version": EXTERNAL_MODEPACK_CHILD_PROVENANCE_VERSION,
        "source_kind": "workspace_modepack",
        "modepack_name": snapshot.name,
        "schema_version": snapshot.schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "mode_id": policy.mode_id,
        "policy_fingerprint": policy_fingerprint,
        "captured_parent_run_id": parent_run_id,
        "captured_handoff_envelope_id": source_handoff_envelope_id,
        "captured_handoff_envelope_fingerprint": source_handoff_envelope_fingerprint,
    })))
}

fn tool_summary(tool: brownie_tools::ToolDefinition) -> ToolSummary {
    ToolSummary {
        tool_id: tool.tool_id,
        display_name: tool.display_name,
        description: tool.description,
        required_action: runtime_action_name(&tool.required_action),
    }
}

fn build_tool_plan_result(
    record: &brownie_protocol::TaskRecord,
    policy: &CompiledModePolicy,
) -> ToolPlanResult {
    let plan = ToolPlanner::plan(ToolPlanningInput {
        task_id: record.task_id.clone(),
        goal: record.goal.clone(),
        mode_id: policy.mode_id.clone(),
    });
    let evaluation = ToolPlanEvaluator::evaluate(policy, plan);
    ToolPlanResult {
        task_id: record.task_id.clone(),
        run_id: record.run_id.clone(),
        mode_id: policy.mode_id.clone(),
        items: evaluation
            .items
            .into_iter()
            .map(tool_plan_decision_summary)
            .collect(),
    }
}

fn tool_plan_decision_summary(decision: ToolPlanDecision) -> ToolPlanDecisionSummary {
    ToolPlanDecisionSummary {
        tool_id: decision.tool_id,
        required_action: runtime_action_name(&decision.required_action),
        allowed: decision.allowed,
        reason: decision.reason,
    }
}

fn tool_intent_decision_summary(decision: ToolIntentDecision) -> ToolIntentDecisionSummary {
    ToolIntentDecisionSummary {
        tool_id: decision.tool_id,
        required_action: runtime_action_name(&decision.required_action),
        allowed: decision.allowed,
        reason: decision.reason,
        request_reason: decision.request_reason,
        input_summary: tool_intent_input_summary(&decision.input),
    }
}

fn tool_intent_rejected_summary(rejected: RejectedToolIntent) -> ToolIntentRejectedSummary {
    ToolIntentRejectedSummary {
        tool_id: rejected.tool_id,
        reason: rejected.reason,
        code: rejected.code,
    }
}

fn tool_intent_parser_summary(
    summary: brownie_tools::ToolIntentParserSummary,
) -> ToolIntentParserSummary {
    ToolIntentParserSummary {
        found_blocks: summary.found_blocks,
        accepted_blocks: summary.accepted_blocks,
        accepted_requests: summary.accepted_requests,
        rejected_requests: summary.rejected_requests,
        max_blocks: summary.max_blocks,
        max_block_bytes: summary.max_block_bytes,
        max_tool_requests: summary.max_tool_requests,
        max_input_bytes: summary.max_input_bytes,
        max_reason_chars: summary.max_reason_chars,
        max_workspace_write_content_chars: summary.max_workspace_write_content_chars,
    }
}

fn tool_intent_parser_config_summary() -> ToolIntentParserConfigSummary {
    let config = ToolIntentParser::config();
    ToolIntentParserConfigSummary {
        max_blocks: config.max_blocks,
        max_block_bytes: config.max_block_bytes,
        max_tool_requests: config.max_tool_requests,
        max_input_bytes: config.max_input_bytes,
        max_reason_chars: config.max_reason_chars,
        max_workspace_write_content_chars: config.max_workspace_write_content_chars,
    }
}

fn tool_intent_input_summary(input: &Value) -> ToolIntentInputSummary {
    ToolIntentInputSummary {
        has_path: input.get("path").and_then(Value::as_str).is_some(),
        field_count: input.as_object().map(|object| object.len()).unwrap_or(0),
    }
}

fn summarize_intent_input(input: &Value) -> Value {
    json!(tool_intent_input_summary(input))
}

fn normalized_subtask_spawn_goal_preview(input: &Value) -> Option<String> {
    input
        .get("goal")
        .and_then(Value::as_str)
        .map(|goal| goal.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|goal| !goal.is_empty())
        .map(|goal| preview_with_limit(&goal, MAX_SUBTASK_SPAWN_GOAL_CHARS))
}

fn normalized_subtask_spawn_mode_id(input: &Value) -> Option<String> {
    input
        .get("mode_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|mode_id| !mode_id.is_empty())
        .map(ToString::to_string)
}

fn subtask_spawn_input_runtime_rejection_reason(
    store: &BrownieStore,
    policy: &CompiledModePolicy,
    input: &Value,
) -> anyhow::Result<Option<&'static str>> {
    let Some(mode_id) = normalized_subtask_spawn_mode_id(input) else {
        return Ok(None);
    };
    if resolve_workspace_mode_policy(store, &mode_id)
        .map_err(anyhow::Error::msg)?
        .is_none()
    {
        return Ok(Some("subtask.spawn input.mode_id is unknown."));
    }
    if let Some(allowed_handoff_targets) = policy.allowed_handoff_targets.as_ref() {
        if !allowed_handoff_targets
            .iter()
            .any(|allowed_mode_id| allowed_mode_id == &mode_id)
        {
            return Ok(Some(
                "subtask.spawn input.mode_id is not allowed by active mode handoff policy.",
            ));
        }
    }
    Ok(None)
}

fn tool_execute_result(result: brownie_tools::ToolExecutionResult) -> ToolExecuteResult {
    ToolExecuteResult {
        tool_id: result.tool_id,
        status: match result.status {
            ToolExecutionStatus::Completed => ToolExecuteStatus::Completed,
            ToolExecutionStatus::Denied => ToolExecuteStatus::Denied,
            ToolExecutionStatus::Failed => ToolExecuteStatus::Failed,
        },
        output: result.output,
    }
}

const VERIFICATION_COMPLETION_GATE_STATUS_PASSED: &str = "Passed";
const VERIFICATION_COMPLETION_GATE_STATUS_FAILED: &str = "Failed";

struct RequiredVerificationIntent {
    tool_id: String,
    event_index: usize,
    rejected: bool,
    requirement_fingerprint: Option<String>,
}

#[derive(Debug, Clone)]
struct RuntimeVerificationRequirement {
    requirement_id: String,
    source_kind: String,
    source_apply_id: String,
    requirement_fingerprint: String,
    required_verifier_tool_ids: Vec<String>,
}

fn verification_completion_gate_for_run(
    events: &[LedgerEvent],
) -> Option<TaskRunVerificationCompletionGate> {
    verification_completion_gate_for_run_with_requirement(events, None)
}

fn verification_completion_gate_for_run_with_requirement(
    events: &[LedgerEvent],
    runtime_requirement: Option<&RuntimeVerificationRequirement>,
) -> Option<TaskRunVerificationCompletionGate> {
    let mut required = required_verification_intents(events);
    if let Some(requirement) = runtime_requirement {
        for tool_id in &requirement.required_verifier_tool_ids {
            if required.iter().any(|intent| intent.tool_id == *tool_id) {
                continue;
            }
            required.push(RequiredVerificationIntent {
                tool_id: tool_id.clone(),
                event_index: 0,
                rejected: false,
                requirement_fingerprint: Some(requirement.requirement_fingerprint.clone()),
            });
        }
    }
    if required.is_empty() {
        return None;
    }

    let mut passed_verifier_tool_ids = Vec::new();
    let mut failed_verifier_tool_ids = Vec::new();
    let mut missing_verifier_tool_ids = Vec::new();
    let mut failure_reasons = Vec::new();
    let mut bounded_cargo_diagnostics = Vec::new();

    for intent in &required {
        if intent.rejected {
            failed_verifier_tool_ids.push(intent.tool_id.clone());
            failure_reasons.push(format!("{}:RejectedToolIntent", intent.tool_id));
            continue;
        }

        match terminal_verification_event_after(events, intent.event_index, &intent.tool_id) {
            Some(event)
                if intent.requirement_fingerprint.as_deref().is_some()
                    && !event_matches_requirement(
                        event,
                        intent.requirement_fingerprint.as_deref(),
                    ) =>
            {
                failed_verifier_tool_ids.push(intent.tool_id.clone());
                missing_verifier_tool_ids.push(intent.tool_id.clone());
                failure_reasons.push(format!("{}:RequirementFingerprintMismatch", intent.tool_id));
            }
            Some(event) if event.kind == LedgerEventKind::ToolExecutionCompleted => {
                let verification_status = event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("verification_status"))
                    .and_then(Value::as_str);
                if verification_status == Some(VERIFICATION_COMPLETION_GATE_STATUS_PASSED) {
                    passed_verifier_tool_ids.push(intent.tool_id.clone());
                } else {
                    push_bounded_cargo_diagnostics(
                        &mut bounded_cargo_diagnostics,
                        bounded_cargo_diagnostics_from_event(event),
                    );
                    failed_verifier_tool_ids.push(intent.tool_id.clone());
                    failure_reasons.push(format!(
                        "{}:{}",
                        intent.tool_id,
                        verification_status.unwrap_or("MalformedTerminalEvidence")
                    ));
                }
            }
            Some(event) if event.kind == LedgerEventKind::ToolExecutionDenied => {
                failed_verifier_tool_ids.push(intent.tool_id.clone());
                failure_reasons.push(format!("{}:Denied", intent.tool_id));
            }
            Some(event) if event.kind == LedgerEventKind::ToolExecutionFailed => {
                let verification_status = event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("verification_status"))
                    .and_then(Value::as_str)
                    .unwrap_or("Failed");
                push_bounded_cargo_diagnostics(
                    &mut bounded_cargo_diagnostics,
                    bounded_cargo_diagnostics_from_event(event),
                );
                failed_verifier_tool_ids.push(intent.tool_id.clone());
                failure_reasons.push(format!("{}:{verification_status}", intent.tool_id));
            }
            Some(_) => {
                failed_verifier_tool_ids.push(intent.tool_id.clone());
                failure_reasons.push(format!("{}:MalformedTerminalEvidence", intent.tool_id));
            }
            None => {
                failed_verifier_tool_ids.push(intent.tool_id.clone());
                missing_verifier_tool_ids.push(intent.tool_id.clone());
                let reason = if stale_verification_event_before(
                    events,
                    intent.event_index,
                    &intent.tool_id,
                    intent.requirement_fingerprint.as_deref(),
                ) {
                    "StaleTerminalEvidence"
                } else {
                    "MissingTerminalEvidence"
                };
                failure_reasons.push(format!("{}:{reason}", intent.tool_id));
            }
        }
    }

    let required_verifier_tool_ids = required
        .iter()
        .map(|intent| intent.tool_id.clone())
        .collect::<Vec<_>>();
    let status = if failed_verifier_tool_ids.is_empty() {
        VERIFICATION_COMPLETION_GATE_STATUS_PASSED
    } else {
        VERIFICATION_COMPLETION_GATE_STATUS_FAILED
    };
    let next_action = if failed_verifier_tool_ids.is_empty() {
        "complete_task"
    } else {
        "inspect_verification_failure_and_retry_task"
    };

    Some(TaskRunVerificationCompletionGate {
        status: status.to_string(),
        requirement_id: runtime_requirement.map(|requirement| requirement.requirement_id.clone()),
        requirement_source_kind: runtime_requirement
            .map(|requirement| requirement.source_kind.clone()),
        source_apply_id: runtime_requirement.map(|requirement| requirement.source_apply_id.clone()),
        requirement_fingerprint: runtime_requirement
            .map(|requirement| requirement.requirement_fingerprint.clone()),
        required_verifier_count: required_verifier_tool_ids.len(),
        passed_verifier_count: passed_verifier_tool_ids.len(),
        failed_verifier_count: failed_verifier_tool_ids.len(),
        required_verifier_tool_ids,
        passed_verifier_tool_ids,
        failed_verifier_tool_ids,
        missing_verifier_tool_ids,
        failure_reasons,
        bounded_cargo_diagnostics,
        next_action: next_action.to_string(),
    })
}

fn required_verification_intents(events: &[LedgerEvent]) -> Vec<RequiredVerificationIntent> {
    let mut required: Vec<RequiredVerificationIntent> = Vec::new();
    for (event_index, event) in events.iter().enumerate() {
        if !matches!(
            event.kind,
            LedgerEventKind::ToolIntentPermissionChecked | LedgerEventKind::ToolIntentRejected
        ) {
            continue;
        }
        let Some(tool_id) = event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("tool_id"))
            .and_then(Value::as_str)
        else {
            continue;
        };
        if !is_verification_tool_id(tool_id) {
            continue;
        }
        let rejected = event.kind == LedgerEventKind::ToolIntentRejected;
        if let Some(position) = required.iter().position(|intent| intent.tool_id == tool_id) {
            required[position].event_index = event_index;
            required[position].rejected = rejected;
            required[position].requirement_fingerprint = event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("verification_requirement_fingerprint"))
                .and_then(Value::as_str)
                .map(ToString::to_string);
        } else {
            required.push(RequiredVerificationIntent {
                tool_id: tool_id.to_string(),
                event_index,
                rejected,
                requirement_fingerprint: event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("verification_requirement_fingerprint"))
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
            });
        }
    }
    required
}

fn terminal_verification_event_after<'a>(
    events: &'a [LedgerEvent],
    required_event_index: usize,
    tool_id: &str,
) -> Option<&'a LedgerEvent> {
    events
        .iter()
        .enumerate()
        .rev()
        .filter(|(event_index, _)| *event_index > required_event_index)
        .map(|(_, event)| event)
        .find(|event| is_terminal_verification_event_for_tool(event, tool_id))
}

fn stale_verification_event_before(
    events: &[LedgerEvent],
    required_event_index: usize,
    tool_id: &str,
    requirement_fingerprint: Option<&str>,
) -> bool {
    events.iter().enumerate().any(|(event_index, event)| {
        event_index < required_event_index
            && is_terminal_verification_event_for_tool(event, tool_id)
            && event_matches_requirement(event, requirement_fingerprint)
    })
}

fn is_terminal_verification_event_for_tool(event: &LedgerEvent, tool_id: &str) -> bool {
    matches!(
        event.kind,
        LedgerEventKind::ToolExecutionCompleted
            | LedgerEventKind::ToolExecutionDenied
            | LedgerEventKind::ToolExecutionFailed
    ) && event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("tool_id"))
        .and_then(Value::as_str)
        == Some(tool_id)
}

fn event_matches_requirement(event: &LedgerEvent, requirement_fingerprint: Option<&str>) -> bool {
    match requirement_fingerprint {
        Some(requirement_fingerprint) => {
            event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("verification_requirement_fingerprint"))
                .and_then(Value::as_str)
                == Some(requirement_fingerprint)
        }
        None => true,
    }
}

fn is_verification_tool_id(tool_id: &str) -> bool {
    matches!(
        tool_id,
        VERIFICATION_CARGO_FMT_CHECK_TOOL_ID
            | VERIFICATION_CARGO_CHECK_TOOL_ID
            | VERIFICATION_CARGO_TEST_TOOL_ID
    )
}

fn push_bounded_cargo_diagnostics(
    destination: &mut Vec<BoundedCargoDiagnostic>,
    diagnostics: Vec<BoundedCargoDiagnostic>,
) {
    for diagnostic in diagnostics {
        if destination.len() >= MAX_BOUNDED_CARGO_DIAGNOSTICS {
            break;
        }
        if !destination.contains(&diagnostic) {
            destination.push(diagnostic);
        }
    }
}

fn bounded_cargo_diagnostics_from_event(event: &LedgerEvent) -> Vec<BoundedCargoDiagnostic> {
    event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("bounded_cargo_diagnostics"))
        .map(bounded_cargo_diagnostics_from_value)
        .unwrap_or_default()
}

fn bounded_cargo_diagnostics_from_value(value: &Value) -> Vec<BoundedCargoDiagnostic> {
    let Some(items) = value.as_array() else {
        return Vec::new();
    };
    let mut diagnostics = Vec::new();
    for item in items.iter().take(MAX_BOUNDED_CARGO_DIAGNOSTICS) {
        if let Some(diagnostic) = sanitized_bounded_cargo_diagnostic(item) {
            if diagnostics.len() >= MAX_BOUNDED_CARGO_DIAGNOSTICS {
                break;
            }
            if !diagnostics.contains(&diagnostic) {
                diagnostics.push(diagnostic);
            }
        }
    }
    diagnostics
}

fn sanitized_bounded_cargo_diagnostic(item: &Value) -> Option<BoundedCargoDiagnostic> {
    let tool_id = item.get("tool_id")?.as_str()?;
    let check_id = item.get("check_id")?.as_str()?;
    let diagnostic_kind = item.get("diagnostic_kind")?.as_str()?;
    let severity = item.get("severity")?.as_str()?;
    let truncated = item.get("truncated")?.as_bool()?;
    match (tool_id, check_id) {
        (VERIFICATION_CARGO_CHECK_TOOL_ID, "cargo_check") => {
            if !matches!(diagnostic_kind, "compile_error" | "compile_warning") {
                return None;
            }
            if !matches!(severity, "error" | "warning") {
                return None;
            }
            let workspace_relative_path = item
                .get("workspace_relative_path")
                .and_then(Value::as_str)
                .and_then(sanitize_bounded_cargo_diagnostic_path)?;
            let line = item.get("line").and_then(positive_usize)?;
            let column = item.get("column").and_then(positive_usize)?;
            let code = item
                .get("code")
                .and_then(Value::as_str)
                .and_then(sanitize_bounded_cargo_diagnostic_code);
            Some(BoundedCargoDiagnostic {
                tool_id: tool_id.to_string(),
                check_id: check_id.to_string(),
                diagnostic_kind: diagnostic_kind.to_string(),
                severity: severity.to_string(),
                code,
                test_name_hash: None,
                workspace_relative_path: Some(workspace_relative_path),
                line: Some(line),
                column: Some(column),
                truncated,
            })
        }
        (VERIFICATION_CARGO_TEST_TOOL_ID, "cargo_test") => {
            if !matches!(
                diagnostic_kind,
                "panic_location" | "test_failure" | "unavailable"
            ) {
                return None;
            }
            if severity != "error" {
                return None;
            }
            let test_name_hash = item
                .get("test_name_hash")
                .and_then(Value::as_str)
                .and_then(sanitize_bounded_cargo_diagnostic_fingerprint);
            let workspace_relative_path = item
                .get("workspace_relative_path")
                .and_then(Value::as_str)
                .and_then(sanitize_bounded_cargo_diagnostic_path);
            let line = item.get("line").and_then(positive_usize);
            let column = item.get("column").and_then(positive_usize);
            if diagnostic_kind == "panic_location"
                && (test_name_hash.is_none()
                    || workspace_relative_path.is_none()
                    || line.is_none()
                    || column.is_none())
            {
                return None;
            }
            if diagnostic_kind == "test_failure" && test_name_hash.is_none() {
                return None;
            }
            Some(BoundedCargoDiagnostic {
                tool_id: tool_id.to_string(),
                check_id: check_id.to_string(),
                diagnostic_kind: diagnostic_kind.to_string(),
                severity: severity.to_string(),
                code: None,
                test_name_hash,
                workspace_relative_path,
                line,
                column,
                truncated,
            })
        }
        _ => None,
    }
}

fn positive_usize(value: &Value) -> Option<usize> {
    let raw = value.as_u64()?;
    if raw == 0 {
        return None;
    }
    usize::try_from(raw).ok()
}

fn sanitize_bounded_cargo_diagnostic_code(code: &str) -> Option<String> {
    if code.is_empty() || code.len() > MAX_BOUNDED_CARGO_DIAGNOSTIC_CODE_CHARS {
        return None;
    }
    if !code
        .bytes()
        .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-'))
    {
        return None;
    }
    Some(code.to_string())
}

fn sanitize_bounded_cargo_diagnostic_fingerprint(fingerprint: &str) -> Option<String> {
    if is_sha256_fingerprint(fingerprint) {
        Some(fingerprint.to_string())
    } else {
        None
    }
}

fn sanitize_bounded_cargo_diagnostic_path(path: &str) -> Option<String> {
    if path.is_empty()
        || path.len() > MAX_BOUNDED_CARGO_DIAGNOSTIC_PATH_CHARS
        || path.contains('\0')
        || path.contains('\\')
    {
        return None;
    }
    let path = Path::new(path);
    if path.is_absolute() {
        return None;
    }
    let mut components = Vec::new();
    for component in path.components() {
        match component {
            Component::Normal(name) => {
                let name = name.to_string_lossy();
                if name.is_empty()
                    || name == "."
                    || name == ".."
                    || is_bounded_cargo_diagnostic_protected_component(&name)
                {
                    return None;
                }
                components.push(name.to_string());
            }
            Component::CurDir => {}
            Component::ParentDir | Component::Prefix(_) | Component::RootDir => return None,
        }
    }
    if components.is_empty() {
        return None;
    }
    Some(components.join("/"))
}

fn is_bounded_cargo_diagnostic_protected_component(component: &str) -> bool {
    matches!(component, ".git" | ".brownie" | "node_modules" | "target")
}

fn verification_completion_gate_payload(gate: &TaskRunVerificationCompletionGate) -> Value {
    let mut payload = json!({
        "verification_completion_gate_status": gate.status,
        "required_verifier_count": gate.required_verifier_count,
        "passed_verifier_count": gate.passed_verifier_count,
        "failed_verifier_count": gate.failed_verifier_count,
        "required_verifier_tool_ids": gate.required_verifier_tool_ids.clone(),
        "passed_verifier_tool_ids": gate.passed_verifier_tool_ids.clone(),
        "failed_verifier_tool_ids": gate.failed_verifier_tool_ids.clone(),
        "missing_verifier_tool_ids": gate.missing_verifier_tool_ids.clone(),
        "failure_reasons": gate.failure_reasons.clone(),
        "next_action": gate.next_action.clone(),
    });
    if let Some(object) = payload.as_object_mut() {
        if !gate.bounded_cargo_diagnostics.is_empty() {
            object.insert(
                "bounded_cargo_diagnostics".to_string(),
                json!(gate.bounded_cargo_diagnostics.clone()),
            );
        }
        if let Some(requirement_id) = gate.requirement_id.as_ref() {
            object.insert(
                "verification_requirement_id".to_string(),
                json!(requirement_id),
            );
        }
        if let Some(source_kind) = gate.requirement_source_kind.as_ref() {
            object.insert(
                "verification_requirement_source_kind".to_string(),
                json!(source_kind),
            );
        }
        if let Some(source_apply_id) = gate.source_apply_id.as_ref() {
            object.insert("source_apply_id".to_string(), json!(source_apply_id));
        }
        if let Some(fingerprint) = gate.requirement_fingerprint.as_ref() {
            object.insert(
                "verification_requirement_fingerprint".to_string(),
                json!(fingerprint),
            );
        }
    }
    payload
}

fn verification_recovery_repair_payload(
    repair: &TaskRunVerificationRecoveryRepairOutcome,
) -> Value {
    let mut payload = json!({
        "verification_recovery_repair_gate_status": repair.gate_status,
        "verification_recovery_repair": true,
        "source_task_id": repair.source_task_id,
        "source_run_id": repair.source_run_id,
        "recovery_task_id": repair.recovery_task_id,
        "recovery_run_id": repair.recovery_run_id,
        "failure_fingerprint": repair.failure_fingerprint,
        "failed_verifier_tool_ids": repair.failed_verifier_tool_ids,
        "proposal_count": repair.proposal_count,
        "apply_enabled": repair.apply_enabled,
        "next_action": repair.next_action,
    });
    if let Some(object) = payload.as_object_mut() {
        if let Some(proposal_id) = repair.proposal_id.as_ref() {
            object.insert("proposal_id".to_string(), json!(proposal_id));
        }
        if let Some(reason) = repair.failure_reason.as_ref() {
            object.insert("failure_reason".to_string(), json!(reason));
        }
    }
    payload
}

fn task_run_terminal_payload(
    completion_evidence: Option<&TaskRunCompletionEvidence>,
    verification_completion_gate: Option<&TaskRunVerificationCompletionGate>,
    verification_recovery_repair: Option<&TaskRunVerificationRecoveryRepairOutcome>,
) -> Option<Value> {
    let mut payload = json!({});
    if let Some(evidence) = completion_evidence {
        merge_json_object(&mut payload, json!({ "completion_evidence": evidence }));
    }
    if let Some(gate) = verification_completion_gate {
        merge_json_object(&mut payload, verification_completion_gate_payload(gate));
    }
    if let Some(repair) = verification_recovery_repair {
        merge_json_object(&mut payload, verification_recovery_repair_payload(repair));
    }
    if payload
        .as_object()
        .map(|object| object.is_empty())
        .unwrap_or(true)
    {
        None
    } else {
        Some(payload)
    }
}

fn merge_json_object(target: &mut Value, source: Value) {
    let Some(target_object) = target.as_object_mut() else {
        return;
    };
    let Some(source_object) = source.as_object() else {
        return;
    };
    for (key, value) in source_object {
        target_object.insert(key.clone(), value.clone());
    }
}

fn append_verification_recovery_retry_tool_execution(
    store: &BrownieStore,
    record: &TaskRecord,
    policy: &CompiledModePolicy,
    tool_id: &str,
    runtime_requirement: Option<&RuntimeVerificationRequirement>,
) -> anyhow::Result<()> {
    let definition = BuiltinToolRegistry::get(tool_id)
        .ok_or_else(|| anyhow::anyhow!("unknown verification retry tool id: {tool_id}"))?;
    if !is_verification_tool_id(&definition.tool_id) {
        anyhow::bail!("unsupported verification retry tool id: {tool_id}");
    }
    let check_id = match definition.tool_id.as_str() {
        VERIFICATION_CARGO_FMT_CHECK_TOOL_ID => "cargo_fmt_check",
        VERIFICATION_CARGO_CHECK_TOOL_ID => "cargo_check",
        VERIFICATION_CARGO_TEST_TOOL_ID => "cargo_test",
        _ => anyhow::bail!("unsupported verification retry tool id: {tool_id}"),
    };
    let input = json!({
        "check_id": check_id,
    });
    let permission = RuntimePermissionGate::check(policy, definition.required_action.clone());
    let mut intent_payload = json!({
        "tool_id": definition.tool_id,
        "required_action": runtime_action_name(&definition.required_action),
        "allowed": permission.allowed,
        "reason": permission.reason,
        "request_reason": "verification_recovery_retry",
        "input_summary": summarize_intent_input(&input),
        "verification_recovery_retry": true,
    });
    add_runtime_requirement_payload_fields(&mut intent_payload, runtime_requirement);
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::ToolIntentPermissionChecked,
        Some(intent_payload.clone()),
    )?;
    store.tasks().append_task_event_with_payload(
        record,
        if permission.allowed {
            LedgerEventKind::ToolIntentApproved
        } else {
            LedgerEventKind::ToolIntentDenied
        },
        Some(intent_payload),
    )?;
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::ToolExecutionRequested,
        Some({
            let mut payload = json!({
                "tool_id": definition.tool_id,
                "input_summary": summarize_intent_input(&input),
                "verification_recovery_retry": true,
            });
            add_runtime_requirement_payload_fields(&mut payload, runtime_requirement);
            payload
        }),
    )?;
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::ToolExecutionPermissionChecked,
        Some({
            let mut payload = json!({
                "tool_id": definition.tool_id,
                "required_action": runtime_action_name(&definition.required_action),
                "allowed": permission.allowed,
                "reason": permission.reason,
                "verification_recovery_retry": true,
            });
            add_runtime_requirement_payload_fields(&mut payload, runtime_requirement);
            payload
        }),
    )?;
    if !permission.allowed {
        store.tasks().append_task_event_with_payload(
            record,
            LedgerEventKind::ToolExecutionDenied,
            Some({
                let mut payload = json!({
                    "tool_id": definition.tool_id,
                    "status": "Denied",
                    "reason": permission.reason,
                    "verification_recovery_retry": true,
                });
                add_runtime_requirement_payload_fields(&mut payload, runtime_requirement);
                payload
            }),
        )?;
        return Ok(());
    }

    let result = ToolExecutor::execute_controlled(
        store.workspace_root(),
        ToolExecutionRequest {
            tool_id: definition.tool_id,
            input,
        },
    )?;
    let kind = match result.status {
        ToolExecutionStatus::Completed => LedgerEventKind::ToolExecutionCompleted,
        ToolExecutionStatus::Denied => LedgerEventKind::ToolExecutionDenied,
        ToolExecutionStatus::Failed => LedgerEventKind::ToolExecutionFailed,
    };
    let mut payload = tool_execution_ledger_payload(&result);
    if let Some(object) = payload.as_object_mut() {
        object.insert("verification_recovery_retry".to_string(), json!(true));
    }
    add_runtime_requirement_payload_fields(&mut payload, runtime_requirement);
    store
        .tasks()
        .append_task_event_with_payload(record, kind, Some(payload))?;
    Ok(())
}

fn add_runtime_requirement_payload_fields(
    payload: &mut Value,
    runtime_requirement: Option<&RuntimeVerificationRequirement>,
) {
    let Some(requirement) = runtime_requirement else {
        return;
    };
    if let Some(object) = payload.as_object_mut() {
        object.insert(
            "verification_requirement_id".to_string(),
            json!(requirement.requirement_id),
        );
        object.insert(
            "verification_requirement_source_kind".to_string(),
            json!(requirement.source_kind),
        );
        object.insert(
            "source_apply_id".to_string(),
            json!(requirement.source_apply_id),
        );
        object.insert(
            "verification_requirement_fingerprint".to_string(),
            json!(requirement.requirement_fingerprint),
        );
    }
}

fn runtime_verification_requirement_for_record(
    record: &TaskRecord,
) -> Option<RuntimeVerificationRequirement> {
    let provenance = record.verification_recovery_retry_provenance.as_ref()?;
    let mut required_verifier_tool_ids = provenance.retried_verifier_tool_ids.clone();
    required_verifier_tool_ids.sort();
    required_verifier_tool_ids.dedup();
    if required_verifier_tool_ids.is_empty() {
        return None;
    }
    let source_kind = "verification_recovery_retry_apply".to_string();
    let canonical = json!({
        "version": "runtime_required_verification_requirement_v1",
        "task_id": record.task_id,
        "run_id": record.run_id,
        "source_kind": source_kind,
        "source_task_id": provenance.source_task_id,
        "source_run_id": provenance.source_run_id,
        "recovery_task_id": provenance.recovery_task_id,
        "recovery_run_id": provenance.recovery_run_id,
        "proposal_id": provenance.proposal_id,
        "apply_id": provenance.apply_id,
        "failure_fingerprint": provenance.failure_fingerprint,
        "apply_fingerprint": provenance.apply_fingerprint,
        "required_verifier_tool_ids": required_verifier_tool_ids,
    });
    let requirement_fingerprint =
        format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()));
    let requirement_id = format!(
        "verification_requirement_{}",
        requirement_fingerprint
            .trim_start_matches("sha256:")
            .chars()
            .take(16)
            .collect::<String>()
    );
    Some(RuntimeVerificationRequirement {
        requirement_id,
        source_kind,
        source_apply_id: provenance.apply_id.clone(),
        requirement_fingerprint,
        required_verifier_tool_ids,
    })
}

#[derive(Debug, Clone)]
enum VerificationRecoveryAdmissionError {
    InvalidParams(String),
    Internal(String),
}

fn verification_recovery_provenance_for_source(
    store: &BrownieStore,
    source: &VerificationRecoverySource,
) -> Result<VerificationRecoveryProvenance, VerificationRecoveryAdmissionError> {
    if source.source_task_id.trim().is_empty() {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.source_task_id must not be empty".into(),
        ));
    }
    if source.source_run_id.trim().is_empty() {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.source_run_id must not be empty".into(),
        ));
    }
    if !source.authorize_recovery {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.authorize_recovery must be true".into(),
        ));
    }
    if !is_sha256_fingerprint(&source.expected_failure_fingerprint) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.expected_failure_fingerprint must be a sha256 fingerprint".into(),
        ));
    }

    let source_task = store
        .tasks()
        .get_task(&source.source_task_id)
        .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?
        .ok_or_else(|| {
            VerificationRecoveryAdmissionError::InvalidParams(
                "invalid params: verification_recovery_source.source_task_id was not found".into(),
            )
        })?;

    if source_task.run_id != source.source_run_id {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.source_run_id does not match source task"
                .into(),
        ));
    }
    if source_task.status != TaskStatus::Failed {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery source task must be terminal Failed".into(),
        ));
    }

    let events = store
        .tasks()
        .read_ledger_events(&source.source_run_id)
        .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?;
    let gate = verification_completion_gate_for_run(&events).ok_or_else(|| {
        VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery source has no verification completion gate"
                .into(),
        )
    })?;
    if gate.status != VERIFICATION_COMPLETION_GATE_STATUS_FAILED || gate.failed_verifier_count == 0
    {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery source gate is not failed".into(),
        ));
    }
    if !has_terminal_failed_task_event_with_verification_gate(&events) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery source is not a terminal failed verification run"
                .into(),
        ));
    }

    let actual_fingerprint = verification_recovery_failure_fingerprint(&source_task, &gate);
    if actual_fingerprint != source.expected_failure_fingerprint {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_source.expected_failure_fingerprint is stale"
                .into(),
        ));
    }

    Ok(VerificationRecoveryProvenance {
        source_task_id: source_task.task_id,
        source_run_id: source_task.run_id,
        failure_fingerprint: actual_fingerprint,
        required_verifier_count: gate.required_verifier_count,
        passed_verifier_count: gate.passed_verifier_count,
        failed_verifier_count: gate.failed_verifier_count,
        failed_verifier_tool_ids: gate.failed_verifier_tool_ids,
        failure_reasons: gate.failure_reasons,
        bounded_cargo_diagnostics: gate.bounded_cargo_diagnostics,
    })
}

#[derive(Debug, Clone)]
struct VerificationRecoveryApplyEvidence {
    apply_fingerprint: String,
}

fn verification_recovery_retry_provenance_for_source(
    store: &BrownieStore,
    source: &VerificationRecoveryRetrySource,
) -> Result<VerificationRecoveryRetryProvenance, VerificationRecoveryAdmissionError> {
    validate_verification_recovery_retry_source_shape(source)?;

    let recovery_source = VerificationRecoverySource {
        source_task_id: source.source_task_id.clone(),
        source_run_id: source.source_run_id.clone(),
        expected_failure_fingerprint: source.expected_failure_fingerprint.clone(),
        authorize_recovery: true,
    };
    let latest_recovery_provenance =
        verification_recovery_provenance_for_source(store, &recovery_source)?;

    let recovery_task = store
        .tasks()
        .get_task(&source.recovery_task_id)
        .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?
        .ok_or_else(|| {
            VerificationRecoveryAdmissionError::InvalidParams(
                "invalid params: verification_recovery_retry_source.recovery_task_id was not found"
                    .into(),
            )
        })?;
    if recovery_task.run_id != source.recovery_run_id {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_retry_source.recovery_run_id does not match recovery task"
                .into(),
        ));
    }
    let Some(recovery_provenance) = recovery_task.verification_recovery_provenance.as_ref() else {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery retry source task is not a recovery task".into(),
        ));
    };
    if recovery_provenance != &latest_recovery_provenance {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery retry source recovery provenance is stale"
                .into(),
        ));
    }

    let proposals =
        verification_recovery_repair_proposals_for_run(store, &recovery_task, recovery_provenance)
            .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?;
    if !proposals
        .iter()
        .any(|proposal| proposal.applicable && proposal.proposal_id == source.proposal_id)
    {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery retry source proposal is not recovery-scoped"
                .into(),
        ));
    }

    let apply_evidence = latest_recovery_apply_evidence(
        store,
        &source.recovery_run_id,
        &source.proposal_id,
        &source.apply_id,
    )?;
    if apply_evidence.apply_fingerprint != source.expected_apply_fingerprint {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_retry_source.expected_apply_fingerprint is stale"
                .into(),
        ));
    }

    let retried_verifier_tool_ids = recovery_provenance
        .failed_verifier_tool_ids
        .iter()
        .map(|tool_id| tool_id.as_str())
        .collect::<Vec<_>>();
    if retried_verifier_tool_ids.is_empty()
        || !retried_verifier_tool_ids
            .iter()
            .all(|tool_id| is_verification_tool_id(tool_id))
    {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification recovery retry source has unsupported verifier set"
                .into(),
        ));
    }

    Ok(VerificationRecoveryRetryProvenance {
        source_task_id: source.source_task_id.clone(),
        source_run_id: source.source_run_id.clone(),
        recovery_task_id: source.recovery_task_id.clone(),
        recovery_run_id: source.recovery_run_id.clone(),
        proposal_id: source.proposal_id.clone(),
        apply_id: source.apply_id.clone(),
        failure_fingerprint: source.expected_failure_fingerprint.clone(),
        apply_fingerprint: source.expected_apply_fingerprint.clone(),
        retried_verifier_tool_ids: retried_verifier_tool_ids
            .into_iter()
            .map(ToString::to_string)
            .collect(),
    })
}

fn llm_provider_failure_retry_provenance_for_source(
    store: &BrownieStore,
    source: &LlmProviderFailureRetrySource,
) -> Result<LlmProviderFailureRetryProvenance, VerificationRecoveryAdmissionError> {
    if source.source_task_id.trim().is_empty() {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.source_task_id must not be empty"
                .into(),
        ));
    }
    if source.source_run_id.trim().is_empty() {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.source_run_id must not be empty"
                .into(),
        ));
    }
    if !source.authorize_provider_failure_retry {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.authorize_provider_failure_retry must be true"
                .into(),
        ));
    }
    if !is_sha256_fingerprint(&source.expected_failure_fingerprint) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.expected_failure_fingerprint must be a sha256 fingerprint"
                .into(),
        ));
    }

    let source_task = store
        .tasks()
        .get_task(&source.source_task_id)
        .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?
        .ok_or_else(|| {
            VerificationRecoveryAdmissionError::InvalidParams(
                "invalid params: llm_provider_failure_retry_source.source_task_id was not found"
                    .into(),
            )
        })?;

    if source_task.run_id != source.source_run_id {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.source_run_id does not match source task"
                .into(),
        ));
    }
    if source_task.status != TaskStatus::Failed {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: LLM provider failure retry source task must be terminal Failed".into(),
        ));
    }

    let events = store
        .tasks()
        .read_ledger_events(&source.source_run_id)
        .map_err(|error| VerificationRecoveryAdmissionError::Internal(error.to_string()))?;
    let Some(outcome) = llm_provider_failure_outcome_from_events(&events) else {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: LLM provider failure retry source has no structured provider failure evidence"
                .into(),
        ));
    };
    if outcome.failure_fingerprint != source.expected_failure_fingerprint {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: llm_provider_failure_retry_source.expected_failure_fingerprint is stale"
                .into(),
        ));
    }
    if !outcome.retryable || !is_retryable_llm_provider_failure_class(&outcome.failure_class) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: LLM provider failure retry source failure class is not retryable"
                .into(),
        ));
    }

    Ok(LlmProviderFailureRetryProvenance {
        source_task_id: source_task.task_id,
        source_run_id: source_task.run_id,
        failure_fingerprint: outcome.failure_fingerprint,
        failure_class: outcome.failure_class,
        provider: outcome.provider,
        model: outcome.model,
        request_phase: outcome.request_phase,
        retryable: outcome.retryable,
    })
}

fn is_retryable_llm_provider_failure_class(failure_class: &str) -> bool {
    matches!(
        failure_class,
        "http_status"
            | "transport_or_timeout"
            | "invalid_provider_response"
            | "missing_provider_content"
            | "unknown_provider_failure"
    )
}

fn validate_verification_recovery_retry_source_shape(
    source: &VerificationRecoveryRetrySource,
) -> Result<(), VerificationRecoveryAdmissionError> {
    for (field, value) in [
        ("source_task_id", source.source_task_id.as_str()),
        ("source_run_id", source.source_run_id.as_str()),
        ("recovery_task_id", source.recovery_task_id.as_str()),
        ("recovery_run_id", source.recovery_run_id.as_str()),
        ("proposal_id", source.proposal_id.as_str()),
        ("apply_id", source.apply_id.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(VerificationRecoveryAdmissionError::InvalidParams(format!(
                "invalid params: verification_recovery_retry_source.{field} must not be empty"
            )));
        }
    }
    if !source.authorize_verification_retry {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_retry_source.authorize_verification_retry must be true"
                .into(),
        ));
    }
    if !is_sha256_fingerprint(&source.expected_failure_fingerprint) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_retry_source.expected_failure_fingerprint must be a sha256 fingerprint"
                .into(),
        ));
    }
    if !is_sha256_fingerprint(&source.expected_apply_fingerprint) {
        return Err(VerificationRecoveryAdmissionError::InvalidParams(
            "invalid params: verification_recovery_retry_source.expected_apply_fingerprint must be a sha256 fingerprint"
                .into(),
        ));
    }
    Ok(())
}

fn verification_recovery_retry_record_for_headless_run_target(
    store: &BrownieStore,
    target: &VerificationRecoveryRetryRunTarget,
) -> Result<TaskRecord, TaskRunAdmissionRejection> {
    for value in [
        ("retry_task_id", target.retry_task_id.as_str()),
        ("retry_run_id", target.retry_run_id.as_str()),
        ("proposal_id", target.proposal_id.as_str()),
        ("apply_id", target.apply_id.as_str()),
    ]
    .map(|(_, value)| value)
    {
        if value.trim().is_empty() {
            return Err(TaskRunAdmissionRejection::InvalidParams(
                "invalid params: verification_recovery_retry_run_target fields must not be empty",
            ));
        }
    }
    if !target.authorize_verification_retry_run {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.authorize_verification_retry_run must be true"
                .into(),
        ));
    }
    if !is_sha256_fingerprint(&target.expected_failure_fingerprint) {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.expected_failure_fingerprint must be a sha256 fingerprint"
                .into(),
        ));
    }
    if !is_sha256_fingerprint(&target.expected_apply_fingerprint) {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.expected_apply_fingerprint must be a sha256 fingerprint"
                .into(),
        ));
    }

    let record = store
        .tasks()
        .get_task(&target.retry_task_id)
        .map_err(|error| TaskRunAdmissionRejection::Internal(error.to_string()))?
        .ok_or_else(|| {
            TaskRunAdmissionRejection::InvalidParams(
                "invalid params: verification_recovery_retry_run_target.retry_task_id was not found"
                    .into(),
            )
        })?;
    if record.run_id != target.retry_run_id {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.retry_run_id does not match retry task"
                .into(),
        ));
    }
    if !matches!(record.status, TaskStatus::Created | TaskStatus::Queued) {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification recovery retry run target task must be Created or Queued"
                .into(),
        ));
    }
    let Some(provenance) = record.verification_recovery_retry_provenance.as_ref() else {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification recovery retry run target task has no retry provenance"
                .into(),
        ));
    };
    if provenance.proposal_id != target.proposal_id {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.proposal_id is stale".into(),
        ));
    }
    if provenance.apply_id != target.apply_id {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.apply_id is stale".into(),
        ));
    }
    if provenance.failure_fingerprint != target.expected_failure_fingerprint {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.expected_failure_fingerprint is stale"
                .into(),
        ));
    }
    if provenance.apply_fingerprint != target.expected_apply_fingerprint {
        return Err(TaskRunAdmissionRejection::InvalidParams(
            "invalid params: verification_recovery_retry_run_target.expected_apply_fingerprint is stale"
                .into(),
        ));
    }
    revalidate_verification_recovery_retry_task_for_run(store, &record)?;
    Ok(record)
}

