    #[test]
    fn task_start_and_run_verification_recovery_retry_after_applied_recovery_proposal() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("src")).expect("mkdir");
        std::fs::write(temp.path().join("README.md"), "original README").expect("readme");
        std::fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"m8_3_fmt_retry\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .expect("manifest");
        std::fs::write(
            temp.path().join("src/lib.rs"),
            "pub fn raw_m8_3_fmt_failure_marker( )->i32{1}\n",
        )
        .expect("src");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Verify formatting","mode_id":"verifier"}}"#,
            );
        let (recovery_task_id, recovery_run_id) = start_verification_recovery_task_from_source(
            &source_task_id,
            &source_run_id,
            &fingerprint,
            "Implement recovery edit",
            "implementer",
        );
        let recovery_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{recovery_task_id}"}}}}"#
        ));
        assert!(recovery_run.error.is_none());
        let recovery_result = recovery_run.result.expect("recovery result");
        let repair = &recovery_result["verification_recovery_repair"];
        let proposal_id = repair["proposal_id"].as_str().expect("proposal id");

        let approve = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"proposal.approve","params":{{"run_id":"{recovery_run_id}","proposal_id":"{proposal_id}","reason":"retry apply test"}}}}"#
        ));
        assert!(approve.error.is_none());
        let preflight = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":6,"method":"proposal.preflight","params":{{"run_id":"{recovery_run_id}","proposal_id":"{proposal_id}"}}}}"#
        ));
        let preflight_result = preflight.result.expect("preflight result");
        let expected_hash = preflight_result["snapshot"]["file_sha256"]
            .as_str()
            .expect("file hash")
            .to_string();
        let apply_request = json!({
            "jsonrpc": "2.0",
            "id": 7,
            "method": "proposal.apply",
            "params": {
                "run_id": recovery_run_id,
                "proposal_id": proposal_id,
                "expected_target_sha256": expected_hash,
                "replacement_content": "new README content",
                "authorize": true,
            }
        });
        let apply = parse_line(&apply_request.to_string());
        assert!(apply.error.is_none());
        let apply_result = apply.result.expect("apply result");
        assert_eq!(apply_result["apply_result"]["apply_status"], "Applied");
        assert_eq!(apply_result["apply_result"]["applied"], true);
        assert_eq!(apply_result["apply_result"]["authorization_consumed"], true);
        let apply_id = apply_result["apply_result"]["apply_id"]
            .as_str()
            .expect("apply id")
            .to_string();
        let store = BrownieStore::new(temp.path());
        let apply_payload = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery apply events")
            .into_iter()
            .rev()
            .find(|event| {
                event.kind == LedgerEventKind::WorkspacePatchApplyResultRecorded
                    && event
                        .payload
                        .as_ref()
                        .and_then(|payload| payload.get("apply_id"))
                        .and_then(Value::as_str)
                        == Some(apply_id.as_str())
            })
            .and_then(|event| event.payload)
            .expect("apply payload");
        let apply_fingerprint = super::verification_recovery_apply_fingerprint(&apply_payload);

        let retry_start = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 8,
                "method": "task.start",
                "params": {
                    "goal": "Retry failed verification after recovery apply",
                    "mode_id": "verifier",
                    "verification_recovery_retry_source": {
                        "source_task_id": source_task_id,
                        "source_run_id": source_run_id,
                        "recovery_task_id": recovery_task_id,
                        "recovery_run_id": recovery_run_id,
                        "proposal_id": proposal_id,
                        "apply_id": apply_id,
                        "expected_failure_fingerprint": fingerprint,
                        "expected_apply_fingerprint": apply_fingerprint,
                        "authorize_verification_retry": true
                    }
                }
            })
            .to_string(),
        );
        assert!(
            retry_start.error.is_none(),
            "retry start error: {:?}",
            retry_start.error
        );
        let retry_start_result = retry_start.result.expect("retry start result");
        let retry_task_id = retry_start_result["task_id"]
            .as_str()
            .expect("retry task id")
            .to_string();
        let retry_run_id = retry_start_result["run_id"]
            .as_str()
            .expect("retry run id")
            .to_string();
        assert_eq!(
            retry_start_result["verification_recovery_retry_admission"]["retry_running_enabled"],
            false
        );
        assert_eq!(
            retry_start_result["verification_recovery_retry_admission"]["next_action"],
            "run_verification_retry_task_explicitly"
        );

        let retry_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":9,"method":"task.run","params":{{"task_id":"{retry_task_id}"}}}}"#
        ));
        assert!(retry_run.error.is_none());
        let retry_result = retry_run.result.expect("retry result");
        assert_eq!(retry_result["status"], "Failed");
        assert_eq!(
            retry_result["verification_completion_gate"]["requirement_source_kind"],
            "verification_recovery_retry_apply"
        );
        assert_eq!(
            retry_result["verification_completion_gate"]["source_apply_id"],
            apply_id
        );
        assert!(
            retry_result["verification_completion_gate"]["requirement_fingerprint"]
                .as_str()
                .expect("requirement fingerprint")
                .starts_with("sha256:")
        );
        let retry = &retry_result["verification_recovery_retry"];
        assert_eq!(retry["source_task_id"], source_task_id);
        assert_eq!(retry["source_run_id"], source_run_id);
        assert_eq!(retry["recovery_task_id"], recovery_task_id);
        assert_eq!(retry["recovery_run_id"], recovery_run_id);
        assert_eq!(retry["proposal_id"], proposal_id);
        assert_eq!(retry["apply_id"], apply_id);
        assert_eq!(retry["failure_fingerprint"], fingerprint);
        assert_eq!(retry["apply_fingerprint"], apply_fingerprint);
        assert_eq!(
            retry["retried_verifier_tool_ids"][0],
            VERIFICATION_CARGO_FMT_CHECK_TOOL_ID
        );
        assert_eq!(retry["retry_status"], "Failed");
        assert_eq!(retry["replayed"], false);
        assert_eq!(
            retry_result["verification_completion_gate"]["required_verifier_tool_ids"][0],
            VERIFICATION_CARGO_FMT_CHECK_TOOL_ID
        );

        let retry_events = store
            .tasks()
            .read_ledger_events(&retry_run_id)
            .expect("retry events");
        assert_eq!(
            retry_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );
        assert_eq!(
            retry_events
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::ToolExecutionRequested
                        && event
                            .payload
                            .as_ref()
                            .and_then(|payload| payload.get("tool_id"))
                            .and_then(Value::as_str)
                            == Some(VERIFICATION_CARGO_FMT_CHECK_TOOL_ID)
                })
                .count(),
            1
        );
        let retry_tool_terminal_payload = retry_events
            .iter()
            .find_map(|event| {
                if !matches!(
                    event.kind,
                    LedgerEventKind::ToolExecutionCompleted | LedgerEventKind::ToolExecutionFailed
                ) {
                    return None;
                }
                let payload = event.payload.as_ref()?;
                if payload.get("tool_id").and_then(Value::as_str)
                    == Some(VERIFICATION_CARGO_FMT_CHECK_TOOL_ID)
                {
                    Some(payload)
                } else {
                    None
                }
            })
            .expect("retry tool terminal payload");
        assert_eq!(retry_tool_terminal_payload["check_id"], "cargo_fmt_check");
        assert_eq!(
            retry_tool_terminal_payload["verification_requirement_fingerprint"],
            retry_result["verification_completion_gate"]["requirement_fingerprint"]
        );
        assert_eq!(retry_tool_terminal_payload["process_launched"], true);
        assert_eq!(retry_tool_terminal_payload["output_redacted"], true);
        assert!(!retry_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::WorkspacePatchApplyResultRecorded));

        let replay = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":10,"method":"task.run","params":{{"task_id":"{retry_task_id}"}}}}"#
        ));
        assert!(replay.error.is_none());
        let replay_result = replay.result.expect("replay result");
        assert_eq!(
            replay_result["verification_recovery_retry"]["replayed"],
            true
        );
        let retry_events_after_replay = store
            .tasks()
            .read_ledger_events(&retry_run_id)
            .expect("retry events after replay");
        assert_eq!(retry_events_after_replay.len(), retry_events.len());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_recovery_task_rejects_stale_recovery_provenance_before_running() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("src")).expect("mkdir");
        std::fs::write(temp.path().join("README.md"), "# Brownie\n").expect("readme");
        std::fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"m8_2_stale_repair\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .expect("manifest");
        std::fs::write(temp.path().join("src/lib.rs"), "pub fn bad( )->i32{1}\n").expect("src");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Verify formatting","mode_id":"verifier"}}"#,
            );
        let (recovery_task_id, recovery_run_id) = start_verification_recovery_task_from_source(
            &source_task_id,
            &source_run_id,
            &fingerprint,
            "Implement recovery edit",
            "implementer",
        );
        let store = BrownieStore::new(temp.path());
        store
            .tasks()
            .update_task_status(
                &source_task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("make source stale");

        let run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{recovery_task_id}"}}}}"#
        ));
        assert!(run.result.is_none());
        assert_eq!(run.error.expect("error").code, -32602);
        let recovery_events = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events");
        assert!(!recovery_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
        assert!(!recovery_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::WorkspacePatchProposed));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_recovery_task_with_denied_workspace_write_fails_closed_without_repair_proposal() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("src")).expect("mkdir");
        std::fs::write(temp.path().join("README.md"), "original README").expect("readme");
        std::fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"m8_2_denied_repair\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .expect("manifest");
        std::fs::write(temp.path().join("src/lib.rs"), "pub fn bad( )->i32{1}\n").expect("src");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Verify formatting","mode_id":"verifier"}}"#,
            );
        let (recovery_task_id, recovery_run_id) = start_verification_recovery_task_from_source(
            &source_task_id,
            &source_run_id,
            &fingerprint,
            "Implement recovery edit",
            "orchestrator",
        );
        let run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{recovery_task_id}"}}}}"#
        ));
        assert!(run.error.is_none());
        let run_result = run.result.expect("run result");
        assert_eq!(run_result["status"], "Failed");
        assert_eq!(run_result["agent_loop"]["final_state"], "Failed");
        let repair = &run_result["verification_recovery_repair"];
        assert_eq!(repair["gate_status"], "Failed");
        assert_eq!(repair["proposal_count"], 0);
        assert_eq!(repair["failure_reason"], "MissingRecoveryRepairProposal");
        assert_eq!(
            repair["next_action"],
            "inspect_recovery_repair_gate_failure"
        );
        assert!(repair.get("proposal_id").is_none());
        let store = BrownieStore::new(temp.path());
        let recovery_events = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events");
        assert!(!recovery_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::WorkspacePatchProposed));
        assert!(recovery_events.iter().any(|event| {
            event.kind == LedgerEventKind::ToolIntentDenied
                && event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("tool_id"))
                    .and_then(Value::as_str)
                    == Some(WORKSPACE_WRITE_TOOL_ID)
        }));
        assert_eq!(
            std::fs::read_to_string(temp.path().join("README.md")).unwrap(),
            "original README"
        );
        let failed_payload = recovery_events
            .iter()
            .find(|event| event.kind == LedgerEventKind::TaskFailed)
            .and_then(|event| event.payload.as_ref())
            .expect("failed terminal payload");
        assert_eq!(
            failed_payload["verification_recovery_repair_gate_status"],
            "Failed"
        );
        assert_eq!(
            failed_payload["failure_reason"],
            "MissingRecoveryRepairProposal"
        );

        let recovery_again = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 5,
                "method": "task.start",
                "params": {
                    "goal": "Implement recovery edit",
                    "mode_id": "implementer",
                    "verification_recovery_source": {
                        "source_task_id": source_task_id,
                        "source_run_id": source_run_id,
                        "expected_failure_fingerprint": fingerprint,
                        "authorize_recovery": true
                    }
                }
            })
            .to_string(),
        );
        assert!(
            recovery_again.error.is_none(),
            "second recovery admission error: {:?}",
            recovery_again.error
        );
        let recovery_again_result = recovery_again.result.expect("second recovery result");
        let second_recovery_task_id = recovery_again_result["task_id"]
            .as_str()
            .expect("second recovery task id")
            .to_string();
        assert_ne!(second_recovery_task_id, recovery_task_id);
        assert_eq!(
            recovery_again_result["verification_recovery_admission"]["replayed"],
            false
        );
        let second_recovery_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":6,"method":"task.run","params":{{"task_id":"{second_recovery_task_id}"}}}}"#
        ));
        assert!(second_recovery_run.error.is_none());
        let second_recovery_result = second_recovery_run.result.expect("second run result");
        assert_eq!(second_recovery_result["status"], "Completed");
        assert_eq!(
            second_recovery_result["verification_recovery_repair"]["gate_status"],
            "Passed"
        );
        assert_eq!(
            second_recovery_result["verification_recovery_repair"]["proposal_count"],
            1
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_recovery_task_with_unusable_workspace_proposal_fails_repair_gate() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("src")).expect("mkdir");
        std::fs::write(temp.path().join("README.md"), "original README").expect("readme");
        std::fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"m8_2_unusable_repair\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .expect("manifest");
        std::fs::write(temp.path().join("src/lib.rs"), "pub fn bad( )->i32{1}\n").expect("src");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Verify formatting","mode_id":"verifier"}}"#,
            );
        std::fs::remove_file(temp.path().join("README.md")).expect("remove readme");
        std::fs::create_dir(temp.path().join("README.md")).expect("readme directory");

        let (recovery_task_id, recovery_run_id) = start_verification_recovery_task_from_source(
            &source_task_id,
            &source_run_id,
            &fingerprint,
            "Implement recovery edit",
            "implementer",
        );
        let run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{recovery_task_id}"}}}}"#
        ));
        assert!(run.error.is_none());
        let run_result = run.result.expect("run result");
        assert_eq!(run_result["status"], "Failed");
        assert_eq!(run_result["agent_loop"]["final_state"], "Failed");
        let repair = &run_result["verification_recovery_repair"];
        assert_eq!(repair["gate_status"], "Failed");
        assert_eq!(repair["proposal_count"], 1);
        assert_eq!(
            repair["failure_reason"],
            "RecoveryRepairProposalNotApplicable"
        );
        assert_eq!(
            repair["next_action"],
            "inspect_recovery_repair_gate_failure"
        );
        assert!(repair.get("proposal_id").is_none());

        let store = BrownieStore::new(temp.path());
        let recovery_events = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events");
        let proposal_payload = recovery_events
            .iter()
            .find(|event| event.kind == LedgerEventKind::WorkspacePatchProposed)
            .and_then(|event| event.payload.as_ref())
            .expect("proposal payload");
        assert_eq!(proposal_payload["verification_recovery_repair"], true);
        assert_eq!(proposal_payload["source_task_id"], source_task_id);
        assert_eq!(proposal_payload["source_run_id"], source_run_id);
        assert_eq!(proposal_payload["recovery_task_id"], recovery_task_id);
        assert_eq!(proposal_payload["recovery_run_id"], recovery_run_id);
        assert_eq!(proposal_payload["failure_fingerprint"], fingerprint);
        assert_eq!(proposal_payload["validation_status"], "Invalid");

        let replay = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"task.run","params":{{"task_id":"{recovery_task_id}"}}}}"#
        ));
        assert!(replay.error.is_none());
        let replay_result = replay.result.expect("replay result");
        assert_eq!(
            replay_result["verification_recovery_repair"]["failure_reason"],
            "RecoveryRepairProposalNotApplicable"
        );
        assert_eq!(
            replay_result["verification_recovery_repair"]["replayed"],
            true
        );
        let recovery_events_after_replay = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("events after replay");
        assert_eq!(recovery_events_after_replay.len(), recovery_events.len());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    fn failed_verification_source_from_start_and_run(
        start_request: &str,
    ) -> (String, String, String) {
        let start = parse_line(start_request);
        assert!(start.error.is_none());
        let start_result = start.result.expect("start result");
        let task_id = start_result["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let run_id = start_result["run_id"].as_str().expect("run id").to_string();
        let run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"task.run","params":{{"task_id":"{task_id}"}}}}"#
        ));
        assert!(run.error.is_none());
        let run_result = run.result.expect("run result");
        assert_eq!(run_result["status"], "Failed");
        assert_eq!(
            run_result["verification_completion_gate"]["status"],
            "Failed"
        );

        let workspace_root = std::env::var_os("BROWNIE_WORKSPACE_ROOT").expect("workspace root");
        let store = BrownieStore::new(workspace_root);
        let source_task = store
            .tasks()
            .get_task(&task_id)
            .expect("get source task")
            .expect("source task");
        assert_eq!(source_task.status, TaskStatus::Failed);
        let events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("source events");
        let gate = super::verification_completion_gate_for_run(&events).expect("failed gate");
        assert_eq!(gate.status, VERIFICATION_COMPLETION_GATE_STATUS_FAILED);
        let fingerprint = super::verification_recovery_failure_fingerprint(&source_task, &gate);
        (task_id, run_id, fingerprint)
    }

    fn start_verification_recovery_task_from_source(
        source_task_id: &str,
        source_run_id: &str,
        fingerprint: &str,
        goal: &str,
        mode_id: &str,
    ) -> (String, String) {
        let recovery = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 3,
                "method": "task.start",
                "params": {
                    "goal": goal,
                    "mode_id": mode_id,
                    "verification_recovery_source": {
                        "source_task_id": source_task_id,
                        "source_run_id": source_run_id,
                        "expected_failure_fingerprint": fingerprint,
                        "authorize_recovery": true
                    }
                }
            })
            .to_string(),
        );
        assert!(recovery.error.is_none());
        let result = recovery.result.expect("recovery result");
        (
            result["task_id"].as_str().expect("task id").to_string(),
            result["run_id"].as_str().expect("run id").to_string(),
        )
    }

    #[test]
    fn headless_continue_once_admits_verification_recovery_from_failed_gate() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("README.md")).expect("readme directory");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Verify formatting","mode_id":"verifier"}}"#,
            );
        let progress = parse_line(r#"{"jsonrpc":"2.0","id":3,"method":"task.list"}"#)
            .result
            .expect("task list")["progress_overview"]
            .clone();
        let request = json!({
            "jsonrpc": "2.0",
            "id": 4,
            "method": "headless.continue_once",
            "params": {
                "authorize": true,
                "expected_progress_fingerprint": progress["source_fingerprint"],
                "expected_aggregate_sequence": progress["aggregate_sequence"],
                "continuation_id": "m18.1.recovery.admit",
                "verification_recovery_source": {
                    "source_task_id": source_task_id,
                    "source_run_id": source_run_id,
                    "expected_failure_fingerprint": fingerprint,
                    "authorize_recovery": true
                }
            }
        });
        let first = parse_line(&request.to_string())
            .result
            .expect("headless recovery admission");
        assert_eq!(first["status"], "task_in_progress");
        assert_eq!(first["task_run_result"], Value::Null);
        assert_eq!(first["next_action"], "run_recovery_task_explicitly");
        assert_eq!(first["next_route"]["kind"], "run_recovery_task_explicitly");
        assert_eq!(
            first["next_route"]["next_action"],
            "run_recovery_task_explicitly"
        );
        let recovery_task_id = first["selected_task_id"]
            .as_str()
            .expect("recovery task id")
            .to_string();
        let recovery_run_id = first["selected_run_id"]
            .as_str()
            .expect("recovery run id")
            .to_string();

        let store = BrownieStore::new(temp.path());
        let events_after_first = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events");
        assert!(events_after_first
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskStarted));
        assert!(events_after_first
            .iter()
            .any(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded));
        assert!(events_after_first
            .iter()
            .all(|event| event.kind != LedgerEventKind::TaskRunning));

        let replay = parse_line(&request.to_string())
            .result
            .expect("headless recovery replay");
        assert_eq!(replay["replayed"], true);
        assert_eq!(replay["status"], "task_in_progress");
        assert_eq!(replay["selected_task_id"], recovery_task_id);
        assert_eq!(replay["selected_run_id"], recovery_run_id);
        assert_eq!(replay["next_route"]["kind"], "run_recovery_task_explicitly");
        let events_after_replay = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events after replay");
        assert_eq!(events_after_replay.len(), events_after_first.len());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_continue_once_runs_targeted_verification_recovery_task() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        write_cargo_check_fixture(
            temp.path(),
            "m32_1_headless_contextual_recovery_run",
            "pub fn raw_m32_1_check_failure_marker() -> MissingType {\n    1\n}\n",
        );
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let (source_task_id, source_run_id, fingerprint) =
            failed_verification_source_from_start_and_run(
                r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Run cargo check","mode_id":"verifier"}}"#,
            );
        let progress = parse_line(r#"{"jsonrpc":"2.0","id":3,"method":"task.list"}"#)
            .result
            .expect("task list")["progress_overview"]
            .clone();
        let admit = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 4,
                "method": "headless.continue_once",
                "params": {
                    "authorize": true,
                    "expected_progress_fingerprint": progress["source_fingerprint"],
                    "expected_aggregate_sequence": progress["aggregate_sequence"],
                    "continuation_id": "m18.2.recovery.admit",
                    "verification_recovery_goal": "Implement recovery edit",
                    "verification_recovery_mode_id": "implementer",
                    "verification_recovery_source": {
                        "source_task_id": source_task_id,
                        "source_run_id": source_run_id,
                        "expected_failure_fingerprint": fingerprint,
                        "authorize_recovery": true
                    }
                }
            })
            .to_string(),
        );
        assert!(admit.error.is_none());
        let admit_result = admit.result.expect("admit result");
        let recovery_task_id = admit_result["selected_task_id"]
            .as_str()
            .expect("recovery task")
            .to_string();
        let recovery_run_id = admit_result["selected_run_id"]
            .as_str()
            .expect("recovery run")
            .to_string();
        let run_progress = parse_line(r#"{"jsonrpc":"2.0","id":5,"method":"task.list"}"#)
            .result
            .expect("task list after admit")["progress_overview"]
            .clone();
        let run_request = json!({
            "jsonrpc": "2.0",
            "id": 6,
            "method": "headless.continue_once",
            "params": {
                "authorize": true,
                "expected_progress_fingerprint": run_progress["source_fingerprint"],
                "expected_aggregate_sequence": run_progress["aggregate_sequence"],
                "continuation_id": "m18.2.recovery.run",
                "verification_recovery_run_target": {
                    "recovery_task_id": recovery_task_id,
                    "recovery_run_id": recovery_run_id,
                    "source_task_id": source_task_id,
                    "source_run_id": source_run_id,
                    "expected_failure_fingerprint": fingerprint,
                    "authorize_recovery_run": true
                },
                "verification_recovery_context_read": {
                    "authorize": true,
                    "source_task_id": source_task_id,
                    "source_run_id": source_run_id,
                    "expected_failure_fingerprint": fingerprint,
                    "diagnostic_index": 0,
                    "max_excerpt_bytes": 256
                }
            }
        });

        let missing_auth = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 7,
                "method": "headless.continue_once",
                "params": {
                    "authorize": true,
                    "expected_progress_fingerprint": run_progress["source_fingerprint"],
                    "expected_aggregate_sequence": run_progress["aggregate_sequence"],
                    "verification_recovery_run_target": {
                        "recovery_task_id": recovery_task_id,
                        "recovery_run_id": recovery_run_id,
                        "source_task_id": source_task_id,
                        "source_run_id": source_run_id,
                        "expected_failure_fingerprint": fingerprint,
                        "authorize_recovery_run": false
                    }
                }
            })
            .to_string(),
        );
        assert_eq!(
            missing_auth
                .error
                .as_ref()
                .expect("missing auth error")
                .code,
            -32602
        );

        let store = BrownieStore::new(temp.path());
        let events_before_valid_run = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events before valid run");
        assert_eq!(
            events_before_valid_run
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            0
        );

        let run = parse_line(&run_request.to_string());
        assert!(run.error.is_none(), "recovery run error: {:?}", run.error);
        let run_result = run.result.expect("headless recovery run result");
        assert_eq!(run_result["status"], "task_executed");
        assert_eq!(run_result["selected_task_id"], recovery_task_id);
        assert_eq!(run_result["task_run_result"]["task_id"], recovery_task_id);
        assert!(
            run_result["task_run_result"]["verification_recovery_repair"]
                .as_object()
                .is_some()
        );
        assert_eq!(
            run_result["task_run_result"]["verification_recovery_context_read"]["source_task_id"],
            source_task_id
        );
        assert_eq!(
            run_result["task_run_result"]["verification_recovery_context_read"]["source_run_id"],
            source_run_id
        );
        assert_eq!(
            run_result["task_run_result"]["verification_recovery_context_read"]["diagnostic_index"],
            0
        );
        assert_eq!(
            run_result["task_run_result"]["verification_recovery_context_read"]
                ["prompt_preview_redacted"],
            true
        );
        assert_eq!(
            run_result["next_route"]["next_action"],
            "review_and_authorize_recovery_proposal"
        );
        let decision_event = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events after contextual run")
            .into_iter()
            .rev()
            .find(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
            .expect("headless decision event");
        let decision_payload = decision_event.payload.expect("decision payload");
        assert_eq!(decision_payload["verification_recovery_context_read"], true);
        assert!(decision_payload["excerpt_sha256"].as_str().is_some());
        assert!(decision_payload["read_path_fingerprint"].as_str().is_some());
        assert!(decision_payload.get("excerpt").is_none());
        let decision_count = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events")
            .iter()
            .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
            .count();

        let replay = parse_line(&run_request.to_string())
            .result
            .expect("headless replay");
        assert_eq!(replay["replayed"], true);
        assert_eq!(replay["status"], "task_executed");
        assert_eq!(replay["selected_task_id"], recovery_task_id);
        let events_after_replay = store
            .tasks()
            .read_ledger_events(&recovery_run_id)
            .expect("recovery events after replay");
        assert_eq!(
            events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );
        assert_eq!(
            events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
                .count(),
            decision_count
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

