    fn task_list_progress_overview_groups_runtime_owned_task_sets() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        let parent_join = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Parent ready for join".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start join parent");
        let join_child = start_progress_test_child(&store, &parent_join, "join_child");
        append_progress_test_handoff_envelope(&store, &parent_join, &join_child);
        store
            .tasks()
            .append_task_event_with_payload(
                &join_child,
                LedgerEventKind::AgentLoopCompleted,
                Some(json!({
                    "final_state": "Completed",
                    "completion_summary": "join child completed",
                    "completion_result_fingerprint": format!("sha256:{}", "c".repeat(64))
                })),
            )
            .expect("append join child agent loop completion");
        store
            .tasks()
            .update_task_status(
                &join_child.task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("complete join child");
        let parent_join = store
            .tasks()
            .update_task_status(
                &parent_join.task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("complete join parent");
        let parent_pending = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Parent with pending child".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start pending parent");
        let pending_child = start_progress_test_child(&store, &parent_pending, "pending_child");
        let parent_pending = store
            .tasks()
            .update_task_status(
                &parent_pending.task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("complete pending parent");
        let running_task = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Running task".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start running task");
        store
            .tasks()
            .update_task_status(
                &running_task.task_id,
                TaskStatus::Running,
                LedgerEventKind::TaskRunning,
            )
            .expect("mark running task");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let list = parse_line(r#"{"jsonrpc":"2.0","id":1,"method":"task.list"}"#);
        let result = list.result.expect("list result");
        let progress = &result["progress_overview"];
        assert_eq!(progress["task_count"], 5);
        assert_eq!(progress["status_counts"]["created"], 0);
        assert_eq!(progress["status_counts"]["queued"], 1);
        assert_eq!(progress["status_counts"]["running"], 1);
        assert_eq!(progress["status_counts"]["completed"], 3);
        assert_json_array_contains(&progress["runnable_task_ids"], &pending_child.task_id);
        assert_json_array_contains(&progress["blocked_task_ids"], &parent_join.task_id);
        assert_json_array_contains(&progress["blocked_task_ids"], &parent_pending.task_id);
        assert_json_array_contains(&progress["terminal_task_ids"], &parent_join.task_id);
        assert_json_array_contains(&progress["terminal_task_ids"], &join_child.task_id);
        assert_json_array_contains(
            &progress["parent_join_ready_task_ids"],
            &parent_join.task_id,
        );
        assert_eq!(progress["nodes"].as_array().expect("nodes").len(), 5);
        assert_eq!(progress["edges"].as_array().expect("edges").len(), 2);
        assert!(
            progress["aggregate_sequence"]
                .as_u64()
                .expect("aggregate sequence")
                > 0
        );
        assert!(progress["source_fingerprint"]
            .as_str()
            .expect("fingerprint")
            .starts_with("sha256:"));
        assert_json_next_action_contains(
            progress,
            "run_parent_task_explicitly",
            &parent_join.task_id,
        );
        assert_json_next_action_contains(
            progress,
            "run_remaining_child_tasks_explicitly",
            &parent_pending.task_id,
        );
        assert_json_next_action_contains(progress, "run_task_explicitly", &pending_child.task_id);
        assert_json_next_action_contains(progress, "inspect_task", &running_task.task_id);
        assert_json_headless_route_candidate_contains(
            progress,
            "run_parent_task_explicitly",
            &parent_join.task_id,
        );
        assert_json_headless_route_candidate_contains(
            progress,
            "headless_continue_once",
            &pending_child.task_id,
        );
        let route_candidates = progress["headless_route_candidates"]
            .as_array()
            .expect("route candidates");
        assert!(route_candidates.iter().all(|candidate| {
            candidate["progress_fingerprint"] == progress["source_fingerprint"]
                && candidate["aggregate_sequence"] == progress["aggregate_sequence"]
                && candidate["route_fingerprint"]
                    .as_str()
                    .expect("route fingerprint")
                    .starts_with("sha256:")
        }));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_continue_once_runs_one_created_task_from_expected_progress_state() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        let first = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Headless first".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start first");
        let second = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Headless second".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start second");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let progress = parse_line(r#"{"jsonrpc":"2.0","id":1,"method":"task.list"}"#)
            .result
            .expect("list result")["progress_overview"]
            .clone();
        let response = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"headless.continue_once","params":{{"authorize":true,"expected_progress_fingerprint":"{}","expected_aggregate_sequence":{},"continuation_id":"continue.created.1"}}}}"#,
            progress["source_fingerprint"]
                .as_str()
                .expect("fingerprint"),
            progress["aggregate_sequence"].as_u64().expect("sequence")
        ));
        let expected_selected = [&first, &second]
            .into_iter()
            .min_by(|left, right| left.task_id.cmp(&right.task_id))
            .expect("selected task");
        let expected_not_selected = if expected_selected.task_id == first.task_id {
            &second
        } else {
            &first
        };
        let result = response
            .result
            .unwrap_or_else(|| panic!("continue result: {:?}", response.error));
        assert_eq!(result["status"], "task_executed");
        assert_eq!(result["candidate_count"], 2);
        assert_eq!(result["selected_task_id"], expected_selected.task_id);
        assert_eq!(
            result["task_run_result"]["task_id"],
            expected_selected.task_id
        );
        assert_eq!(result["stale"], false);
        assert!(result["decision_id"]
            .as_str()
            .expect("decision id")
            .starts_with("headless_decision_"));

        let selected_events = store
            .tasks()
            .read_ledger_events(&expected_selected.run_id)
            .expect("selected events");
        let decision_index = selected_events
            .iter()
            .position(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
            .expect("decision event");
        let running_index = selected_events
            .iter()
            .position(|event| event.kind == LedgerEventKind::TaskRunning)
            .expect("running event");
        assert!(decision_index < running_index);
        let decision_payload = selected_events[decision_index]
            .payload
            .as_ref()
            .expect("decision payload");
        assert_eq!(decision_payload["authorize"], true);
        assert_eq!(decision_payload["candidate_count"], 2);
        assert_eq!(decision_payload["next_action"], "run_task_explicitly");
        let decision_payload_text =
            serde_json::to_string(decision_payload).expect("decision payload json");
        assert!(!decision_payload_text.contains("raw_provider_response"));
        assert!(!decision_payload_text.contains("prompt"));
        assert!(!decision_payload_text.contains("stdout"));
        assert!(!decision_payload_text.contains("stderr"));
        assert!(!decision_payload_text.contains("environment"));

        let not_selected_state = store
            .tasks()
            .get_task(&expected_not_selected.task_id)
            .expect("not selected task")
            .expect("not selected task");
        assert_eq!(not_selected_state.status, TaskStatus::Created);
        let all_events = store
            .tasks()
            .read_ledger_events(&first.run_id)
            .expect("first events")
            .into_iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count()
            + store
                .tasks()
                .read_ledger_events(&second.run_id)
                .expect("second events")
                .into_iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count();
        assert_eq!(all_events, 1);

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

