    #[test]
    fn headless_run_advance_persists_checkpoint_replays_and_advances_from_checkpoint() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        let first = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Run session first".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start first");
        let second = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Run session second".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start second");
        let third = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Run session third".to_string(),
                mode_id: Some("orchestrator".to_string()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start third");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let progress = parse_line(r#"{"jsonrpc":"2.0","id":1,"method":"task.list"}"#)
            .result
            .expect("list result")["progress_overview"]
            .clone();
        let first_request = format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"headless.run.advance","params":{{"authorize":true,"session_id":"m17.session","advance_id":"m17.advance.1","expected_session_sequence":1,"expected_progress_fingerprint":"{}","expected_aggregate_sequence":{},"max_steps":2,"context_budget":{{"max_prompt_chars":4096,"max_ledger_events":1,"max_selected_index_chars":0}}}}}}"#,
            progress["source_fingerprint"]
                .as_str()
                .expect("fingerprint"),
            progress["aggregate_sequence"].as_u64().expect("sequence")
        );
        let first_response = parse_line(&first_request);
        let first_result = first_response
            .result
            .unwrap_or_else(|| panic!("run advance result: {:?}", first_response.error));
        assert_eq!(first_result["status"], "task_executed");
        assert_eq!(first_result["session_id"], "m17.session");
        assert_eq!(first_result["session_sequence"], 1);
        assert_eq!(first_result["step_count"], 2);
        assert_eq!(first_result["executed_count"], 2);
        assert_eq!(first_result["replayed"], false);
        assert!(first_result["checkpoint_fingerprint"]
            .as_str()
            .expect("checkpoint fingerprint")
            .starts_with("sha256:"));
        assert_eq!(
            first_result["steps"][0]["continuation_id"],
            "run.m17.session.1.step.1"
        );
        assert_eq!(
            first_result["steps"][1]["continuation_id"],
            "run.m17.session.1.step.2"
        );
        assert_eq!(
            first_result["steps"][0]["context_budget"]["requested"],
            true
        );
        assert_eq!(
            first_result["steps"][0]["context_budget"]["max_ledger_events"],
            1
        );
        assert_eq!(
            first_result["steps"][1]["context_budget"]["requested"],
            true
        );
        assert_eq!(
            first_result["steps"][1]["context_budget"]["max_selected_index_chars"],
            0
        );
        let first_terminal_evidence = &first_result["terminal_completion_evidence"];
        assert_eq!(first_terminal_evidence["final_state"], "Completed");
        assert_eq!(first_terminal_evidence["task_status"], "Completed");
        assert!(first_terminal_evidence["completion_result_fingerprint"]
            .as_str()
            .expect("advance terminal completion fingerprint")
            .starts_with("sha256:"));
        assert_eq!(
            first_result["steps"][1]["terminal_completion_evidence"]
                ["completion_result_fingerprint"],
            first_terminal_evidence["completion_result_fingerprint"]
        );
        assert_eq!(
            first_result["steps"][0]["terminal_completion_evidence"]["final_response_present"],
            true
        );
        assert!(first_result["steps"][0].get("prompt").is_none());
        assert!(first_result["steps"][0].get("provider_response").is_none());
        assert!(first_terminal_evidence.get("final_response").is_none());
        assert!(first_terminal_evidence.get("absolute_path").is_none());

        let replay_response = parse_line(&first_request);
        let replay_result = replay_response
            .result
            .unwrap_or_else(|| panic!("run advance replay: {:?}", replay_response.error));
        assert_eq!(replay_result["replayed"], true);
        assert_eq!(
            replay_result["checkpoint_fingerprint"],
            first_result["checkpoint_fingerprint"]
        );
        assert_eq!(
            replay_result["steps"][0]["context_budget"],
            first_result["steps"][0]["context_budget"]
        );
        assert_eq!(
            replay_result["terminal_completion_evidence"],
            first_result["terminal_completion_evidence"]
        );
        assert_eq!(
            replay_result["steps"][1]["terminal_completion_evidence"],
            first_result["steps"][1]["terminal_completion_evidence"]
        );

        let second_response = parse_line(
            r#"{"jsonrpc":"2.0","id":3,"method":"headless.run.advance","params":{"authorize":true,"session_id":"m17.session","expected_session_sequence":2,"max_steps":1}}"#,
        );
        let second_result = second_response
            .result
            .unwrap_or_else(|| panic!("second run advance: {:?}", second_response.error));
        assert_eq!(second_result["status"], "task_executed");
        assert_eq!(second_result["session_sequence"], 2);
        assert_eq!(second_result["step_count"], 1);
        assert_eq!(second_result["executed_count"], 1);
        assert_eq!(
            second_result["start_progress"],
            first_result["post_progress"]
        );
        assert_eq!(
            second_result["steps"][0]["terminal_completion_evidence"]
                ["completion_result_fingerprint"],
            second_result["terminal_completion_evidence"]["completion_result_fingerprint"]
        );

        let selected_run_ids = first_result["steps"]
            .as_array()
            .expect("first steps")
            .iter()
            .chain(
                second_result["steps"]
                    .as_array()
                    .expect("second steps")
                    .iter(),
            )
            .map(|step| {
                step["selected_run_id"]
                    .as_str()
                    .expect("run id")
                    .to_string()
            })
            .collect::<Vec<_>>();
        let running_events = selected_run_ids
            .iter()
            .map(|run_id| {
                store
                    .tasks()
                    .read_ledger_events(run_id)
                    .expect("events")
                    .into_iter()
                    .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                    .count()
            })
            .sum::<usize>();
        let session_events = selected_run_ids
            .iter()
            .map(|run_id| {
                store
                    .tasks()
                    .read_ledger_events(run_id)
                    .expect("events")
                    .into_iter()
                    .filter(|event| event.kind == LedgerEventKind::HeadlessRunSessionAdvanced)
                    .count()
            })
            .sum::<usize>();
        assert_eq!(running_events, 3);
        assert_eq!(session_events, 3);
        assert!(store
            .tasks()
            .get_task(&first.task_id)
            .expect("first")
            .is_some());
        assert!(store
            .tasks()
            .get_task(&second.task_id)
            .expect("second")
            .is_some());
        assert!(store
            .tasks()
            .get_task(&third.task_id)
            .expect("third")
            .is_some());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

