        assert_eq!(
            parent_join.result.expect("parent join result")["status"],
            "Completed"
        );
        let parent_event_count_after_parent_join = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events after parent join")
            .len();
