    fn child_count_for_parent_run(store: &BrownieStore, parent_run_id: &str) -> usize {
        store
            .tasks()
            .list_tasks()
            .expect("list parent children")
            .into_iter()
            .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id))
            .count()
    }

    fn assert_parent_inspection_did_not_mutate(
        store: &BrownieStore,
        parent_run_id: &str,
        expected_parent_event_count: usize,
        expected_child_count: usize,
    ) {
        assert_eq!(
            store
                .tasks()
                .read_ledger_events(parent_run_id)
                .expect("parent events after inspect")
                .len(),
            expected_parent_event_count
        );
        assert_eq!(
            child_count_for_parent_run(store, parent_run_id),
            expected_child_count
        );
    }

    fn start_recovery_cycle_child_with_parent_evidence(
        workspace_root: &std::path::Path,
    ) -> (TaskRecord, TaskRecord, RecoveryCycleChildProvenance) {
        start_recovery_cycle_child_with_parent_evidence_at_depth(workspace_root, 2)
    }

    fn start_recovery_cycle_child_with_parent_evidence_at_depth(
        workspace_root: &std::path::Path,
        recovery_cycle_depth: usize,
    ) -> (TaskRecord, TaskRecord, RecoveryCycleChildProvenance) {
        let store = BrownieStore::new(workspace_root);
        let parent = store
            .tasks()
            .start_task(TaskStartParams {
                goal: "Parent recovery-cycle admission".into(),
                mode_id: Some("orchestrator".into()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
            })
            .expect("start parent");
        let provenance = RecoveryCycleChildProvenance {
            parent_join_admission_id: "parent_join_admission_m5_26".into(),
            parent_join_child_completion_fingerprint: format!("sha256:{}", "a".repeat(64)),
            parent_join_child_completion_child_count: recovery_cycle_depth + 1,
            parent_join_terminal_failed_child_count: 1,
            parent_join_terminal_completed_child_count: recovery_cycle_depth,
            parent_join_recovery_cycle: true,
            parent_join_recovery_cycle_depth: recovery_cycle_depth,
        };
        let source_handoff_envelope_id = "handoff_envelope_m5_26";
        let source_handoff_envelope_fingerprint = format!("sha256:{}", "b".repeat(64));
        let source_candidate_id = "candidate_m5_26_recovery_child";
        store
            .tasks()
            .append_task_event_with_payload(
                &parent,
                LedgerEventKind::ParentJoinContinuationFingerprintConsumed,
                Some(json!({
                    "parent_join_continuation_status": "Consumed",
                    "admission_id": provenance.parent_join_admission_id,
                    "child_completion_fingerprint": provenance.parent_join_child_completion_fingerprint,
                    "child_completion_child_count": provenance.parent_join_child_completion_child_count,
                    "child_terminal_failed_count": provenance.parent_join_terminal_failed_child_count,
                    "child_terminal_completed_count": provenance.parent_join_terminal_completed_child_count,
                    "child_recovery_cycle_depth": provenance.parent_join_recovery_cycle_depth,
                    "fingerprint_input_count": 5,
                    "reason": "Parent join continuation admitted for M5.26 recovery-cycle child run provenance guard."
                })),
            )
            .expect("append parent join admission evidence");
        store
            .tasks()
            .append_task_event_with_payload(
                &parent,
                LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded,
                Some(json!({
                    "handoff_envelope_status": "Accepted",
                    "handoff_envelope_id": source_handoff_envelope_id,
                    "handoff_envelope_fingerprint": source_handoff_envelope_fingerprint,
                    "candidate_ids": [source_candidate_id],
                    "parent_join_admission_id": provenance.parent_join_admission_id,
                    "parent_join_child_completion_fingerprint": provenance.parent_join_child_completion_fingerprint,
                    "parent_join_child_completion_child_count": provenance.parent_join_child_completion_child_count,
                    "parent_join_terminal_failed_child_count": provenance.parent_join_terminal_failed_child_count,
                    "parent_join_terminal_completed_child_count": provenance.parent_join_terminal_completed_child_count,
                    "parent_join_recovery_cycle": provenance.parent_join_recovery_cycle,
                    "parent_join_recovery_cycle_depth": provenance.parent_join_recovery_cycle_depth,
                    "scheduler_handoff_status": "Blocked",
                    "execution_enabled": false,
                    "reason": "Accepted parent join recovery-cycle handoff envelope for controlled child materialization."
                })),
            )
            .expect("append accepted handoff envelope evidence");
        let child = store
            .tasks()
            .start_child_task(ChildTaskStartParams {
                goal: "Run recovery-cycle child after provenance admission guard".into(),
                mode_id: Some("orchestrator".into()),
                parent_task_id: parent.task_id.clone(),
                parent_run_id: parent.run_id.clone(),
                source_candidate_id: source_candidate_id.into(),
                source_handoff_envelope_id: source_handoff_envelope_id.into(),
                source_handoff_envelope_fingerprint,
                source_intent_summary: None,
                recovery_cycle_provenance: Some(provenance.clone()),
                external_modepack_child_provenance: None,
            })
            .expect("start recovery-cycle child");

        (parent, child, provenance)
    }

    fn mutate_task_state(
        workspace_root: &std::path::Path,
        run_id: &str,
        mutate: impl FnOnce(&mut Value),
    ) {
        let state_path = workspace_root
            .join(".brownie/runs")
            .join(run_id)
            .join("state.json");
        let mut state: Value =
            serde_json::from_str(&std::fs::read_to_string(&state_path).expect("task state"))
                .expect("task state json");
        mutate(&mut state);
        std::fs::write(
            &state_path,
            serde_json::to_string_pretty(&state).expect("task state serialize"),
        )
        .expect("write task state");
    }

    fn assert_recovery_child_run_rejected_before_running(
        workspace_root: &std::path::Path,
        child: &TaskRecord,
        expected_message: &str,
    ) {
        let child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":41,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            child.task_id
        ));
        assert!(child_run.result.is_none());
        let error = child_run.error.expect("child run error");
        assert_eq!(error.code, -32602);
        assert!(error.message.contains(expected_message));

        let store = BrownieStore::new(workspace_root);
        let rejected_child = store
            .tasks()
            .get_task(&child.task_id)
            .expect("get rejected child")
            .expect("rejected child");
        assert_eq!(rejected_child.status, TaskStatus::Queued);
        let child_events = store
            .tasks()
            .read_ledger_events(&child.run_id)
            .expect("child events");
        assert!(!child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
    }

    fn clear_llm_env_for_test() {
        for key in [
            "BROWNIE_LLM_PROVIDER",
            "BROWNIE_LLM_BASE_URL",
            "BROWNIE_LLM_MODEL",
            "BROWNIE_LLM_API_KEY_ENV",
            "BROWNIE_LLM_API_KEY",
            "BROWNIE_LLM_STRICT",
            "BROWNIE_LLM_ALLOW_TASK_RUN_NETWORK",
        ] {
            std::env::remove_var(key);
        }
    }

    fn configure_strict_missing_openai_for_test() {
        std::env::set_var("BROWNIE_LLM_PROVIDER", "openai-compatible");
        std::env::set_var("BROWNIE_LLM_STRICT", "true");
        std::env::remove_var("BROWNIE_LLM_BASE_URL");
        std::env::remove_var("BROWNIE_LLM_MODEL");
        std::env::remove_var("BROWNIE_LLM_API_KEY_ENV");
        std::env::remove_var("BROWNIE_LLM_API_KEY");
    }

    #[test]
    fn llm_failure_reason_is_bounded_before_persistence() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        clear_llm_env_for_test();
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Bound failure reason","mode_id":"orchestrator"}}"#,
        );
        let task_id = start.result.expect("start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let store = BrownieStore::new(temp.path());
        let running = store
            .tasks()
            .update_task_status(&task_id, TaskStatus::Running, LedgerEventKind::TaskRunning)
            .expect("mark running");
        let long_reason = format!(
            "{}LONG_FAILURE_REASON_TAIL_SHOULD_NOT_APPEAR",
            "bounded failure reason ".repeat(80)
        );
        let _ = fail_llm_request(
            &store,
            &running,
            json!(2),
            default_fake_status(),
            &long_reason,
            LedgerEventKind::LlmRequestFailed,
        );

        let events = store
            .tasks()
            .read_ledger_events(&running.run_id)
            .expect("events");
        let failure_payload = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::LlmRequestFailed)
            .and_then(|event| event.payload.as_ref())
            .expect("failure payload");
        let reason = failure_payload["reason"]
            .as_str()
            .expect("bounded failure reason");
        assert!(reason.chars().count() <= LLM_FAILURE_REASON_PREVIEW_CHARS);
        assert!(!reason.contains("LONG_FAILURE_REASON_TAIL_SHOULD_NOT_APPEAR"));
        assert_eq!(failure_payload["reason_truncated"], true);
        assert!(
            failure_payload["reason_chars"]
                .as_u64()
                .expect("reason chars")
                > LLM_FAILURE_REASON_PREVIEW_CHARS as u64
        );
        assert!(failure_payload["reason_sha256"]
            .as_str()
            .expect("reason sha")
            .starts_with("sha256:"));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        clear_llm_env_for_test();
    }

    #[test]
    fn task_run_accepts_valid_queued_child_task_with_provenance() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, child, parent_event_count) =
            start_parent_with_queued_child();

        let child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            child.task_id
        ));
        assert!(child_run.error.is_none());
        let child_result = child_run.result.expect("child run result");
        assert_eq!(child_result["task_id"], child.task_id);
        assert_eq!(child_result["run_id"], child.run_id);
        assert_eq!(child_result["status"], "Completed");

        let store = BrownieStore::new(temp.path());
        let completed_child = store
            .tasks()
            .get_task(&child.task_id)
            .expect("get child")
            .expect("child record");
        assert_eq!(completed_child.status, TaskStatus::Completed);
        assert_eq!(
            completed_child.parent_task_id.as_deref(),
            Some(parent_task_id.as_str())
        );
        assert_eq!(
            completed_child.parent_run_id.as_deref(),
            Some(parent_run_id.as_str())
        );
        assert_eq!(
            completed_child.source_candidate_id.as_deref(),
            child.source_candidate_id.as_deref()
        );
        assert_eq!(
            completed_child
                .source_handoff_envelope_fingerprint
                .as_deref(),
            child.source_handoff_envelope_fingerprint.as_deref()
        );

        let child_events = store
            .tasks()
            .read_ledger_events(&child.run_id)
            .expect("child ledger");
        assert!(child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
        assert!(child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::AgentLoopStarted));
        assert!(child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskCompleted));

        assert_eq!(
            store
                .tasks()
                .read_ledger_events(&parent_run_id)
                .expect("parent ledger after child run")
                .len(),
            parent_event_count
        );

        let parent_inspect = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"run.inspect","params":{{"run_id":"{parent_run_id}"}}}}"#
        ));
        let parent_summary = parent_inspect.result.expect("parent inspect")["run"].clone();
        assert_eq!(parent_summary["child_task_count"], 1);
        assert!(parent_summary["child_task_ids"]
            .as_array()
            .expect("child ids")
            .iter()
            .any(|value| value.as_str() == Some(child.task_id.as_str())));
        let parent_child_summaries = parent_summary["child_tasks"]
            .as_array()
            .expect("child summaries");
        assert_eq!(parent_child_summaries.len(), 1);
        let child_summary = &parent_child_summaries[0];
        assert_eq!(child_summary["task_id"], child.task_id);
        assert_eq!(child_summary["run_id"], child.run_id);
        assert_eq!(child_summary["status"], "Completed");
        assert_eq!(child_summary["parent_task_id"], parent_task_id);
        assert_eq!(child_summary["parent_run_id"], parent_run_id);
        assert_eq!(
            child_summary["source_candidate_id"],
            child
                .source_candidate_id
                .as_deref()
                .expect("source candidate id")
        );
        assert_eq!(
            child_summary["source_handoff_envelope_fingerprint"],
            child
                .source_handoff_envelope_fingerprint
                .as_deref()
                .expect("source handoff envelope fingerprint")
        );
        assert_eq!(
            child_summary["source_intent_summary"]["tool_id"],
            SUBTASK_SPAWN_TOOL_ID
        );
        assert_eq!(
            child_summary["source_intent_summary"]["request_reason"],
            "Orchestrator mode may coordinate subtasks."
        );
        assert!(child_summary["source_intent_summary"]
            .get("input")
            .is_none());
        assert!(child_summary["event_count"].as_u64().expect("event count") > 1);
        assert_eq!(child_summary["has_agent_loop_completed"], true);
        assert_eq!(child_summary["completion_final_state"], "Completed");
        assert!(child_summary["completion_result_fingerprint"]
            .as_str()
            .expect("completion result fingerprint")
            .starts_with("sha256:"));
        assert!(child_summary["completion_summary_preview"]
            .as_str()
            .expect("completion summary preview")
            .contains(&child.task_id));
        assert!(child_summary["final_response_preview"]
            .as_str()
            .expect("final response preview")
            .contains("Fake LLM"));

        let child_inspect = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"task.inspect","params":{{"task_id":"{}"}}}}"#,
            child.task_id
        ));
        let inspected_child = child_inspect.result.expect("child inspect")["task"].clone();
        assert_eq!(inspected_child["status"], "Completed");
        assert_eq!(inspected_child["parent_task_id"], parent_task_id);
        assert_eq!(inspected_child["parent_run_id"], parent_run_id);
        assert_eq!(
            inspected_child["source_handoff_envelope_fingerprint"],
            child
                .source_handoff_envelope_fingerprint
                .as_deref()
                .expect("source handoff envelope fingerprint")
        );
        assert_eq!(
            inspected_child["source_intent_summary"]["request_reason"],
            "Orchestrator mode may coordinate subtasks."
        );
        assert!(inspected_child["source_intent_summary"]
            .get("input")
            .is_none());

        let rerun = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":6,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            child.task_id
        ));
        assert!(rerun.error.is_none());
        let rerun_result = rerun.result.expect("rerun result");
        assert_eq!(rerun_result["status"], "Completed");
        assert_parent_join_readiness_outcome(
            &rerun_result["parent_join_readiness_outcome"],
            &parent_task_id,
            &parent_run_id,
            &child,
            "Completed",
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_replays_child_orchestration_outcome_for_existing_queued_child_without_mutation() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, child, parent_event_count) =
            start_parent_with_queued_child();
        let store = BrownieStore::new(temp.path());
        let parent_events_before = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent ledger before replay");
        assert_eq!(parent_events_before.len(), parent_event_count);
        let parent_task_running_count_before = parent_events_before
            .iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();
        let parent_join_consumption_count_before = parent_events_before
            .iter()
            .filter(|event| {
                event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
            })
            .count();
        let handoff_envelope_count_before = parent_events_before
            .iter()
            .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
            .count();
        let child_count_before = store
            .tasks()
            .list_tasks()
            .expect("list tasks before replay")
            .into_iter()
            .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
            .count();
        let child_running_event_count_before = store
            .tasks()
            .read_ledger_events(&child.run_id)
            .expect("child ledger before replay")
            .into_iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();

        let replay = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(replay.error.is_none());
        let replay_result = replay.result.expect("queued child replay result");
        assert_eq!(replay_result["status"], "Completed");
        assert!(replay_result.get("recovery_cycle_budget_outcome").is_none());
        let outcome = replay_result["child_orchestration_outcome"].clone();
        assert_eq!(outcome["parent_run_id"], parent_run_id);
        assert_eq!(outcome["materialized_child_count"], 1);
        assert_eq!(outcome["queued_child_count"], 1);
        assert_eq!(outcome["child_running_enabled"], false);
        assert_eq!(outcome["next_action"], "run_child_task_explicitly");
        assert_eq!(
            payload_string_array(&outcome, "materialized_child_task_ids"),
            vec![child.task_id.clone()]
        );
        assert_eq!(
            payload_string_array(&outcome, "queued_child_task_ids"),
            vec![child.task_id.clone()]
        );
        let serialized_outcome = outcome.to_string();
        for raw_marker in [
            "Run parent orchestrator",
            "Orchestrator mode may coordinate subtasks.",
            "requested_goal_preview",
            "request_reason",
            "raw child prompt",
            "provider",
            "stdout",
            "stderr",
            "input",
        ] {
            assert!(!serialized_outcome.contains(raw_marker));
        }

        let parent = store
            .tasks()
            .get_task(&parent_task_id)
            .expect("get parent")
            .expect("parent");
        assert_eq!(parent.status, TaskStatus::Completed);
        let parent_events_after = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent ledger after replay");
        assert_eq!(parent_events_after.len(), parent_event_count);
        assert_eq!(
            parent_events_after
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            parent_task_running_count_before
        );
        assert_eq!(
            parent_events_after
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
                })
                .count(),
            parent_join_consumption_count_before
        );
        assert_eq!(
            parent_events_after
                .iter()
                .filter(
                    |event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded
                )
                .count(),
            handoff_envelope_count_before
        );
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list tasks after replay")
                .into_iter()
                .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
                .count(),
            child_count_before
        );
        let child = store
            .tasks()
            .get_task(&child.task_id)
            .expect("get child")
            .expect("child");
        assert_eq!(child.status, TaskStatus::Queued);
        let child_events = store
            .tasks()
            .read_ledger_events(&child.run_id)
            .expect("child ledger");
        assert_eq!(
            child_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            child_running_event_count_before
        );
        let parent_run_inspect = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"run.inspect","params":{{"run_id":"{parent_run_id}"}}}}"#
        ));
        assert!(parent_run_inspect.error.is_none());
        assert_eq!(
            payload_string_array(
                &parent_run_inspect.result.expect("parent inspect")["run"],
                "child_task_ids"
            ),
            vec![child.task_id.clone()]
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_parent_join_continuation_consumes_completed_child_summary() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, child, _parent_event_count) =
            start_parent_with_queued_child();

        let child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            child.task_id
        ));
        assert!(child_run.error.is_none());
        assert_eq!(
            child_run.result.expect("child run result")["status"],
            "Completed"
        );

        let store = BrownieStore::new(temp.path());
        let completed_child = store
            .tasks()
            .get_task(&child.task_id)
            .expect("get child")
            .expect("child");
        assert_eq!(completed_child.status, TaskStatus::Completed);
        store
            .tasks()
            .append_task_event_with_payload(
                &completed_child,
                LedgerEventKind::PromptBuilt,
                Some(json!({
                    "prompt_preview": "RAW_CHILD_PROMPT_SHOULD_NOT_APPEAR"
                })),
            )
            .expect("append child prompt evidence");
        store
            .tasks()
            .append_task_event_with_payload(
                &completed_child,
                LedgerEventKind::ToolExecutionCompleted,
                Some(json!({
                    "tool_id": "workspace.read",
                    "status": "Completed",
                    "bytes_read": 42,
                    "truncated": false,
                    "output_preview": "RAW_CHILD_FILE_CONTENT_SHOULD_NOT_APPEAR"
                })),
            )
            .expect("append child tool evidence");
        let child_event_count = store
            .tasks()
            .read_ledger_events(&child.run_id)
            .expect("child events before join")
            .len();

        let parent_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(parent_join.error.is_none());
        let parent_join_result = parent_join.result.expect("parent join result");
        assert_eq!(parent_join_result["task_id"], parent_task_id);
        assert_eq!(parent_join_result["run_id"], parent_run_id);
        assert_eq!(parent_join_result["status"], "Completed");

        assert_eq!(
            store
                .tasks()
                .read_ledger_events(&child.run_id)
                .expect("child events after join")
                .len(),
            child_event_count
        );

        let parent_events = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events");
        assert_eq!(
            parent_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            2
        );
        assert_eq!(
            parent_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompleted)
                .count(),
            2
        );
        let consumption_payload = parent_events
            .iter()
            .find(|event| event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed)
            .and_then(|event| event.payload.as_ref())
            .expect("parent join continuation consumption payload");
        assert_eq!(
            consumption_payload["parent_join_continuation_status"],
            "Consumed"
        );
        assert!(consumption_payload["child_completion_fingerprint"]
            .as_str()
            .expect("child completion fingerprint")
            .starts_with("sha256:"));
        let admission_id = consumption_payload["admission_id"]
            .as_str()
            .expect("parent join admission id");
        assert_eq!(consumption_payload["child_completion_child_count"], 1);
        assert!(
            consumption_payload["fingerprint_input_count"]
                .as_u64()
                .expect("fingerprint input count")
                > 0
        );
        let consumption_index = parent_events
            .iter()
            .position(|event| {
                event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
            })
            .expect("consumption event index");
        let second_running_index = parent_events
            .iter()
            .enumerate()
            .filter(|(_, event)| event.kind == LedgerEventKind::TaskRunning)
            .nth(1)
            .map(|(index, _)| index)
            .expect("second TaskRunning index");
        assert!(consumption_index < second_running_index);
        let second_running_payload = parent_events[second_running_index]
            .payload
            .as_ref()
            .expect("second TaskRunning payload");
        assert_eq!(second_running_payload["admission_id"], admission_id);
        let continuation_prompt_payload = parent_events
            .iter()
            .rev()
            .find(|event| event.kind == LedgerEventKind::PromptBuilt)
            .and_then(|event| event.payload.as_ref())
            .expect("continuation prompt payload");
        let continuation_prompt_preview = continuation_prompt_payload["prompt_preview"]
            .as_str()
            .expect("continuation prompt preview");
        assert!(continuation_prompt_preview.contains("completed_child task_id="));
        assert!(continuation_prompt_preview.contains(&child.task_id));
        assert!(continuation_prompt_preview.contains(
            child
                .source_candidate_id
                .as_deref()
                .expect("source candidate id")
        ));
        assert!(continuation_prompt_preview.contains("completion_summary_preview="));
        assert!(continuation_prompt_preview.contains("final_response_preview=Fake LLM"));
        assert!(!continuation_prompt_preview.contains("RAW_CHILD_PROMPT_SHOULD_NOT_APPEAR"));
        assert!(!continuation_prompt_preview.contains("RAW_CHILD_FILE_CONTENT_SHOULD_NOT_APPEAR"));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_parent_join_materializes_continuation_subtask_without_auto_run() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, initial_child, _parent_event_count) =
            start_parent_with_queued_child();

        let initial_child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            initial_child.task_id
        ));
        assert!(initial_child_run.error.is_none());

        let parent_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(parent_join.error.is_none());
        let parent_join_result = parent_join.result.expect("parent join result");
        assert_eq!(parent_join_result["status"], "Completed");

        let store = BrownieStore::new(temp.path());
        let parent = store
            .tasks()
            .get_task(&parent_task_id)
            .expect("get parent")
            .expect("parent");
        assert_eq!(parent.status, TaskStatus::Completed);

        let parent_children = store
            .tasks()
            .list_tasks()
            .expect("list tasks")
            .into_iter()
            .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
            .collect::<Vec<_>>();
        assert_eq!(parent_children.len(), 2);
        let continuation_child = parent_children
            .iter()
            .find(|record| record.task_id != initial_child.task_id)
            .expect("continuation child");
        assert_eq!(continuation_child.status, TaskStatus::Queued);
        assert_eq!(
            continuation_child.parent_task_id.as_deref(),
            Some(parent_task_id.as_str())
        );
        assert_eq!(
            continuation_child.parent_run_id.as_deref(),
            Some(parent_run_id.as_str())
        );
        assert_ne!(
            continuation_child.source_candidate_id,
            initial_child.source_candidate_id
        );
        assert!(continuation_child
            .source_handoff_envelope_fingerprint
            .as_deref()
            .expect("continuation handoff fingerprint")
            .starts_with("sha256:"));
        assert_eq!(
            continuation_child
                .source_intent_summary
                .as_ref()
                .expect("source intent summary")
                .request_reason,
            "Orchestrator mode may coordinate subtasks."
        );

        let child_events = store
            .tasks()
            .read_ledger_events(&continuation_child.run_id)
            .expect("continuation child ledger");
        assert_eq!(child_events.len(), 1);
        assert_eq!(child_events[0].kind, LedgerEventKind::TaskStarted);
        let child_started_payload = child_events[0]
            .payload
            .as_ref()
            .expect("child started payload");
        assert_eq!(child_started_payload["status"], "Queued");
        assert_eq!(child_started_payload["execution_enabled"], false);
        assert_eq!(child_started_payload["scheduler_handoff_enabled"], false);
        assert!(child_started_payload["source_intent_summary"]
            .get("input")
            .is_none());
        assert!(!child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));

        let parent_events = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events");
        let continuation_envelope_payload = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
            .filter_map(|event| event.payload.as_ref())
            .find(|payload| {
                payload
                    .get("continuation_materialization")
                    .and_then(Value::as_bool)
                    == Some(true)
            })
            .expect("continuation handoff envelope");
        assert_eq!(
            continuation_envelope_payload["required_capability"],
            "continuation_subtask_materialization"
        );
        assert_eq!(
            continuation_envelope_payload["parent_join_child_completion_child_count"],
            1
        );
        assert_eq!(continuation_envelope_payload["dispatch_enabled"], false);
        assert_eq!(continuation_envelope_payload["execution_enabled"], false);
        assert!(
            continuation_envelope_payload["parent_join_child_completion_fingerprint"]
                .as_str()
                .expect("child completion fingerprint")
                .starts_with("sha256:")
        );
        let candidate_ids = continuation_envelope_payload["candidate_ids"]
            .as_array()
            .expect("candidate ids");
        assert!(candidate_ids.iter().any(|candidate| {
            candidate.as_str() == continuation_child.source_candidate_id.as_deref()
        }));
        assert_eq!(
            continuation_child.source_handoff_envelope_id.as_deref(),
            continuation_envelope_payload["handoff_envelope_id"].as_str()
        );
        assert_eq!(
            continuation_child
                .source_handoff_envelope_fingerprint
                .as_deref(),
            continuation_envelope_payload["handoff_envelope_fingerprint"].as_str()
        );
        assert!(
            validate_controlled_queued_child_task_provenance(continuation_child, &store).is_ok()
        );
        let expected_outcome = parent_join_result["child_orchestration_outcome"].clone();
        assert_eq!(expected_outcome["parent_run_id"], parent_run_id);
        assert_eq!(expected_outcome["materialized_child_count"], 1);
        assert_eq!(expected_outcome["queued_child_count"], 1);
        assert_eq!(expected_outcome["child_running_enabled"], false);
        assert_eq!(expected_outcome["next_action"], "run_child_task_explicitly");
        assert_eq!(
            payload_string_array(&expected_outcome, "materialized_child_task_ids"),
            vec![continuation_child.task_id.clone()]
        );
        assert_eq!(
            payload_string_array(&expected_outcome, "queued_child_task_ids"),
            vec![continuation_child.task_id.clone()]
        );

        materialize_controlled_child_task_from_handoff_envelope(&store, &parent)
            .expect("idempotent materialization");
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list tasks after duplicate prevention")
                .iter()
                .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
                .count(),
            2
        );
        let parent_task_running_count_after_join = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();
        let parent_join_consumption_count_after_join = parent_events
            .iter()
            .filter(|event| {
                event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
            })
            .count();
        let handoff_envelope_count_after_join = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
            .count();
        let parent_event_count_after_join = parent_events.len();
        let child_count_after_join = store
            .tasks()
            .list_tasks()
            .expect("list tasks before replay")
            .into_iter()
            .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
            .count();
        let child_running_event_count_after_join = store
            .tasks()
            .read_ledger_events(&continuation_child.run_id)
            .expect("continuation child ledger before replay")
            .into_iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();

        let initial_child_inspect_after_consumed_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":51,"method":"task.inspect","params":{{"task_id":"{}"}}}}"#,
            initial_child.task_id
        ));
        assert!(initial_child_inspect_after_consumed_join.error.is_none());
        let initial_child_inspect_after_consumed_join_result =
            initial_child_inspect_after_consumed_join
                .result
                .expect("initial child inspect after consumed join");
        assert_child_inspect_consumed_parent_join_recovery_summary(
            &initial_child_inspect_after_consumed_join_result
                ["consumed_parent_join_recovery_summary"],
            &parent_task_id,
            &parent_run_id,
            &initial_child,
            "Completed",
            1,
            std::slice::from_ref(&continuation_child.task_id),
            &[],
            0,
            "run_continuation_child_tasks_explicitly",
        );
        let continuation_child_inspect_after_consumed_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":52,"method":"task.inspect","params":{{"task_id":"{}"}}}}"#,
            continuation_child.task_id
        ));
        assert!(continuation_child_inspect_after_consumed_join
            .error
            .is_none());
        let continuation_child_inspect_after_consumed_join_result =
            continuation_child_inspect_after_consumed_join
                .result
                .expect("continuation child inspect after consumed join");
        assert_child_inspect_consumed_parent_join_recovery_summary(
            &continuation_child_inspect_after_consumed_join_result
                ["consumed_parent_join_recovery_summary"],
            &parent_task_id,
            &parent_run_id,
            continuation_child,
            "Queued",
            1,
            std::slice::from_ref(&continuation_child.task_id),
            &[],
            0,
            "run_continuation_child_tasks_explicitly",
        );
        let parent_run_inspect_after_consumed_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":53,"method":"run.inspect","params":{{"run_id":"{parent_run_id}"}}}}"#
        ));
        assert!(parent_run_inspect_after_consumed_join.error.is_none());
        let parent_run_inspect_after_consumed_join_result = parent_run_inspect_after_consumed_join
            .result
            .expect("parent run inspect after consumed join")["run"]
            .clone();
        assert_parent_inspect_consumed_parent_join_recovery_summary(
            &parent_run_inspect_after_consumed_join_result["consumed_parent_join_recovery_summary"],
            &parent_task_id,
            &parent_run_id,
            1,
            std::slice::from_ref(&continuation_child.task_id),
            &[],
            0,
            "run_continuation_child_tasks_explicitly",
        );
        let parent_task_inspect_after_consumed_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":54,"method":"task.inspect","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(parent_task_inspect_after_consumed_join.error.is_none());
        let parent_task_inspect_after_consumed_join_result =
            parent_task_inspect_after_consumed_join
                .result
                .expect("parent task inspect after consumed join")["run"]
                .clone();
        assert_eq!(
            parent_task_inspect_after_consumed_join_result["consumed_parent_join_recovery_summary"],
            parent_run_inspect_after_consumed_join_result["consumed_parent_join_recovery_summary"]
        );
        assert_parent_inspection_did_not_mutate(
            &store,
            &parent_run_id,
            parent_event_count_after_join,
            child_count_after_join,
        );

        let replay_parent_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(replay_parent_join.error.is_none());
        let replay_parent_join_result = replay_parent_join
            .result
            .expect("parent join replay result");
        assert_eq!(replay_parent_join_result["status"], "Completed");
        assert!(replay_parent_join_result
            .get("recovery_cycle_budget_outcome")
            .is_none());
        assert_eq!(
            replay_parent_join_result["child_orchestration_outcome"],
            expected_outcome
        );
        let replay_serialized =
            replay_parent_join_result["child_orchestration_outcome"].to_string();
        for raw_marker in [
            "Run parent orchestrator",
            "Orchestrator mode may coordinate subtasks.",
            "requested_goal_preview",
            "request_reason",
            "provider",
            "stdout",
            "stderr",
            "input",
        ] {
            assert!(!replay_serialized.contains(raw_marker));
        }
        let parent_events_after_replay = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events after replay");
        assert_eq!(
            parent_events_after_replay.len(),
            parent_event_count_after_join
        );
        assert_eq!(
            parent_events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            parent_task_running_count_after_join
        );
        assert_eq!(
            parent_events_after_replay
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
                })
                .count(),
            parent_join_consumption_count_after_join
        );
        assert_eq!(
            parent_events_after_replay
                .iter()
                .filter(
                    |event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded
                )
                .count(),
            handoff_envelope_count_after_join
        );
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list tasks after replay")
                .into_iter()
                .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
                .count(),
            child_count_after_join
        );
        assert_eq!(
            store
                .tasks()
                .read_ledger_events(&continuation_child.run_id)
                .expect("continuation child ledger after replay")
                .into_iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            child_running_event_count_after_join
        );

        let continuation_child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":6,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            continuation_child.task_id
        ));
        assert!(continuation_child_run.error.is_none());
        assert_eq!(
            continuation_child_run
                .result
                .expect("continuation child run result")["status"],
            "Completed"
        );
        let completed_continuation_child = store
            .tasks()
            .get_task(&continuation_child.task_id)
            .expect("get completed continuation child")
            .expect("completed continuation child");
        assert_eq!(completed_continuation_child.status, TaskStatus::Completed);

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_parent_join_recovers_failed_controlled_child_without_auto_run() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        clear_llm_env_for_test();
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, initial_child, _parent_event_count) =
            start_parent_with_queued_child();

        configure_strict_missing_openai_for_test();
        let failed_child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            initial_child.task_id
        ));
        assert!(failed_child_run.error.is_none());
        let failed_child_run_result = failed_child_run.result.expect("failed child run result");
        assert_eq!(failed_child_run_result["status"], "Failed");
        assert_parent_join_readiness_outcome(
            &failed_child_run_result["parent_join_readiness_outcome"],
            &parent_task_id,
            &parent_run_id,
            &initial_child,
            "Failed",
        );
        clear_llm_env_for_test();

        let store = BrownieStore::new(temp.path());
        let failed_child = store
            .tasks()
            .get_task(&initial_child.task_id)
            .expect("get failed child")
            .expect("failed child");
        assert_eq!(failed_child.status, TaskStatus::Failed);
        let failed_child_events = store
            .tasks()
            .read_ledger_events(&failed_child.run_id)
            .expect("failed child events");
        assert!(failed_child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
        assert!(failed_child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::LlmRequestFailed));
        assert!(failed_child_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskFailed));
        let failed_child_event_count_after_first_run = failed_child_events.len();
        let replay_failed_child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":33,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            failed_child.task_id
        ));
        assert!(replay_failed_child_run.error.is_none());
        let replay_failed_child_run_result = replay_failed_child_run
            .result
            .expect("replay failed child run result");
        assert_eq!(replay_failed_child_run_result["status"], "Failed");
        assert_eq!(
            replay_failed_child_run_result["parent_join_readiness_outcome"],
            failed_child_run_result["parent_join_readiness_outcome"]
        );
        assert_eq!(
            store
                .tasks()
                .read_ledger_events(&failed_child.run_id)
                .expect("failed child events after replay")
                .len(),
            failed_child_event_count_after_first_run
        );
        store
            .tasks()
            .append_task_event_with_payload(
                &failed_child,
                LedgerEventKind::PromptBuilt,
                Some(json!({
                    "prompt_preview": "RAW_FAILED_CHILD_PROMPT_SHOULD_NOT_APPEAR"
                })),
            )
            .expect("append failed child prompt marker");
        store
            .tasks()
            .append_task_event_with_payload(
                &failed_child,
                LedgerEventKind::ToolExecutionCompleted,
                Some(json!({
                    "tool_id": "workspace.read",
                    "status": "Completed",
                    "output_preview": "RAW_FAILED_CHILD_FILE_CONTENT_SHOULD_NOT_APPEAR"
                })),
            )
            .expect("append failed child raw marker");

        let parent_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(parent_join.error.is_none());
        let parent_join_result = parent_join.result.expect("parent join result");
        assert_eq!(parent_join_result["status"], "Completed");

        let parent = store
            .tasks()
            .get_task(&parent_task_id)
            .expect("get parent")
            .expect("parent");
        assert_eq!(parent.status, TaskStatus::Completed);
        let parent_children = store
            .tasks()
            .list_tasks()
            .expect("list parent children")
            .into_iter()
            .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
            .collect::<Vec<_>>();
        assert_eq!(parent_children.len(), 2);
        let recovery_child = parent_children
            .iter()
            .find(|record| record.task_id != failed_child.task_id)
            .expect("recovery child");
        assert_eq!(recovery_child.status, TaskStatus::Queued);
        assert_eq!(
            recovery_child
                .source_intent_summary
                .as_ref()
                .expect("recovery source intent")
                .request_reason,
            "Recover failed controlled child task."
        );
        let recovery_events = store
            .tasks()
            .read_ledger_events(&recovery_child.run_id)
            .expect("recovery child events");
        assert_eq!(recovery_events.len(), 1);
        assert_eq!(recovery_events[0].kind, LedgerEventKind::TaskStarted);
        assert!(!recovery_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));

        let parent_events = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events");
        let continuation_prompt_preview = parent_events
            .iter()
            .rev()
            .find(|event| event.kind == LedgerEventKind::PromptBuilt)
            .and_then(|event| event.payload.as_ref())
            .and_then(|payload| payload.get("prompt_preview"))
            .and_then(Value::as_str)
            .expect("continuation prompt preview");
        assert!(continuation_prompt_preview.contains("failed_child task_id="));
        assert!(continuation_prompt_preview.contains(&failed_child.task_id));
        assert!(continuation_prompt_preview.contains("failure_result_fingerprint=sha256:"));
        assert!(continuation_prompt_preview.contains("failure_summary_preview="));
        assert!(!continuation_prompt_preview.contains("RAW_FAILED_CHILD_PROMPT_SHOULD_NOT_APPEAR"));
        assert!(!continuation_prompt_preview
            .contains("RAW_FAILED_CHILD_FILE_CONTENT_SHOULD_NOT_APPEAR"));
        let continuation_consumptions = parent_events
            .iter()
            .filter(|event| {
                event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
            })
            .collect::<Vec<_>>();
        assert_eq!(continuation_consumptions.len(), 1);
        let continuation_envelope_payload = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
            .filter_map(|event| event.payload.as_ref())
            .find(|payload| {
                payload
                    .get("continuation_materialization")
                    .and_then(Value::as_bool)
                    == Some(true)
            })
            .expect("failed child continuation envelope");
        assert_eq!(
            continuation_envelope_payload["required_capability"],
            "continuation_subtask_materialization"
        );
        assert_eq!(
            recovery_child
                .source_handoff_envelope_fingerprint
                .as_deref(),
            continuation_envelope_payload["handoff_envelope_fingerprint"].as_str()
        );
        let expected_outcome = parent_join_result["child_orchestration_outcome"].clone();
        assert_eq!(expected_outcome["parent_run_id"], parent_run_id);
        assert_eq!(expected_outcome["materialized_child_count"], 1);
        assert_eq!(expected_outcome["queued_child_count"], 1);
        assert_eq!(expected_outcome["child_running_enabled"], false);
        assert_eq!(expected_outcome["next_action"], "run_child_task_explicitly");
        assert_eq!(
            payload_string_array(&expected_outcome, "materialized_child_task_ids"),
            vec![recovery_child.task_id.clone()]
        );
        assert_eq!(
            payload_string_array(&expected_outcome, "queued_child_task_ids"),
            vec![recovery_child.task_id.clone()]
        );

        let parent_event_count_after_join = parent_events.len();
        let parent_task_running_count_after_join = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();
        let parent_join_consumption_count_after_join = parent_events
            .iter()
            .filter(|event| {
                event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
            })
            .count();
        let handoff_envelope_count_after_join = parent_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded)
            .count();
        let child_count_after_join = parent_children.len();
        let recovery_child_running_count_after_join = recovery_events
            .iter()
            .filter(|event| event.kind == LedgerEventKind::TaskRunning)
            .count();
        let repeated_join = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"task.run","params":{{"task_id":"{parent_task_id}"}}}}"#
        ));
        assert!(repeated_join.error.is_none());
        let repeated_join_result = repeated_join.result.expect("repeat join result");
        assert_eq!(repeated_join_result["status"], "Completed");
        assert!(repeated_join_result
            .get("recovery_cycle_budget_outcome")
            .is_none());
        assert_eq!(
            repeated_join_result["child_orchestration_outcome"],
            expected_outcome
        );
        let replay_serialized = repeated_join_result["child_orchestration_outcome"].to_string();
        for raw_marker in [
            "RAW_FAILED_CHILD_PROMPT_SHOULD_NOT_APPEAR",
            "RAW_FAILED_CHILD_FILE_CONTENT_SHOULD_NOT_APPEAR",
            "provider",
            "stdout",
            "stderr",
            "input",
        ] {
            assert!(!replay_serialized.contains(raw_marker));
        }
        let parent_events_after_repeat = store
            .tasks()
            .read_ledger_events(&parent_run_id)
            .expect("parent events after repeat");
        assert_eq!(
            parent_events_after_repeat.len(),
            parent_event_count_after_join
        );
        assert_eq!(
            parent_events_after_repeat
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            parent_task_running_count_after_join
        );
        assert_eq!(
            parent_events_after_repeat
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::ParentJoinContinuationFingerprintConsumed
                })
                .count(),
            parent_join_consumption_count_after_join
        );
        assert_eq!(
            parent_events_after_repeat
                .iter()
                .filter(
                    |event| event.kind == LedgerEventKind::SubtaskDispatchHandoffEnvelopeRecorded
                )
                .count(),
            handoff_envelope_count_after_join
        );
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list parent children after repeat")
                .into_iter()
                .filter(|record| record.parent_run_id.as_deref() == Some(parent_run_id.as_str()))
                .count(),
            child_count_after_join
        );
        assert_eq!(
            store
                .tasks()
                .read_ledger_events(&recovery_child.run_id)
                .expect("recovery child events after repeat")
                .into_iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            recovery_child_running_count_after_join
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        clear_llm_env_for_test();
    }

    #[test]
    fn failed_child_terminal_outcome_fingerprint_changes_with_failure_reason() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        clear_llm_env_for_test();
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let (parent_task_id, parent_run_id, initial_child, _parent_event_count) =
            start_parent_with_queued_child();

        configure_strict_missing_openai_for_test();
        let failed_child_run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{}"}}}}"#,
            initial_child.task_id
        ));
        assert!(failed_child_run.error.is_none());
        let failed_child_run_result = failed_child_run.result.expect("failed child run result");
        assert_eq!(failed_child_run_result["status"], "Failed");
        assert_parent_join_readiness_outcome(
            &failed_child_run_result["parent_join_readiness_outcome"],
            &parent_task_id,
            &parent_run_id,
            &initial_child,
            "Failed",
        );
        clear_llm_env_for_test();

        let store = BrownieStore::new(temp.path());
        let failed_child = store
            .tasks()
            .get_task(&initial_child.task_id)
            .expect("get failed child")
            .expect("failed child");
        assert_eq!(failed_child.status, TaskStatus::Failed);

        let first_evidence =
            parent_join_child_completion_evidence(&store, &failed_child).expect("first evidence");
        assert!(first_evidence.summary.contains("failed_child task_id="));
        assert!(first_evidence
            .summary
            .contains("failure_result_fingerprint=sha256:"));
        let (first_fingerprint, _) = parent_join_child_completion_fingerprint(&[first_evidence]);

        store
            .tasks()
            .append_task_event_with_payload(
                &failed_child,
                LedgerEventKind::LlmRequestFailed,
                Some(json!({
                    "provider": "OpenAiCompatible",
                    "model": "<none>",
                    "reason": "different sanitized failed child outcome",
                    "strict": true,
                    "sensitive_guard": "off"
                })),
            )
            .expect("append different failed outcome");
        let second_evidence =
            parent_join_child_completion_evidence(&store, &failed_child).expect("second evidence");
        let (second_fingerprint, _) = parent_join_child_completion_fingerprint(&[second_evidence]);
        assert_ne!(first_fingerprint, second_fingerprint);

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        clear_llm_env_for_test();
    }

