    #[test]
    fn proposal_apply_transaction_recovery_mutates_unrecovered_item_from_partial_evidence() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::write(temp.path().join("README.md"), "updated README").expect("write readme");
        std::fs::write(temp.path().join("NOTES.md"), "original notes").expect("write notes");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        clear_llm_env_for_test();

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Recover two-file update","mode_id":"implementer"}}"#,
        );
        let run_id = start.result.expect("start result")["run_id"]
            .as_str()
            .unwrap()
            .to_string();
        let store = BrownieStore::from_env_or_cwd().expect("store");
        let task = store
            .tasks()
            .get_task_by_run_id(&run_id)
            .expect("task lookup")
            .expect("task");
        append_generated_patch_proposal(
            &store,
            &task,
            "proposal_recovery_notes",
            "NOTES.md",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            "updated notes",
        );
        let approve = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"proposal.approve","params":{{"run_id":"{run_id}","proposal_id":"proposal_recovery_notes","reason":"approved"}}}}"#
        ));
        assert!(approve.error.is_none());
        let notes_preflight = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"proposal.preflight","params":{{"run_id":"{run_id}","proposal_id":"proposal_recovery_notes"}}}}"#
        ));
        let notes_hash = notes_preflight.result.expect("notes preflight")["snapshot"]
            ["file_sha256"]
            .as_str()
            .unwrap()
            .to_string();
        let updated_readme_hash = format!("sha256:{}", hex_sha256(b"updated README"));
        let source_payload = partial_transaction_source_payload(
            "proposal_recovery_source",
            "apply_source_partial",
            "apply_tx_source_partial",
            "proposal_recovery_readme",
            "proposal_recovery_notes",
            &updated_readme_hash,
            &notes_hash,
        );
        let source_fingerprint =
            transaction_source_fingerprint(&source_payload).expect("source fingerprint");
        store
            .tasks()
            .append_task_event_with_payload(
                &task,
                LedgerEventKind::WorkspacePatchApplyResultRecorded,
                Some(source_payload),
            )
            .expect("append source apply");

        let apply = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":4,"method":"proposal.apply","params":{{"run_id":"{run_id}","proposal_id":"proposal_recovery_notes","authorize":true,"transaction_recovery_source":{{"source_run_id":"{run_id}","source_apply_id":"apply_source_partial","source_transaction_id":"apply_tx_source_partial","expected_source_transaction_fingerprint":"{source_fingerprint}"}},"transaction_items":[{{"proposal_id":"proposal_recovery_notes","expected_target_sha256":"{notes_hash}","replacement_content":"updated notes"}}]}}}}"#
        ));
        let result = apply.result.expect("recovery apply result");
        assert_eq!(result["apply_result"]["apply_status"], "Applied");
        assert_eq!(
            result["apply_result"]["transaction_recovery_status"],
            "Applied"
        );
        assert_eq!(
            std::fs::read_to_string(temp.path().join("README.md")).unwrap(),
            "updated README"
        );
        assert_eq!(
            std::fs::read_to_string(temp.path().join("NOTES.md")).unwrap(),
            "updated notes"
        );

        let events = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":5,"method":"run.events","params":{{"run_id":"{run_id}"}}}}"#
        ));
        let serialized_events =
            serde_json::to_string(&events.result.expect("events")["events"]).unwrap();
        for forbidden in [
            "raw_content",
            "full_content",
            "patch",
            "diff",
            "raw_input",
            "canonical_path",
            "absolute_path",
            "file_content",
            "original notes",
            "updated notes",
        ] {
            assert!(!serialized_events.contains(&format!(r#"\"{forbidden}\""#)));
        }

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        clear_llm_env_for_test();
    }

