    #[test]
    fn patch_proposal_validation_blocks_invalid_and_sensitive_cases() {
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::write(
            temp.path().join("README.md"),
            "old
",
        )
        .expect("write readme");
        std::fs::create_dir(temp.path().join("docs")).expect("mkdir");
        std::fs::write(
            temp.path().join("secret.txt"),
            "api_key=sk-existing
",
        )
        .expect("secret");
        let outside = tempfile::tempdir().expect("outside tempdir");
        std::fs::write(
            outside.path().join("outside.txt"),
            "outside workspace
",
        )
        .expect("outside file");
        #[cfg(unix)]
        std::os::unix::fs::symlink(
            outside.path().join("outside.txt"),
            temp.path().join("link.txt"),
        )
        .expect("symlink");
        #[cfg(unix)]
        std::os::unix::fs::symlink(temp.path().join("docs"), temp.path().join("docs-link"))
            .expect("symlink parent");
        let store = BrownieStore::new(temp.path());

        let missing = build_workspace_patch_proposal(
            &store,
            "missing.md",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            "new
",
        );
        assert_eq!(missing.validation_status, "Invalid");
        assert_eq!(
            missing.validation_reason,
            Some("target file does not exist")
        );

        let directory = build_workspace_patch_proposal(
            &store,
            "docs",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            "new
",
        );
        assert_eq!(directory.validation_status, "Invalid");
        assert_eq!(
            directory.validation_reason,
            Some("target path is not a file")
        );

        let create_file = build_workspace_patch_proposal(
            &store,
            "docs/new.md",
            WorkspacePatchOperation::CreateFile.as_str(),
            "new
",
        );
        assert_eq!(create_file.validation_status, "Valid");
        assert!(create_file
            .diff_preview
            .as_deref()
            .unwrap()
            .contains("+++ b/docs/new.md"));

        let create_existing = build_workspace_patch_proposal(
            &store,
            "README.md",
            WorkspacePatchOperation::CreateFile.as_str(),
            "new
",
        );
        assert_eq!(create_existing.validation_status, "Invalid");
        assert_eq!(
            create_existing.validation_reason,
            Some("target path already exists")
        );

        let create_missing_parent = build_workspace_patch_proposal(
            &store,
            "missing/new.md",
            WorkspacePatchOperation::CreateFile.as_str(),
            "new
",
        );
        assert_eq!(create_missing_parent.validation_status, "Invalid");
        assert_eq!(
            create_missing_parent.validation_reason,
            Some("target parent directory does not exist")
        );

        let delete_file = build_workspace_patch_proposal(
            &store,
            "README.md",
            WorkspacePatchOperation::DeleteFile.as_str(),
            "",
        );
        assert_eq!(delete_file.validation_status, "Valid");
        assert_eq!(delete_file.content_preview, "");
        assert_eq!(delete_file.content_chars, 0);
        assert!(delete_file
            .diff_preview
            .as_deref()
            .unwrap()
            .contains("--- a/README.md"));
        assert!(delete_file
            .diff_preview
            .as_deref()
            .unwrap()
            .contains("-old"));

        let delete_with_content = build_workspace_patch_proposal(
            &store,
            "README.md",
            WorkspacePatchOperation::DeleteFile.as_str(),
            "new\n",
        );
        assert_eq!(delete_with_content.validation_status, "Invalid");
        assert_eq!(
            delete_with_content.validation_reason,
            Some("delete_file operation must not include content")
        );

        let delete_missing = build_workspace_patch_proposal(
            &store,
            "missing.md",
            WorkspacePatchOperation::DeleteFile.as_str(),
            "",
        );
        assert_eq!(delete_missing.validation_status, "Invalid");
        assert_eq!(
            delete_missing.validation_reason,
            Some("target file does not exist")
        );

        let delete_directory = build_workspace_patch_proposal(
            &store,
            "docs",
            WorkspacePatchOperation::DeleteFile.as_str(),
            "",
        );
        assert_eq!(delete_directory.validation_status, "Invalid");
        assert_eq!(
            delete_directory.validation_reason,
            Some("target path is not a file")
        );

        #[cfg(unix)]
        {
            let create_target_symlink = build_workspace_patch_proposal(
                &store,
                "link.txt",
                WorkspacePatchOperation::CreateFile.as_str(),
                "new
",
            );
            assert_eq!(create_target_symlink.validation_status, "Invalid");
            assert_eq!(
                create_target_symlink.validation_reason,
                Some("target path already exists")
            );

            let create_parent_symlink = build_workspace_patch_proposal(
                &store,
                "docs-link/new.md",
                WorkspacePatchOperation::CreateFile.as_str(),
                "new
",
            );
            assert_eq!(create_parent_symlink.validation_status, "Invalid");
            assert_eq!(
                create_parent_symlink.validation_reason,
                Some("target parent directory is a symlink")
            );
            let delete_target_symlink = build_workspace_patch_proposal(
                &store,
                "link.txt",
                WorkspacePatchOperation::DeleteFile.as_str(),
                "",
            );
            assert_eq!(delete_target_symlink.validation_status, "Invalid");
            assert_eq!(
                delete_target_symlink.validation_reason,
                Some("target path is a symlink")
            );
            assert_eq!(
                std::fs::read_to_string(outside.path().join("outside.txt")).unwrap(),
                "outside workspace
"
            );
        }

        let proposed_secret = build_workspace_patch_proposal(
            &store,
            "README.md",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            "sk-proposed
",
        );
        assert_eq!(proposed_secret.validation_status, "Blocked");
        assert_eq!(proposed_secret.content_preview, "[redacted]");
        assert!(proposed_secret.diff_preview.is_none());
        assert!(proposed_secret.diff_redacted);

        let existing_secret = build_workspace_patch_proposal(
            &store,
            "secret.txt",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            "safe
",
        );
        assert_eq!(existing_secret.validation_status, "Blocked");
        assert_eq!(
            existing_secret.validation_reason,
            Some("target file contains sensitive-like data")
        );
        assert!(existing_secret.diff_preview.is_none());
        assert!(existing_secret.diff_redacted);

        #[cfg(unix)]
        {
            let symlink_escape = build_workspace_patch_proposal(
                &store,
                "link.txt",
                WorkspacePatchOperation::ReplaceFile.as_str(),
                "safe
",
            );
            assert_eq!(symlink_escape.validation_status, "Invalid");
            assert_eq!(
                symlink_escape.validation_reason,
                Some("target path escapes workspace root")
            );
            assert!(symlink_escape.diff_preview.is_none());
        }

        let large = build_workspace_patch_proposal(
            &store,
            "README.md",
            WorkspacePatchOperation::ReplaceFile.as_str(),
            &"new line
"
            .repeat(1000),
        );
        assert_eq!(large.validation_status, "Valid");
        assert!(large.diff_truncated);
        assert!(large.diff_preview.unwrap().chars().count() <= DEFAULT_DIFF_PREVIEW_CHARS);
        assert_eq!(
            std::fs::read_to_string(temp.path().join("README.md")).unwrap(),
            "old
"
        );
    }

